CREATE OR REPLACE FUNCTION public.admin_inventory_set_stock_v1(p_actor_id uuid, p_product_id uuid, p_expected_stock integer, p_new_stock integer, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_current_stock integer;
  v_updated_at timestamptz;
begin
  if p_actor_id is null
     or not exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin') then
    raise exception 'Administrator access is required.' using errcode='42501';
  end if;
  if p_product_id is null or p_expected_stock is null or p_new_stock is null
     or p_expected_stock < 0 or p_new_stock < 0
     or p_expected_stock > 1000000000 or p_new_stock > 1000000000 then
    raise exception 'Invalid inventory update.' using errcode='22023';
  end if;

  -- Serialize changes per product and compare against the editor's last value.
  perform pg_advisory_xact_lock(hashtextextended('inventory-product:'||p_product_id::text,0));
  select coalesce(p.stock_quantity,0),p.updated_at
    into v_current_stock,v_updated_at
    from public.products p
    where p.id=p_product_id
    for update;
  if not found then
    raise exception 'Product not found.' using errcode='P0002';
  end if;
  if v_current_stock<>p_expected_stock then
    raise exception 'This stock level changed after you opened it. Reload before saving.' using errcode='40001';
  end if;

  if v_current_stock=p_new_stock then
    return jsonb_build_object('product_id',p_product_id,'stock_quantity',v_current_stock,'updated_at',v_updated_at,'unchanged',true);
  end if;

  update public.products p
     set stock_quantity=p_new_stock,
         updated_at=now()
   where p.id=p_product_id
   returning p.updated_at into v_updated_at;

  insert into public.inventory_adjustments(
    product_id,adjustment_type,quantity_change,previous_stock,new_stock,notes
  ) values (
    p_product_id,'manual_set',p_new_stock-v_current_stock,v_current_stock,p_new_stock,
    coalesce(nullif(trim(p_notes),''),'Stock updated from inventory admin.')
  );

  return jsonb_build_object('product_id',p_product_id,'stock_quantity',p_new_stock,'updated_at',v_updated_at,'unchanged',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_product_activate_drafts_v1(p_actor_id uuid, p_request_id uuid, p_lane text, p_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_receipt public.cms_save_receipts%rowtype;v_hash text;v_result jsonb;v_items jsonb;
begin
  if p_actor_id is null or p_request_id is null or not exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin') then raise exception 'Administrator access is required.' using errcode='42501';end if;
  if p_lane not in ('standard','hiphop','collection') or coalesce(cardinality(p_ids),0) not between 1 and 500 or cardinality(p_ids)<>cardinality(array(select distinct x from unnest(p_ids)x)) then raise exception 'Invalid draft activation request.' using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended('product-operation-request:'||p_actor_id||':'||p_request_id,0));
  v_hash:=md5(jsonb_build_object('lane',p_lane,'ids',p_ids)::text);
  select r.* into v_receipt from public.cms_save_receipts r where r.actor_id=p_actor_id and r.request_id=p_request_id;
  if found then if v_receipt.operation<>'product-activate-drafts-v1' or v_receipt.payload_hash<>v_hash then raise exception 'This request ID was already used.' using errcode='40001';end if;return v_receipt.result;end if;
  perform 1 from public.products p where p.id=any(p_ids) order by p.id for update;
  if (select count(*) from public.products p where p.id=any(p_ids))<>cardinality(p_ids) then raise exception 'A product was not found.' using errcode='P0002';end if;
  if exists(select 1 from public.products p where p.id=any(p_ids) and (coalesce(p.product_lane,'standard')<>p_lane or p.status<>'draft')) then raise exception 'A product is no longer an eligible draft.' using errcode='40001';end if;
  with updated as (update public.products p set status='active',updated_at=now() where p.id=any(p_ids) returning p.id,p.status)
  select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'status',u.status) order by u.id),'[]'::jsonb) into v_items from updated u;
  v_result:=jsonb_build_object('activatedCount',jsonb_array_length(v_items),'items',v_items);
  insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'product-activate-drafts-v1',v_hash,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.admin_product_bulk_delete_v1(p_actor_id uuid, p_request_id uuid, p_lane text, p_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_receipt public.cms_save_receipts%rowtype;v_hash text;v_result jsonb;v_items jsonb;
begin
  if p_actor_id is null or p_request_id is null or not exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin') then raise exception 'Administrator access is required.' using errcode='42501';end if;
  if p_lane not in ('standard','hiphop','collection') or coalesce(cardinality(p_ids),0) not between 1 and 500 or cardinality(p_ids)<>cardinality(array(select distinct x from unnest(p_ids)x)) then raise exception 'Invalid bulk deletion request.' using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended('product-operation-request:'||p_actor_id||':'||p_request_id,0));
  v_hash:=md5(jsonb_build_object('lane',p_lane,'ids',p_ids)::text);
  select r.* into v_receipt from public.cms_save_receipts r where r.actor_id=p_actor_id and r.request_id=p_request_id;
  if found then if v_receipt.operation<>'product-bulk-delete-v1' or v_receipt.payload_hash<>v_hash then raise exception 'This request ID was already used.' using errcode='40001';end if;return v_receipt.result;end if;
  perform 1 from public.products p where p.id=any(p_ids) order by p.id for update;
  if (select count(*) from public.products p where p.id=any(p_ids))<>cardinality(p_ids) then raise exception 'A product was not found.' using errcode='P0002';end if;
  if exists(select 1 from public.products p where p.id=any(p_ids) and coalesce(p.product_lane,'standard')<>p_lane) then raise exception 'A product is outside this lane.' using errcode='40001';end if;
  with deleted as (delete from public.products p where p.id=any(p_ids) returning p.id)
  select coalesce(jsonb_agg(to_jsonb(d.id) order by d.id),'[]'::jsonb) into v_items from deleted d;
  v_result:=jsonb_build_object('ok',true,'deletedCount',jsonb_array_length(v_items),'ids',v_items);
  insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'product-bulk-delete-v1',v_hash,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.admin_product_bulk_price_v1(p_actor_id uuid, p_request_id uuid, p_lane text, p_operation text, p_value numeric, p_ids uuid[], p_expected_prices jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt public.cms_save_receipts%rowtype;
  v_hash text;
  v_result jsonb;
  v_items jsonb;
begin
  if p_actor_id is null or p_request_id is null or not exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin') then
    raise exception 'Administrator access is required.' using errcode='42501';
  end if;
  if p_lane not in ('standard','hiphop','collection') or p_operation not in ('increase_amount','decrease_amount','increase_percent','decrease_percent')
     or p_value is null or p_value<=0 or p_value>1000000000
     or (p_operation like '%_percent' and p_value>1000)
     or (p_operation='decrease_percent' and p_value>=100)
     or coalesce(cardinality(p_ids),0) not between 1 and 500
     or cardinality(p_ids)<>cardinality(array(select distinct x from unnest(p_ids)x))
     or jsonb_typeof(p_expected_prices) is distinct from 'array'
     or jsonb_array_length(p_expected_prices)<>cardinality(p_ids) then
    raise exception 'Invalid bulk price request.' using errcode='22023';
  end if;
  if exists(select 1 from jsonb_array_elements(p_expected_prices)x where coalesce(x->>'id','')!~'^[0-9a-fA-F-]{36}$' or coalesce(x->>'price','')!~'^[0-9]+(\.[0-9]+)?$')
     or exists(select 1 from jsonb_array_elements(p_expected_prices)x group by x->>'id' having count(*)>1)
     or exists(select 1 from unnest(p_ids)i where not exists(select 1 from jsonb_array_elements(p_expected_prices)x where x->>'id'=i::text)) then
    raise exception 'Invalid price verification data.' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('product-operation-request:'||p_actor_id||':'||p_request_id,0));
  v_hash:=md5(jsonb_build_object('lane',p_lane,'operation',p_operation,'value',p_value,'ids',p_ids,'expected',p_expected_prices)::text);
  select r.* into v_receipt from public.cms_save_receipts r where r.actor_id=p_actor_id and r.request_id=p_request_id;
  if found then
    if v_receipt.operation<>'product-bulk-price-v1' or v_receipt.payload_hash<>v_hash then raise exception 'This request ID was already used.' using errcode='40001';end if;
    return v_receipt.result;
  end if;

  perform 1 from public.products p where p.id=any(p_ids) order by p.id for update;
  if (select count(*) from public.products p where p.id=any(p_ids))<>cardinality(p_ids) then raise exception 'A product was not found.' using errcode='P0002';end if;
  if exists(select 1 from public.products p where p.id=any(p_ids) and coalesce(p.product_lane,'standard')<>p_lane) then raise exception 'A product is outside this lane.' using errcode='40001';end if;
  if exists(
    select 1 from public.products p join jsonb_array_elements(p_expected_prices)x on x->>'id'=p.id::text
    where p.id=any(p_ids) and (p.base_price is null or p.base_price<=0 or round(p.base_price::numeric,2)<>round((x->>'price')::numeric,2))
  ) then raise exception 'A product price changed.' using errcode='40001';end if;
  if exists(
    select 1 from public.products p where p.id=any(p_ids) and (
      case when p_operation='increase_amount' then p.base_price+p_value
           when p_operation='decrease_amount' then p.base_price-p_value
           when p_operation='increase_percent' then p.base_price+(p.base_price*p_value/100)
           else p.base_price-(p.base_price*p_value/100) end
    ) not between 0.01 and 1000000000
  ) then raise exception 'The adjustment would create an invalid price.' using errcode='22023';end if;

  with updated as (
    update public.products p set
      base_price=round(case when p_operation='increase_amount' then p.base_price+p_value
                            when p_operation='decrease_amount' then p.base_price-p_value
                            when p_operation='increase_percent' then p.base_price+(p.base_price*p_value/100)
                            else p.base_price-(p.base_price*p_value/100) end,2),
      updated_at=now()
    where p.id=any(p_ids)
    returning p.id,p.base_price
  ) select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'price',u.base_price) order by u.id),'[]'::jsonb) into v_items from updated u;
  v_result:=jsonb_build_object('ok',true,'updatedCount',jsonb_array_length(v_items),'items',v_items);
  insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'product-bulk-price-v1',v_hash,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.admin_product_save_v1(p_actor_id uuid, p_product_id uuid, p_slug text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_product public.products%rowtype;
  v_product_id uuid;
  v_is_create boolean := p_product_id is null;
  v_row jsonb;
  v_child jsonb;
  v_id uuid;
  v_variant_id uuid;
  v_default_client_id text := p_payload->>'default_purity_price_id';
  v_default_purity_id uuid;
  v_first_purity_id uuid;
  v_keep_purity_ids uuid[] := '{}'::uuid[];
  v_keep_metal_ids uuid[] := '{}'::uuid[];
  v_keep_dropdown_ids uuid[] := '{}'::uuid[];
  v_keep_option_ids uuid[];
begin
  if p_actor_id is null or p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Invalid product save request.' using errcode = '22023';
  end if;
  if not exists (select 1 from public.profiles where id = p_actor_id and role = 'admin') then
    raise exception 'Administrator access is required.' using errcode = '42501';
  end if;

  if v_is_create then
    if nullif(btrim(p_slug), '') is null then
      raise exception 'A product URL is required.' using errcode = '22023';
    end if;
    insert into public.products (name, slug, sku, main_category_id, featured, status)
    values (
      p_payload->>'name', p_slug, p_payload->>'sku',
      (p_payload->>'main_category_id')::uuid,
      (p_payload->>'featured')::boolean,
      (p_payload->>'status')::public.product_status
    ) returning * into v_product;
    v_product_id := v_product.id;
  else
    select * into v_product from public.products where id = p_product_id for update;
    if not found then raise exception 'Product not found.' using errcode = 'P0002'; end if;
    v_product_id := p_product_id;
  end if;

  -- Clear the child FK before purity rows are reconciled. Any failure below rolls this
  -- and every other statement in this function back as one PostgreSQL transaction.
  update public.products set default_purity_price_id = null where id = v_product_id;

  update public.products set
    name = p_payload->>'name',
    sku = p_payload->>'sku',
    product_lane = p_payload->>'product_lane',
    detail_template = (p_payload->>'detail_template')::public.product_detail_template,
    main_category_id = (p_payload->>'main_category_id')::uuid,
    subcategory_id = nullif(p_payload->>'subcategory_id', '')::uuid,
    option_id = nullif(p_payload->>'option_id', '')::uuid,
    style_id = nullif(p_payload->>'style_id', '')::uuid,
    description = p_payload->>'description',
    tag_line = p_payload->>'tag_line',
    seo_title = p_payload->>'seo_title',
    seo_description = p_payload->>'seo_description',
    h1_title = p_payload->>'h1_title',
    base_price = nullif(p_payload->>'base_price', '')::numeric,
    discount_price = nullif(p_payload->>'discount_price', '')::numeric,
    gst_slab_id = nullif(p_payload->>'gst_slab_id', '')::uuid,
    stock_quantity = (p_payload->>'stock_quantity')::integer,
    allow_checkout = (p_payload->>'allow_checkout')::boolean,
    featured = (p_payload->>'featured')::boolean,
    status = (p_payload->>'status')::public.product_status,
    features = p_payload->'features',
    purity_values = p_payload->'purity_values',
    certificate_ids = p_payload->'certificate_ids',
    ring_size_ids = p_payload->'ring_size_ids',
    ring_enabled = (p_payload->>'ring_enabled')::boolean,
    custom_dropdowns_enabled = (p_payload->>'custom_dropdowns_enabled')::boolean,
    ring_category_id = case when (p_payload->>'ring_enabled')::boolean then nullif(p_payload->>'ring_category_id', '')::uuid else null end,
    fit_options = p_payload->'fit_options',
    fit_label = p_payload->>'fit_label',
    gemstone_label = p_payload->>'gemstone_label',
    shapes_enabled = (p_payload->>'shapes_enabled')::boolean,
    show_purity = (p_payload->>'show_purity')::boolean,
    engraving_enabled = (p_payload->>'engraving_enabled')::boolean,
    engraving_label = p_payload->>'engraving_label',
    shipping_rule_id = nullif(p_payload->>'shipping_rule_id', '')::uuid,
    care_warranty_rule_id = nullif(p_payload->>'care_warranty_rule_id', '')::uuid,
    shipping_enabled = (p_payload->>'shipping_enabled')::boolean,
    care_warranty_enabled = (p_payload->>'care_warranty_enabled')::boolean,
    shipping_override_enabled = (p_payload->>'shipping_override_enabled')::boolean,
    care_warranty_override_enabled = (p_payload->>'care_warranty_override_enabled')::boolean,
    shipping_title_override = p_payload->>'shipping_title_override',
    shipping_body_override = p_payload->>'shipping_body_override',
    care_warranty_title_override = p_payload->>'care_warranty_title_override',
    care_warranty_body_override = p_payload->>'care_warranty_body_override',
    specifications = p_payload->'specifications',
    product_details = p_payload->'product_details',
    detail_sections = p_payload->'detail_sections',
    image_1_path = p_payload->>'image_1_path',
    image_2_path = p_payload->>'image_2_path',
    image_3_path = p_payload->>'image_3_path',
    image_4_path = p_payload->>'image_4_path',
    image_1_alt = p_payload->>'image_1_alt',
    image_2_alt = p_payload->>'image_2_alt',
    image_3_alt = p_payload->>'image_3_alt',
    image_4_alt = p_payload->>'image_4_alt',
    video_path = p_payload->>'video_path',
    model_3d_url = p_payload->>'model_3d_url',
    show_image_1 = (p_payload->>'show_image_1')::boolean,
    show_image_2 = (p_payload->>'show_image_2')::boolean,
    show_image_3 = (p_payload->>'show_image_3')::boolean,
    show_image_4 = (p_payload->>'show_image_4')::boolean,
    show_video = (p_payload->>'show_video')::boolean,
    custom_order_enabled = (p_payload->>'custom_order_enabled')::boolean,
    ready_to_ship = (p_payload->>'ready_to_ship')::boolean,
    hiphop_badges = p_payload->'hiphop_badges',
    chain_length_options = p_payload->'chain_length_options',
    hiphop_carat_label = p_payload->>'hiphop_carat_label',
    hiphop_carat_values = p_payload->'hiphop_carat_values',
    gram_weight_label = p_payload->>'gram_weight_label',
    gram_weight_value = p_payload->>'gram_weight_value',
    updated_at = now()
  where id = v_product_id;


  -- Older deployments do not yet have this column. Preserve the previous route
  -- behavior: write it when present, while keeping saves compatible when absent.
  if exists (
    select 1 from pg_catalog.pg_attribute
    where attrelid = 'public.products'::regclass
      and attname = 'gemstone_value'
      and not attisdropped
  ) then
    execute 'update public.products set gemstone_value = $1 where id = $2'
      using p_payload->>'gemstone_value', v_product_id;
  end if;

  delete from public.product_metal_selections where product_id = v_product_id;
  for v_row in select value from jsonb_array_elements(p_payload->'metal_ids') loop
    insert into public.product_metal_selections(product_id, metal_id, sort_order)
    values(v_product_id, (v_row#>>'{}')::uuid, coalesce(array_length(v_keep_metal_ids, 1), 0) + 1);
    v_keep_metal_ids := array_append(v_keep_metal_ids, (v_row#>>'{}')::uuid);
  end loop;

  delete from public.product_stone_shapes where product_id = v_product_id;
  for v_row in select value from jsonb_array_elements(p_payload->'shape_ids') loop
    insert into public.product_stone_shapes(product_id, shape_id) values(v_product_id, (v_row#>>'{}')::uuid);
  end loop;

  -- Preserve existing purity row IDs when the submitted UUID belongs to this product;
  -- temporary client keys are mapped to newly generated database UUIDs.
  for v_row in select value from jsonb_array_elements(p_payload->'purity_prices') loop
    v_id := null;
    if coalesce(v_row->>'id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      select id into v_id from public.product_purity_prices
      where id = (v_row->>'id')::uuid and product_id = v_product_id;
    end if;
    if v_id is null then
      insert into public.product_purity_prices(product_id, purity_label, price, compare_at_price, sort_order)
      values(v_product_id, btrim(v_row->>'purity_label'), (v_row->>'price')::numeric,
        nullif(v_row->>'compare_at_price', '')::numeric, (v_row->>'sort_order')::integer)
      returning id into v_id;
    else
      update public.product_purity_prices set
        purity_label = btrim(v_row->>'purity_label'), price = (v_row->>'price')::numeric,
        compare_at_price = nullif(v_row->>'compare_at_price', '')::numeric,
        sort_order = (v_row->>'sort_order')::integer, updated_at = now()
      where id = v_id;
    end if;
    v_keep_purity_ids := array_append(v_keep_purity_ids, v_id);
    if v_first_purity_id is null then v_first_purity_id := v_id; end if;
    if v_default_client_id is not null and v_default_client_id = v_row->>'id' then v_default_purity_id := v_id; end if;
  end loop;
  delete from public.product_purity_prices
  where product_id = v_product_id and not (id = any(v_keep_purity_ids));
  update public.products set default_purity_price_id = coalesce(v_default_purity_id, v_first_purity_id)
  where id = v_product_id;

  -- Product-owned metal media is reconciled by reusable metal ID.
  for v_row in select value from jsonb_array_elements(p_payload->'metal_media') loop
    v_id := null;
    select id into v_id from public.product_metal_media
    where product_id = v_product_id and metal_id = (v_row->>'metal_id')::uuid;
    if v_id is null then
      insert into public.product_metal_media(product_id, metal_id, image_1_path, image_2_path, image_3_path, image_4_path, video_path, is_default_fallback)
      values(v_product_id, (v_row->>'metal_id')::uuid, v_row->>'image_1_path', v_row->>'image_2_path',
        v_row->>'image_3_path', v_row->>'image_4_path', v_row->>'video_path', coalesce((v_row->>'is_default_fallback')::boolean, false));
    else
      update public.product_metal_media set image_1_path=v_row->>'image_1_path', image_2_path=v_row->>'image_2_path',
        image_3_path=v_row->>'image_3_path', image_4_path=v_row->>'image_4_path', video_path=v_row->>'video_path',
        is_default_fallback=coalesce((v_row->>'is_default_fallback')::boolean,false), updated_at=now() where id=v_id;
    end if;
  end loop;
  delete from public.product_metal_media where product_id=v_product_id and not (metal_id = any(
    array(select (value->>'metal_id')::uuid from jsonb_array_elements(p_payload->'metal_media'))));

  delete from public.product_material_value_selections where product_id=v_product_id;
  for v_row in select value from jsonb_array_elements(p_payload->'material_value_ids') loop
    insert into public.product_material_value_selections(product_id,material_value_id,sort_order)
    values(v_product_id,(v_row#>>'{}')::uuid,
      (select count(*)+1 from public.product_material_value_selections where product_id=v_product_id));
  end loop;

  delete from public.product_subcategory_links where product_id=v_product_id;
  if p_payload->>'subcategory_id' is not null then
    insert into public.product_subcategory_links(product_id,subcategory_id,is_primary,sort_order)
    values(v_product_id,(p_payload->>'subcategory_id')::uuid,true,1);
  end if;
  for v_row in select value from jsonb_array_elements(p_payload->'linked_subcategory_ids') loop
    insert into public.product_subcategory_links(product_id,subcategory_id,is_primary,sort_order)
    values(v_product_id,(v_row#>>'{}')::uuid,false,
      (select count(*)+1 from public.product_subcategory_links where product_id=v_product_id));
  end loop;

  delete from public.product_option_links where product_id=v_product_id;
  if p_payload->>'option_id' is not null then
    insert into public.product_option_links(product_id,option_id,is_primary,sort_order)
    values(v_product_id,(p_payload->>'option_id')::uuid,true,1);
  end if;
  for v_row in select value from jsonb_array_elements(p_payload->'linked_option_ids') loop
    insert into public.product_option_links(product_id,option_id,is_primary,sort_order)
    values(v_product_id,(v_row#>>'{}')::uuid,false,
      (select count(*)+1 from public.product_option_links where product_id=v_product_id));
  end loop;

  -- Preserve variant IDs by (product, metal), as the application did before the RPC.
  for v_row in select value from jsonb_array_elements(p_payload->'metal_variants') loop
    select id into v_variant_id from public.product_metal_variants
    where product_id=v_product_id and metal_id=(v_row->>'metal_id')::uuid;
    if v_variant_id is null then
      insert into public.product_metal_variants(product_id,metal_id,price,is_default,sort_order)
      values(v_product_id,(v_row->>'metal_id')::uuid,(v_row->>'price')::numeric,
        (v_row->>'is_default')::boolean,(v_row->>'sort_order')::integer) returning id into v_variant_id;
    else
      update public.product_metal_variants set price=(v_row->>'price')::numeric,
        is_default=(v_row->>'is_default')::boolean, sort_order=(v_row->>'sort_order')::integer,
        updated_at=now() where id=v_variant_id;
    end if;
  end loop;
  delete from public.product_metal_variants where product_id=v_product_id and not (metal_id = any(
    array(select (value->>'metal_id')::uuid from jsonb_array_elements(p_payload->'metal_variants'))));

  delete from public.product_variant_media_items where product_id=v_product_id;
  for v_row in select value from jsonb_array_elements(p_payload->'default_variant_media_items') loop
    insert into public.product_variant_media_items(product_id,variant_id,media_type,media_path,alt_text,sort_order,is_default_fallback)
    values(v_product_id,null,v_row->>'media_type',btrim(v_row->>'media_path'),nullif(btrim(v_row->>'alt_text'),''),
      (v_row->>'sort_order')::integer,true);
  end loop;
  for v_row in select value from jsonb_array_elements(p_payload->'metal_variants') loop
    select id into v_variant_id from public.product_metal_variants
    where product_id=v_product_id and metal_id=(v_row->>'metal_id')::uuid;
    for v_child in select value from jsonb_array_elements(coalesce(v_row->'media_items','[]'::jsonb)) loop
      if nullif(btrim(v_child->>'media_path'),'') is not null then
        insert into public.product_variant_media_items(product_id,variant_id,media_type,media_path,alt_text,sort_order,is_default_fallback)
        values(v_product_id,v_variant_id,v_child->>'media_type',btrim(v_child->>'media_path'),nullif(btrim(v_child->>'alt_text'),''),
          (v_child->>'sort_order')::integer,false);
      end if;
    end loop;
  end loop;

  delete from public.product_faq_items where product_id=v_product_id;
  for v_row in select value from jsonb_array_elements(p_payload->'faq_items') loop
    if nullif(btrim(v_row->>'question'),'') is not null and nullif(btrim(v_row->>'answer'),'') is not null then
      insert into public.product_faq_items(product_id,question,answer,sort_order,is_active,source)
      values(v_product_id,btrim(v_row->>'question'),btrim(v_row->>'answer'),(v_row->>'sort_order')::integer,
        (v_row->>'is_active')::boolean,coalesce(nullif(v_row->>'source',''),'admin'));
    end if;
  end loop;

  -- Disabled custom dropdowns remain stored but inactive through the products flag,
  -- matching the pre-RPC behavior. Enabled submissions reconcile owned rows by ID.
  if (p_payload->>'custom_dropdowns_enabled')::boolean then
    for v_row in select value from jsonb_array_elements(p_payload->'custom_dropdowns') loop
      v_id := (v_row->>'id')::uuid;
      if exists(select 1 from public.product_custom_dropdowns where id=v_id and product_id<>v_product_id) then
        raise exception 'Custom dropdown belongs to another product.' using errcode='40001';
      end if;
      insert into public.product_custom_dropdowns(id,product_id,name,label,is_enabled,is_required,display_order)
      values(v_id,v_product_id,v_row->>'name',v_row->>'label',(v_row->>'is_enabled')::boolean,
        (v_row->>'is_required')::boolean,(v_row->>'display_order')::integer)
      on conflict(id) do update set name=excluded.name,label=excluded.label,is_enabled=excluded.is_enabled,
        is_required=excluded.is_required,display_order=excluded.display_order,updated_at=now();
      v_keep_dropdown_ids := array_append(v_keep_dropdown_ids,v_id);
      v_keep_option_ids := '{}'::uuid[];
      for v_child in select value from jsonb_array_elements(v_row->'options') loop
        if exists(select 1 from public.product_custom_dropdown_options where id=(v_child->>'id')::uuid and dropdown_id<>v_id) then
          raise exception 'Custom dropdown option belongs to another dropdown.' using errcode='40001';
        end if;
        insert into public.product_custom_dropdown_options(id,dropdown_id,label,value,is_enabled,display_order)
        values((v_child->>'id')::uuid,v_id,v_child->>'label',v_child->>'value',(v_child->>'is_enabled')::boolean,
          (v_child->>'display_order')::integer)
        on conflict(id) do update set label=excluded.label,value=excluded.value,is_enabled=excluded.is_enabled,
          display_order=excluded.display_order,updated_at=now();
        v_keep_option_ids := array_append(v_keep_option_ids,(v_child->>'id')::uuid);
      end loop;
      delete from public.product_custom_dropdown_options where dropdown_id=v_id and not(id=any(v_keep_option_ids));
    end loop;
    delete from public.product_custom_dropdowns where product_id=v_product_id and not(id=any(v_keep_dropdown_ids));
  end if;

  select * into v_product from public.products where id=v_product_id;
  return jsonb_build_object('item',to_jsonb(v_product));
end;
$function$

CREATE OR REPLACE FUNCTION public.bespoke_form_save_v1(p_actor_id uuid, p_request_id uuid, p_expected_revision text, p_settings jsonb, p_lists jsonb, p_deleted_ids jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_before jsonb;
  v_result jsonb;
  v_receipt public.cms_save_receipts%rowtype;
  v_hash text;
  v_settings_id uuid;
  v_key text;
  v_table text;
  v_items jsonb;
  v_deleted jsonb;
  v_delete_ids uuid[];
  v_row jsonb;
  v_id uuid;
  v_invalid boolean;
begin
  if p_actor_id is null or p_request_id is null
     or not exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin') then
    raise exception 'Administrator access is required.' using errcode='42501';
  end if;
  if coalesce(p_expected_revision,'')!~'^[0-9a-f]{32}$'
     or jsonb_typeof(p_settings) is distinct from 'object'
     or jsonb_typeof(p_lists) is distinct from 'object'
     or jsonb_typeof(p_deleted_ids) is distinct from 'object' then
    raise exception 'Invalid Bespoke form save payload.' using errcode='22023';
  end if;
  if p_settings->>'status' not in ('active','hidden') then
    raise exception 'A valid form status is required.' using errcode='22023';
  end if;
  if not (p_lists ?& array['guarantees','pieceTypes','stoneOptions','caratOptions','metalOptions'])
     or (select count(*) from jsonb_object_keys(p_lists))<>5
     or not (p_deleted_ids ?& array['guarantees','pieceTypes','stoneOptions','caratOptions','metalOptions'])
     or (select count(*) from jsonb_object_keys(p_deleted_ids))<>5 then
    raise exception 'All Bespoke form option groups are required.' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('bespoke-form',0));
  perform pg_advisory_xact_lock(hashtextextended('bespoke-form-request:'||p_actor_id||':'||p_request_id,0));
  v_hash:=md5(jsonb_build_object(
    'revision',p_expected_revision,
    'settings',p_settings,
    'lists',p_lists,
    'deleted',p_deleted_ids
  )::text);

  select r.* into v_receipt
    from public.cms_save_receipts r
    where r.actor_id=p_actor_id and r.request_id=p_request_id;
  if found then
    if v_receipt.operation<>'bespoke-form-save' or v_receipt.payload_hash<>v_hash then
      raise exception 'This save request was already used for different changes.' using errcode='40001';
    end if;
    return v_receipt.result;
  end if;

  v_before:=public.bespoke_form_snapshot_v1();
  if v_before->>'revision'<>p_expected_revision then
    raise exception 'The Bespoke form changed since you opened it. Reload before saving.' using errcode='40001';
  end if;

  v_settings_id:=nullif(v_before->'settings'->>'id','')::uuid;
  if nullif(p_settings->>'id','') is not null
     and nullif(p_settings->>'id','')::uuid is distinct from v_settings_id then
    raise exception 'The Bespoke form settings ID is invalid.' using errcode='22023';
  end if;

  foreach v_key in array array['guarantees','pieceTypes','stoneOptions','caratOptions','metalOptions'] loop
    v_table:=case v_key
      when 'guarantees' then 'bespoke_form_guarantees'
      when 'pieceTypes' then 'bespoke_form_piece_types'
      when 'stoneOptions' then 'bespoke_form_stone_options'
      when 'caratOptions' then 'bespoke_form_carat_options'
      when 'metalOptions' then 'bespoke_form_metal_options'
    end;
    v_items:=p_lists->v_key;
    v_deleted:=p_deleted_ids->v_key;
    if jsonb_typeof(v_items) is distinct from 'array' or jsonb_typeof(v_deleted) is distinct from 'array' then
      raise exception 'Every Bespoke form option group must be a list.' using errcode='22023';
    end if;
    if exists(
      select 1 from jsonb_array_elements(v_items) x
      where nullif(x->>'id','') is not null
      group by x->>'id' having count(*)>1
    ) or (
      select count(*)<>count(distinct value) from jsonb_array_elements_text(v_deleted)
    ) then
      raise exception 'Option IDs must be unique.' using errcode='22023';
    end if;
    if exists(
      select 1 from jsonb_array_elements(v_items) x
      where nullif(trim(x->>'label'),'') is null
         or coalesce(x->>'display_order','')!~'^[0-9]+$'
         or x->>'status' not in ('active','hidden')
    ) then
      raise exception 'Every option requires a label, valid order, and valid status.' using errcode='22023';
    end if;

    execute format(
      'select exists(select 1 from jsonb_array_elements($1) x where nullif(x->>''id'','''') is not null and not exists(select 1 from public.%I t where t.id=(x->>''id'')::uuid))',
      v_table
    ) into v_invalid using v_items;
    if v_invalid then
      raise exception 'A Bespoke form option does not belong to its option group.' using errcode='22023';
    end if;

    execute format(
      'select exists(select 1 from jsonb_array_elements_text($1) d where not exists(select 1 from public.%I t where t.id=d::uuid))',
      v_table
    ) into v_invalid using v_deleted;
    if v_invalid then
      raise exception 'A deleted Bespoke form option is invalid.' using errcode='22023';
    end if;

    if exists(
      select 1 from jsonb_array_elements(v_items) x
      join jsonb_array_elements_text(v_deleted) d on d=x->>'id'
    ) then
      raise exception 'An option cannot be retained and deleted together.' using errcode='22023';
    end if;

    execute format(
      'select exists(select 1 from public.%I t where not exists(select 1 from jsonb_array_elements($1) x where nullif(x->>''id'','''')::uuid=t.id) and not exists(select 1 from jsonb_array_elements_text($2) d where d::uuid=t.id))',
      v_table
    ) into v_invalid using v_items,v_deleted;
    if v_invalid then
      raise exception 'Options may only be removed explicitly.' using errcode='22023';
    end if;
  end loop;

  if v_settings_id is null then
    insert into public.bespoke_form_settings(intro_heading,intro_subtitle,footer_note,status)
    values(
      nullif(trim(p_settings->>'intro_heading'),''),
      nullif(trim(p_settings->>'intro_subtitle'),''),
      nullif(trim(p_settings->>'footer_note'),''),
      (jsonb_populate_record(null::public.bespoke_form_settings,p_settings)).status
    ) returning id into v_settings_id;
  else
    update public.bespoke_form_settings
    set intro_heading=nullif(trim(p_settings->>'intro_heading'),''),
        intro_subtitle=nullif(trim(p_settings->>'intro_subtitle'),''),
        footer_note=nullif(trim(p_settings->>'footer_note'),''),
        status=(jsonb_populate_record(null::public.bespoke_form_settings,p_settings)).status,
        updated_at=now()
    where id=v_settings_id
      and (intro_heading,intro_subtitle,footer_note,status) is distinct from (
        nullif(trim(p_settings->>'intro_heading'),''),
        nullif(trim(p_settings->>'intro_subtitle'),''),
        nullif(trim(p_settings->>'footer_note'),''),
        (jsonb_populate_record(null::public.bespoke_form_settings,p_settings)).status
      );
  end if;

  foreach v_key in array array['guarantees','pieceTypes','stoneOptions','caratOptions','metalOptions'] loop
    v_table:=case v_key
      when 'guarantees' then 'bespoke_form_guarantees'
      when 'pieceTypes' then 'bespoke_form_piece_types'
      when 'stoneOptions' then 'bespoke_form_stone_options'
      when 'caratOptions' then 'bespoke_form_carat_options'
      when 'metalOptions' then 'bespoke_form_metal_options'
    end;
    v_items:=p_lists->v_key;
    v_deleted:=p_deleted_ids->v_key;
    select coalesce(array_agg(value::uuid),'{}'::uuid[])
      into v_delete_ids from jsonb_array_elements_text(v_deleted);
    execute format('delete from public.%I where id=any($1)',v_table) using v_delete_ids;

    for v_row in select * from jsonb_array_elements(v_items) loop
      v_id:=nullif(v_row->>'id','')::uuid;
      if v_id is null then
        execute format(
          'insert into public.%1$I(label,display_order,status) values(trim($1->>''label''),($1->>''display_order'')::integer,(jsonb_populate_record(null::public.%1$I,$1)).status)',
          v_table
        ) using v_row;
      else
        execute format(
          'update public.%1$I set label=trim($1->>''label''),display_order=($1->>''display_order'')::integer,status=(jsonb_populate_record(null::public.%1$I,$1)).status,updated_at=now() where id=$2 and (label,display_order,status) is distinct from (trim($1->>''label''),($1->>''display_order'')::integer,(jsonb_populate_record(null::public.%1$I,$1)).status)',
          v_table
        ) using v_row,v_id;
      end if;
    end loop;
  end loop;

  v_result:=public.bespoke_form_snapshot_v1();
  insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result)
  values(p_actor_id,p_request_id,'bespoke-form-save',v_hash,v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.bespoke_hero_save_v1(p_actor_id uuid, p_request_id uuid, p_expected_revision text, p_item jsonb, p_items jsonb, p_deleted_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_before jsonb;v_result jsonb;v_receipt public.cms_save_receipts%rowtype;v_hash text;v_parent_id uuid;v_row jsonb;v_id uuid;
begin
  if p_actor_id is null or p_request_id is null or not exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin') then raise exception 'Administrator access is required.' using errcode='42501';end if;
  if coalesce(p_expected_revision,'')!~'^[0-9a-f]{32}$' or jsonb_typeof(p_item) is distinct from 'object' or jsonb_typeof(p_items) is distinct from 'array' then raise exception 'Invalid Bespoke Hero save payload.' using errcode='22023';end if;
  if cardinality(p_deleted_ids)<>cardinality(array(select distinct x from unnest(p_deleted_ids)x)) then raise exception 'Deleted slide IDs must be unique.' using errcode='22023';end if;
  if nullif(trim(p_item->>'heading_line_1'),'') is null or p_item->>'status' not in ('active','hidden') then raise exception 'The primary heading and a valid status are required.' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(p_items)x where nullif(x->>'id','') is not null group by x->>'id' having count(*)>1) then raise exception 'Slide IDs must be unique.' using errcode='22023';end if;

  perform pg_advisory_xact_lock(hashtextextended('bespoke-hero',0));
  perform pg_advisory_xact_lock(hashtextextended('bespoke-hero-request:'||p_actor_id||':'||p_request_id,0));
  v_hash:=md5(jsonb_build_object('revision',p_expected_revision,'item',p_item,'items',p_items,'deleted',p_deleted_ids)::text);
  select r.* into v_receipt from public.cms_save_receipts r where r.actor_id=p_actor_id and r.request_id=p_request_id;
  if found then if v_receipt.operation<>'bespoke-hero-save' or v_receipt.payload_hash<>v_hash then raise exception 'This save request was already used for different changes.' using errcode='40001';end if;return v_receipt.result;end if;
  v_before:=public.bespoke_hero_snapshot_v1();
  if v_before->>'revision'<>p_expected_revision then raise exception 'The Bespoke Hero changed since you opened it. Reload before saving.' using errcode='40001';end if;
  v_parent_id:=nullif(v_before->'item'->>'id','')::uuid;
  if nullif(p_item->>'id','') is not null and nullif(p_item->>'id','')::uuid is distinct from v_parent_id then raise exception 'The Bespoke Hero ID is invalid.' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(p_items)x where nullif(x->>'id','') is not null and not exists(select 1 from public.bespoke_hero_slider_items s where s.id=(x->>'id')::uuid and s.hero_id=v_parent_id)) then raise exception 'A slide does not belong to this hero.' using errcode='22023';end if;
  if exists(select 1 from public.bespoke_hero_slider_items s where s.hero_id=v_parent_id and not(s.id=any(p_deleted_ids)) and not exists(select 1 from jsonb_array_elements(p_items)x where nullif(x->>'id','')::uuid=s.id)) then raise exception 'Slides may only be removed explicitly.' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(p_items)x where nullif(trim(x->>'image_path'),'') is null or nullif(trim(x->>'button_text'),'') is null or nullif(trim(x->>'button_link'),'') is null or coalesce((x->>'sort_order')::integer,0)<1) then raise exception 'Every slide requires an image, button text, button link, and valid order.' using errcode='22023';end if;

  if v_parent_id is null then
    insert into public.bespoke_hero_content(badge_text,eyebrow,heading_line_1,heading_line_2,subtitle,primary_cta_label,primary_cta_action,secondary_cta_label,secondary_cta_action,slider_enabled,status)
    values(nullif(trim(p_item->>'badge_text'),''),nullif(trim(p_item->>'eyebrow'),''),trim(p_item->>'heading_line_1'),nullif(trim(p_item->>'heading_line_2'),''),nullif(trim(p_item->>'subtitle'),''),nullif(trim(p_item->>'primary_cta_label'),''),nullif(trim(p_item->>'primary_cta_action'),''),nullif(trim(p_item->>'secondary_cta_label'),''),nullif(trim(p_item->>'secondary_cta_action'),''),(p_item->>'slider_enabled')::boolean,(jsonb_populate_record(null::public.bespoke_hero_content,p_item)).status) returning id into v_parent_id;
  else
    update public.bespoke_hero_content set badge_text=nullif(trim(p_item->>'badge_text'),''),eyebrow=nullif(trim(p_item->>'eyebrow'),''),heading_line_1=trim(p_item->>'heading_line_1'),heading_line_2=nullif(trim(p_item->>'heading_line_2'),''),subtitle=nullif(trim(p_item->>'subtitle'),''),primary_cta_label=nullif(trim(p_item->>'primary_cta_label'),''),primary_cta_action=nullif(trim(p_item->>'primary_cta_action'),''),secondary_cta_label=nullif(trim(p_item->>'secondary_cta_label'),''),secondary_cta_action=nullif(trim(p_item->>'secondary_cta_action'),''),slider_enabled=(p_item->>'slider_enabled')::boolean,status=(jsonb_populate_record(null::public.bespoke_hero_content,p_item)).status,updated_at=now()
    where id=v_parent_id and (badge_text,eyebrow,heading_line_1,heading_line_2,subtitle,primary_cta_label,primary_cta_action,secondary_cta_label,secondary_cta_action,slider_enabled,status) is distinct from (nullif(trim(p_item->>'badge_text'),''),nullif(trim(p_item->>'eyebrow'),''),trim(p_item->>'heading_line_1'),nullif(trim(p_item->>'heading_line_2'),''),nullif(trim(p_item->>'subtitle'),''),nullif(trim(p_item->>'primary_cta_label'),''),nullif(trim(p_item->>'primary_cta_action'),''),nullif(trim(p_item->>'secondary_cta_label'),''),nullif(trim(p_item->>'secondary_cta_action'),''),(p_item->>'slider_enabled')::boolean,(jsonb_populate_record(null::public.bespoke_hero_content,p_item)).status);
  end if;
  delete from public.bespoke_hero_slider_items where hero_id=v_parent_id and id=any(p_deleted_ids);
  for v_row in select * from jsonb_array_elements(p_items) loop
    v_id:=nullif(v_row->>'id','')::uuid;
    if v_id is null then insert into public.bespoke_hero_slider_items(hero_id,sort_order,image_path,mobile_image_path,button_text,button_link) values(v_parent_id,(v_row->>'sort_order')::integer,trim(v_row->>'image_path'),nullif(trim(v_row->>'mobile_image_path'),''),trim(v_row->>'button_text'),trim(v_row->>'button_link'));
    else update public.bespoke_hero_slider_items set sort_order=(v_row->>'sort_order')::integer,image_path=trim(v_row->>'image_path'),mobile_image_path=nullif(trim(v_row->>'mobile_image_path'),''),button_text=trim(v_row->>'button_text'),button_link=trim(v_row->>'button_link'),updated_at=now() where id=v_id and hero_id=v_parent_id and (sort_order,image_path,mobile_image_path,button_text,button_link) is distinct from ((v_row->>'sort_order')::integer,trim(v_row->>'image_path'),nullif(trim(v_row->>'mobile_image_path'),''),trim(v_row->>'button_text'),trim(v_row->>'button_link'));end if;
  end loop;
  v_result:=public.bespoke_hero_snapshot_v1();
  insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'bespoke-hero-save',v_hash,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.bespoke_hero_snapshot_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_parent jsonb; v_parent_id uuid; v_items jsonb:='[]'::jsonb; v_content jsonb;
begin
  select x.id,to_jsonb(x)-'created_at'-'updated_at' into v_parent_id,v_parent from public.bespoke_hero_content x order by x.updated_at desc,x.id limit 1;
  if v_parent_id is not null then
