  v_result:=jsonb_build_object('ok',true,'id',p_id);insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'catalog-hierarchy-delete-'||p_kind,v_hash,v_result);return v_result;
