CREATE OR REPLACE FUNCTION public.catalog_hierarchy_list_v1(p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_items jsonb;
begin
  case p_kind
    when 'category' then select coalesce(jsonb_agg((to_jsonb(x)-'created_at'-'updated_at')||jsonb_build_object('_revision',md5((to_jsonb(x)-'created_at'-'updated_at')::text)) order by x.display_order,x.name,x.id),'[]') into v_items from public.catalog_categories x;
    when 'subcategory' then select coalesce(jsonb_agg((to_jsonb(x)-'created_at'-'updated_at')||jsonb_build_object('_revision',md5((to_jsonb(x)-'created_at'-'updated_at')::text)) order by x.category_id,x.display_order,x.name,x.id),'[]') into v_items from public.catalog_subcategories x;
