CREATE OR REPLACE FUNCTION public.catalog_hierarchy_row_v1(p_kind text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_item jsonb;v_revision text;
begin
  case p_kind
    when 'category' then select to_jsonb(x) into v_item from public.catalog_categories x where x.id=p_id;
    when 'subcategory' then select to_jsonb(x) into v_item from public.catalog_subcategories x where x.id=p_id;
    when 'option' then select to_jsonb(x) into v_item from public.catalog_options x where x.id=p_id;
    else raise exception 'Unsupported catalog hierarchy type.' using errcode='22023';
  end case;
  v_revision:=md5(coalesce((v_item-'created_at'-'updated_at')::text,'null'));
  return jsonb_build_object('item',case when v_item is null then null else (v_item-'created_at'-'updated_at')||jsonb_build_object('_revision',v_revision) end,'revision',v_revision);
end $function$

