      if exists(select 1 from public.catalog_options x where x.subcategory_id=v_parent and (lower(x.name)=lower(v_name) or x.slug=v_slug) and (p_id is null or x.id<>p_id)) then raise exception 'An option with this name or slug already exists in the subcategory.' using errcode='23505';end if;
      if p_id is null then insert into public.catalog_options(subcategory_id,name,slug,icon_svg_path,image_path,image_alt,display_order,status) values(v_parent,v_name,v_slug,nullif(trim(p_item->>'icon_svg_path'),''),coalesce(nullif(trim(p_item->>'image_path'),''),nullif(trim(p_item->>'icon_svg_path'),'')),nullif(trim(p_item->>'image_alt'),''),v_order,v_status::public.catalog_status) returning id into v_id;
      else select subcategory_id into v_old_parent from public.catalog_options where id=p_id;if v_old_parent<>v_parent and (exists(select 1 from public.products x where x.option_id=p_id) or exists(select 1 from public.product_option_links x where x.option_id=p_id) or exists(select 1 from public.product_style_selections x where x.option_id=p_id) or exists(select 1 from public.homepage_shop_by_category_items x where x.option_id=p_id)) then raise exception 'A referenced option cannot be moved to another subcategory.' using errcode='P0001';end if;update public.catalog_options x set subcategory_id=v_parent,name=v_name,slug=v_slug,icon_svg_path=nullif(trim(p_item->>'icon_svg_path'),''),image_path=nullif(trim(p_item->>'image_path'),''),image_alt=nullif(trim(p_item->>'image_alt'),''),display_order=v_order,status=v_status::public.catalog_status,updated_at=now() where x.id=p_id;v_id:=p_id;
      end if;
    else raise exception 'Unsupported catalog hierarchy type.' using errcode='22023';
  end case;
  v_result:=public.catalog_hierarchy_row_v1(p_kind,v_id);insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'catalog-hierarchy-save-'||p_kind,v_hash,v_result);return v_result;
exception when unique_violation then raise exception 'A hierarchy record with the same name, code, or slug already exists.' using errcode='23505';end $function$

CREATE OR REPLACE FUNCTION public.catalog_master_list_v1(p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_items jsonb;
begin
  case p_kind
    when 'gst_slab' then select coalesce(jsonb_agg(to_jsonb(x) || jsonb_build_object('_revision', md5(to_jsonb(x)::text)) order by x.display_order, x.name, x.id), '[]'::jsonb) into v_items from public.catalog_gst_slabs x;
    when 'certificate' then select coalesce(jsonb_agg(to_jsonb(x) || jsonb_build_object('_revision', md5(to_jsonb(x)::text)) order by x.display_order, x.name, x.id), '[]'::jsonb) into v_items from public.catalog_certificates x;
    when 'material_value' then select coalesce(jsonb_agg(to_jsonb(x) || jsonb_build_object('_revision', md5(to_jsonb(x)::text)) order by x.display_order, x.name, x.id), '[]'::jsonb) into v_items from public.catalog_material_values x;
    when 'ring_size' then select coalesce(jsonb_agg(to_jsonb(x) || jsonb_build_object('_revision', md5(to_jsonb(x)::text)) order by x.display_order, x.name, x.id), '[]'::jsonb) into v_items from public.catalog_ring_sizes x;
    when 'stone_shape' then select coalesce(jsonb_agg(to_jsonb(x) || jsonb_build_object('_revision', md5(to_jsonb(x)::text)) order by x.display_order, x.name, x.id), '[]'::jsonb) into v_items from public.catalog_stone_shapes x;
    when 'style' then select coalesce(jsonb_agg(to_jsonb(x) || jsonb_build_object('_revision', md5(to_jsonb(x)::text)) order by x.display_order, x.name, x.id), '[]'::jsonb) into v_items from public.catalog_styles x;
    when 'content_rule' then select coalesce(jsonb_agg(to_jsonb(x) || jsonb_build_object('_revision', md5(to_jsonb(x)::text)) order by x.display_order, x.name, x.id), '[]'::jsonb) into v_items from public.product_content_rules x;
    else raise exception 'Unsupported catalog master type.' using errcode = '22023';
  end case;
  return coalesce(v_items, '[]'::jsonb);
end;
$function$

CREATE OR REPLACE FUNCTION public.catalog_master_row_v1(p_kind text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item jsonb;
begin
  case p_kind
    when 'gst_slab' then select to_jsonb(x) into v_item from public.catalog_gst_slabs x where x.id = p_id;
    when 'certificate' then select to_jsonb(x) into v_item from public.catalog_certificates x where x.id = p_id;
    when 'material_value' then select to_jsonb(x) into v_item from public.catalog_material_values x where x.id = p_id;
    when 'ring_size' then select to_jsonb(x) into v_item from public.catalog_ring_sizes x where x.id = p_id;
    when 'stone_shape' then select to_jsonb(x) into v_item from public.catalog_stone_shapes x where x.id = p_id;
    when 'style' then select to_jsonb(x) into v_item from public.catalog_styles x where x.id = p_id;
    when 'content_rule' then select to_jsonb(x) into v_item from public.product_content_rules x where x.id = p_id;
    else raise exception 'Unsupported catalog master type.' using errcode = '22023';
  end case;

  if v_item is null then
    return jsonb_build_object('item', null, 'revision', md5('null'));
  end if;
  return jsonb_build_object('item', v_item, 'revision', md5(v_item::text));
end;
$function$

CREATE OR REPLACE FUNCTION public.catalog_metal_delete_v1(p_actor_id uuid, p_request_id uuid, p_expected_revision text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_before jsonb;v_receipt public.cms_save_receipts%rowtype;v_hash text:=md5(jsonb_build_object('id',p_id,'revision',p_expected_revision)::text);v_usage int;v_result jsonb;
begin
  if not exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin') then raise exception 'Administrator access is required.' using errcode='42501';end if;if p_request_id is null or p_expected_revision is null or p_id is null then raise exception 'Invalid metal delete request.' using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended('catalog-request:'||p_actor_id||':'||p_request_id,0));select * into v_receipt from public.cms_save_receipts r where r.actor_id=p_actor_id and r.request_id=p_request_id;if found then if v_receipt.operation<>'catalog-metal-delete' or v_receipt.payload_hash<>v_hash then raise exception 'This request ID was already used.' using errcode='22023';end if;return v_receipt.result;end if;
  perform pg_advisory_xact_lock(hashtextextended('catalog-metal:'||p_id,0));v_before:=public.catalog_metal_row_v1(p_id);if v_before->'item'='null'::jsonb then raise exception 'Metal not found.' using errcode='P0002';end if;if v_before->>'revision'<>p_expected_revision then raise exception 'This metal changed since you opened it. Reload before deleting.' using errcode='40001';end if;
  select (select count(*) from public.product_metal_selections where metal_id=p_id)+(select count(*) from public.product_metal_variants where metal_id=p_id)+(select count(*) from public.product_metal_media where metal_id=p_id) into v_usage;if v_usage>0 then raise exception 'This metal is used in % product record(s). Hide it instead of deleting it.',v_usage using errcode='P0001';end if;
  delete from public.metal_composition_parts where metal_id=p_id;delete from public.catalog_metals where id=p_id;v_result:=jsonb_build_object('ok',true,'id',p_id);insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'catalog-metal-delete',v_hash,v_result);return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.catalog_metal_row_v1(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_parent jsonb;v_parts jsonb;v_revision text;
begin
  select to_jsonb(x)-'created_at'-'updated_at' into v_parent from public.catalog_metals x where x.id=p_id;
  if v_parent is null then return jsonb_build_object('item',null,'revision',md5('null'));end if;
  select coalesce(jsonb_agg(to_jsonb(x)-'created_at'-'metal_id' order by x.sort_order,x.id),'[]'::jsonb) into v_parts from public.metal_composition_parts x where x.metal_id=p_id;
  v_revision:=md5(jsonb_build_object('metal',v_parent,'parts',v_parts)::text);
  return jsonb_build_object('item',v_parent||jsonb_build_object('composition_parts',v_parts,'_revision',v_revision),'revision',v_revision);
end $function$

CREATE OR REPLACE FUNCTION public.catalog_metal_save_v1(p_actor_id uuid, p_request_id uuid, p_expected_revision text, p_id uuid, p_metal jsonb, p_parts jsonb, p_deleted_part_ids bigint[] DEFAULT '{}'::bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_before jsonb;v_result jsonb;v_receipt public.cms_save_receipts%rowtype;v_hash text:=md5(jsonb_build_object('id',p_id,'revision',p_expected_revision,'metal',p_metal,'parts',p_parts,'deleted',p_deleted_part_ids)::text);v_id uuid;v_part jsonb;v_part_id bigint;v_existing_ids bigint[];v_received_ids bigint[];v_missing_ids bigint[];v_name text:=trim(coalesce(p_metal->>'name',''));v_slug text:=lower(regexp_replace(regexp_replace(trim(coalesce(p_metal->>'slug','')),'[^a-zA-Z0-9]+','-','g'),'(^-|-$)','','g'));v_status text:=coalesce(p_metal->>'status','active');v_order int;
begin
  if not exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin') then raise exception 'Administrator access is required.' using errcode='42501';end if;
  if p_request_id is null or p_metal is null or jsonb_typeof(p_metal)<>'object' or p_parts is null or jsonb_typeof(p_parts)<>'array' then raise exception 'Invalid metal save request.' using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended('catalog-request:'||p_actor_id||':'||p_request_id,0));select * into v_receipt from public.cms_save_receipts r where r.actor_id=p_actor_id and r.request_id=p_request_id;
  if found then if v_receipt.operation<>'catalog-metal-save' or v_receipt.payload_hash<>v_hash then raise exception 'This request ID was already used for a different save.' using errcode='22023';end if;return v_receipt.result;end if;
  perform pg_advisory_xact_lock(hashtextextended('catalog-metal:'||coalesce(p_id::text,'new'),0));
  if p_id is null then if p_expected_revision is not null then raise exception 'New metals cannot include an existing revision.' using errcode='22023';end if;else v_before:=public.catalog_metal_row_v1(p_id);if v_before->'item'='null'::jsonb then raise exception 'Metal not found.' using errcode='P0002';end if;if p_expected_revision is null or v_before->>'revision'<>p_expected_revision then raise exception 'This metal changed since you opened it. Reload before saving.' using errcode='40001';end if;end if;
  if exists(select 1 from jsonb_object_keys(p_metal) k where k<>all(array['name','slug','purity_label','base_metal_name','display_label','is_combined_option','color_hex','composition_description','display_order','status'])) then raise exception 'Metal payload contains unsupported fields.' using errcode='22023';end if;
  begin v_order:=coalesce((p_metal->>'display_order')::int,0);exception when others then raise exception 'Display order must be a whole number.' using errcode='22023';end;
  if v_name='' or v_slug='' or v_status not in('active','hidden') or v_order<0 or v_order>1000000 then raise exception 'Invalid metal name, slug, status, or display order.' using errcode='22023';end if;
  if exists(select 1 from public.catalog_metals x where (lower(x.name)=lower(v_name) or x.slug=v_slug) and (p_id is null or x.id<>p_id)) then raise exception 'A metal with this name or slug already exists.' using errcode='23505';end if;
  if exists(select 1 from jsonb_array_elements(p_parts) x where jsonb_typeof(x)<>'object' or exists(select 1 from jsonb_object_keys(x) k where k<>all(array['id','part_name','percentage','color_hex','sort_order']))) then raise exception 'Composition payload contains unsupported fields.' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(p_parts) x where trim(coalesce(x->>'part_name',''))='' or (x->>'percentage') is null or (x->>'percentage')::numeric<0 or (x->>'percentage')::numeric>100 or coalesce((x->>'sort_order')::int,0)<0) then raise exception 'Each composition value needs a name, percentage from 0 to 100, and valid order.' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(p_parts) x group by lower(trim(x->>'part_name')) having count(*)>1) then raise exception 'Composition value names must be unique within a metal.' using errcode='23505';end if;
  select coalesce(array_agg(x.id order by x.id),'{}'::bigint[]) into v_existing_ids from public.metal_composition_parts x where x.metal_id=p_id;
  begin select coalesce(array_agg((x->>'id')::bigint order by (x->>'id')::bigint),'{}'::bigint[]) into v_received_ids from jsonb_array_elements(p_parts) x where x?'id';exception when others then raise exception 'Composition IDs must be valid numbers.' using errcode='22023';end;
  if cardinality(v_received_ids)<>cardinality(array(select distinct unnest(v_received_ids))) or cardinality(p_deleted_part_ids)<>cardinality(array(select distinct unnest(p_deleted_part_ids))) then raise exception 'Composition IDs must be unique.' using errcode='22023';end if;
  if exists(select 1 from unnest(v_received_ids) x where not(x=any(v_existing_ids))) or exists(select 1 from unnest(p_deleted_part_ids) x where not(x=any(v_existing_ids))) then raise exception 'A composition value does not belong to this metal.' using errcode='22023';end if;
  if exists(select 1 from unnest(v_received_ids) x where x=any(p_deleted_part_ids)) then raise exception 'A composition value cannot be retained and deleted.' using errcode='22023';end if;
  select coalesce(array_agg(x),'{}'::bigint[]) into v_missing_ids from unnest(v_existing_ids) x where not(x=any(v_received_ids)) and not(x=any(p_deleted_part_ids));if cardinality(v_missing_ids)>0 then raise exception 'Existing composition values may only be removed explicitly.' using errcode='22023';end if;
  if p_id is null then insert into public.catalog_metals(name,slug,purity_label,base_metal_name,display_label,is_combined_option,color_hex,composition_description,display_order,status) values(v_name,v_slug,nullif(trim(p_metal->>'purity_label'),''),nullif(trim(p_metal->>'base_metal_name'),''),nullif(trim(p_metal->>'display_label'),''),coalesce((p_metal->>'is_combined_option')::boolean,false),nullif(trim(p_metal->>'color_hex'),''),nullif(trim(p_metal->>'composition_description'),''),v_order,v_status::public.catalog_status) returning id into v_id;else update public.catalog_metals x set name=v_name,slug=v_slug,purity_label=nullif(trim(p_metal->>'purity_label'),''),base_metal_name=nullif(trim(p_metal->>'base_metal_name'),''),display_label=nullif(trim(p_metal->>'display_label'),''),is_combined_option=coalesce((p_metal->>'is_combined_option')::boolean,false),color_hex=nullif(trim(p_metal->>'color_hex'),''),composition_description=nullif(trim(p_metal->>'composition_description'),''),display_order=v_order,status=v_status::public.catalog_status,updated_at=now() where x.id=p_id;v_id:=p_id;end if;
  foreach v_part_id in array p_deleted_part_ids loop delete from public.metal_composition_parts x where x.id=v_part_id and x.metal_id=v_id;end loop;
  for v_part in select * from jsonb_array_elements(p_parts) loop if v_part?'id' then update public.metal_composition_parts x set part_name=trim(v_part->>'part_name'),percentage=(v_part->>'percentage')::numeric,color_hex=nullif(trim(v_part->>'color_hex'),''),sort_order=coalesce((v_part->>'sort_order')::int,0) where x.id=(v_part->>'id')::bigint and x.metal_id=v_id;else insert into public.metal_composition_parts(metal_id,part_name,percentage,color_hex,sort_order) values(v_id,trim(v_part->>'part_name'),(v_part->>'percentage')::numeric,nullif(trim(v_part->>'color_hex'),''),coalesce((v_part->>'sort_order')::int,0));end if;end loop;
  v_result:=public.catalog_metal_row_v1(v_id);insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'catalog-metal-save',v_hash,v_result);return v_result;
exception when unique_violation then raise exception 'A metal or composition value with this name or slug already exists.' using errcode='23505';end $function$

CREATE OR REPLACE FUNCTION public.catalog_navbar_source_delete_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if exists (
    select 1 from public.navbar_section_source_items source
    where source.source_kind = tg_argv[0] and source.source_item_id = old.id::text
  ) then
    raise exception 'This catalog value is still used by a navbar section.' using errcode = 'P0001';
  end if;
  return old;
end;
$function$

CREATE OR REPLACE FUNCTION public.catalog_ring_save_v1(p_actor_id uuid, p_request_id uuid, p_expected_revision text, p_categories jsonb, p_sizes jsonb, p_deleted_category_ids text[] DEFAULT '{}'::text[], p_deleted_size_ids text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_before jsonb;
  v_result jsonb;
  v_receipt public.cms_save_receipts%rowtype;
  v_hash text:=md5(jsonb_build_object('expected_revision',p_expected_revision,'categories',p_categories,'sizes',p_sizes,'deleted_category_ids',p_deleted_category_ids,'deleted_size_ids',p_deleted_size_ids)::text);
  v_item jsonb;
  v_id uuid;
  v_category_id uuid;
  v_existing_id uuid;
  v_name text;
  v_slug text;
  v_label text;
  v_order integer;
  v_status text;
  v_count integer;
begin
  if not exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin') then raise exception 'Administrator access is required.' using errcode='42501'; end if;
  if p_request_id is null or p_expected_revision is null or jsonb_typeof(p_categories)<>'array' or jsonb_typeof(p_sizes)<>'array' then raise exception 'Invalid ring catalog save request.' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('catalog-request:'||p_actor_id::text||':'||p_request_id::text,0));
  select * into v_receipt from public.cms_save_receipts r where r.actor_id=p_actor_id and r.request_id=p_request_id;
  if found then
    if v_receipt.operation<>'catalog-ring-save' or v_receipt.payload_hash<>v_hash then raise exception 'This request ID was already used for a different ring save.' using errcode='22023'; end if;
    return v_receipt.result;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('catalog-ring-state',0));
  v_before:=public.catalog_ring_snapshot_v1();
  if v_before->>'revision'<>p_expected_revision then raise exception 'The ring catalog changed since you opened it. Reload before saving.' using errcode='40001'; end if;

  if exists(select 1 from jsonb_array_elements(p_categories) x where jsonb_typeof(x)<>'object' or exists(select 1 from jsonb_object_keys(x) k where k<>all(array['id','name','slug','description','display_order','status','_revision']))) then raise exception 'Ring category payload contains unsupported fields.' using errcode='22023'; end if;
  if exists(select 1 from jsonb_array_elements(p_sizes) x where jsonb_typeof(x)<>'object' or exists(select 1 from jsonb_object_keys(x) k where k<>all(array['id','ring_category_id','size_label','size_value','display_order','status','_revision']))) then raise exception 'Ring size payload contains unsupported fields.' using errcode='22023'; end if;
  if coalesce(array_length(p_deleted_category_ids,1),0) <> (select count(*) from (select distinct x from unnest(coalesce(p_deleted_category_ids,'{}')) x) q) then raise exception 'Duplicate deleted category IDs are not allowed.' using errcode='22023'; end if;
  if coalesce(array_length(p_deleted_size_ids,1),0) <> (select count(*) from (select distinct x from unnest(coalesce(p_deleted_size_ids,'{}')) x) q) then raise exception 'Duplicate deleted size IDs are not allowed.' using errcode='22023'; end if;
  if exists(select 1 from unnest(coalesce(p_deleted_category_ids,'{}')) d where not exists(select 1 from public.catalog_ring_categories x where x.id::text=d)) then raise exception 'A deleted ring category does not exist.' using errcode='P0002'; end if;
  if exists(select 1 from unnest(coalesce(p_deleted_size_ids,'{}')) d where not exists(select 1 from public.catalog_ring_category_sizes x where x.id::text=d)) then raise exception 'A deleted ring size does not exist.' using errcode='P0002'; end if;

  if exists(select 1 from public.catalog_ring_categories x where not(x.id::text=any(coalesce(p_deleted_category_ids,'{}'))) and not exists(select 1 from jsonb_array_elements(p_categories) i where i->>'id'=x.id::text)) then raise exception 'Ring categories may only be removed explicitly.' using errcode='22023'; end if;
  if exists(select 1 from public.catalog_ring_category_sizes x where not(x.id::text=any(coalesce(p_deleted_size_ids,'{}'))) and not exists(select 1 from jsonb_array_elements(p_sizes) i where i->>'id'=x.id::text)) then raise exception 'Ring sizes may only be removed explicitly.' using errcode='22023'; end if;
  if exists(select 1 from jsonb_array_elements(p_categories) i where nullif(i->>'id','') is not null and i->>'id'=any(coalesce(p_deleted_category_ids,'{}'))) then raise exception 'A category cannot be retained and deleted.' using errcode='22023'; end if;
  if exists(select 1 from jsonb_array_elements(p_sizes) i where nullif(i->>'id','') is not null and i->>'id'=any(coalesce(p_deleted_size_ids,'{}'))) then raise exception 'A size cannot be retained and deleted.' using errcode='22023'; end if;

  for v_item in select * from jsonb_array_elements(p_categories) loop
    v_name:=trim(coalesce(v_item->>'name','')); v_slug:=lower(regexp_replace(regexp_replace(trim(coalesce(v_item->>'slug','')),'[^a-zA-Z0-9]+','-','g'),'(^-|-$)','','g')); v_status:=coalesce(v_item->>'status','active');
    begin v_order:=coalesce((v_item->>'display_order')::integer,0); exception when others then raise exception 'Ring category display order must be a whole number.' using errcode='22023'; end;
    if v_name='' or v_slug='' then raise exception 'Ring category name and slug are required.' using errcode='22023'; end if;
    if v_status not in ('active','hidden') or v_order<0 or v_order>1000000 then raise exception 'Invalid ring category status or display order.' using errcode='22023'; end if;
    if nullif(v_item->>'id','') is null then
      if exists(select 1 from public.catalog_ring_categories x where lower(x.name)=lower(v_name) or x.slug=v_slug) then raise exception 'A ring category with this name or slug already exists.' using errcode='23505'; end if;
      insert into public.catalog_ring_categories(name,slug,description,display_order,status) values(v_name,v_slug,nullif(trim(v_item->>'description'),''),v_order,v_status) returning id into v_id;
    else
      v_id:=(v_item->>'id')::uuid;
      if not exists(select 1 from public.catalog_ring_categories x where x.id=v_id) then raise exception 'Ring category not found.' using errcode='P0002'; end if;
      if exists(select 1 from public.catalog_ring_categories x where x.id<>v_id and (lower(x.name)=lower(v_name) or x.slug=v_slug)) then raise exception 'A ring category with this name or slug already exists.' using errcode='23505'; end if;
      update public.catalog_ring_categories x set name=v_name,slug=v_slug,description=nullif(trim(v_item->>'description'),''),display_order=v_order,status=v_status,updated_at=now() where x.id=v_id and (x.name,x.slug,x.description,x.display_order,x.status) is distinct from (v_name,v_slug,nullif(trim(v_item->>'description'),''),v_order,v_status);
    end if;
  end loop;

  for v_item in select * from jsonb_array_elements(p_sizes) loop
    v_label:=trim(coalesce(v_item->>'size_label','')); v_status:=coalesce(v_item->>'status','active'); v_category_id:=nullif(v_item->>'ring_category_id','')::uuid;
    begin v_order:=coalesce((v_item->>'display_order')::integer,0); exception when others then raise exception 'Ring size display order must be a whole number.' using errcode='22023'; end;
    if v_label='' or v_category_id is null or v_status not in ('active','hidden') or v_order<0 or v_order>1000000 then raise exception 'Invalid ring size details.' using errcode='22023'; end if;
    if not exists(select 1 from public.catalog_ring_categories x where x.id=v_category_id) then raise exception 'Every ring size must belong to an existing category.' using errcode='23503'; end if;
    if nullif(v_item->>'id','') is null then
      if exists(select 1 from public.catalog_ring_category_sizes x where x.ring_category_id=v_category_id and lower(x.size_label)=lower(v_label)) then raise exception 'A size with this label already exists in this ring category.' using errcode='23505'; end if;
      insert into public.catalog_ring_category_sizes(ring_category_id,size_label,size_value,display_order,status) values(v_category_id,v_label,nullif(trim(v_item->>'size_value'),''),v_order,v_status) returning id into v_id;
    else
      v_id:=(v_item->>'id')::uuid;
      if not exists(select 1 from public.catalog_ring_category_sizes x where x.id=v_id) then raise exception 'Ring size not found.' using errcode='P0002'; end if;
      if exists(select 1 from public.catalog_ring_category_sizes x where x.id<>v_id and x.ring_category_id=v_category_id and lower(x.size_label)=lower(v_label)) then raise exception 'A size with this label already exists in this ring category.' using errcode='23505'; end if;
      update public.catalog_ring_category_sizes x set ring_category_id=v_category_id,size_label=v_label,size_value=nullif(trim(v_item->>'size_value'),''),display_order=v_order,status=v_status,updated_at=now() where x.id=v_id and (x.ring_category_id,x.size_label,x.size_value,x.display_order,x.status) is distinct from (v_category_id,v_label,nullif(trim(v_item->>'size_value'),''),v_order,v_status);
    end if;
  end loop;

  if exists(select 1 from public.catalog_ring_categories x where x.id::text=any(coalesce(p_deleted_category_ids,'{}')) and exists(select 1 from public.products p where p.ring_category_id=x.id)) then raise exception 'A ring category is used by products. Hide it instead of deleting it.' using errcode='P0001'; end if;
  if exists(select 1 from public.catalog_ring_category_sizes x where x.id::text=any(coalesce(p_deleted_size_ids,'{}'))) then delete from public.catalog_ring_category_sizes x where x.id::text=any(coalesce(p_deleted_size_ids,'{}')); end if;
  if exists(select 1 from public.catalog_ring_category_sizes x where x.ring_category_id::text=any(coalesce(p_deleted_category_ids,'{}'))) then raise exception 'Delete the category sizes explicitly before deleting their ring category.' using errcode='P0001'; end if;
  delete from public.catalog_ring_categories x where x.id::text=any(coalesce(p_deleted_category_ids,'{}'));
  v_result:=public.catalog_ring_snapshot_v1();
  insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'catalog-ring-save',v_hash,v_result);
  return v_result;
exception when unique_violation then raise exception 'A ring category or size with the same name, slug, or label already exists.' using errcode='23505';
end;
$function$

CREATE OR REPLACE FUNCTION public.catalog_ring_snapshot_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_categories jsonb;
  v_sizes jsonb;
  v_state jsonb;
begin
  select coalesce(jsonb_agg((to_jsonb(x)-'created_at'-'updated_at') || jsonb_build_object('_revision', md5(to_jsonb(x)::text)) order by x.display_order, x.name, x.id), '[]'::jsonb) into v_categories from public.catalog_ring_categories x;
  select coalesce(jsonb_agg((to_jsonb(x)-'created_at'-'updated_at') || jsonb_build_object('_revision', md5(to_jsonb(x)::text)) order by x.ring_category_id, x.display_order, x.size_label, x.id), '[]'::jsonb) into v_sizes from public.catalog_ring_category_sizes x;
  v_state:=jsonb_build_object('categories',v_categories,'sizes',v_sizes);
  return v_state || jsonb_build_object('revision',md5(v_state::text));
end;
$function$

CREATE OR REPLACE FUNCTION public.catalog_save_master_v1(p_actor_id uuid, p_request_id uuid, p_expected_revision text, p_kind text, p_id uuid, p_item jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_before jsonb;
  v_result jsonb;
  v_receipt public.cms_save_receipts%rowtype;
  v_hash text := md5(jsonb_build_object('kind', p_kind, 'id', p_id, 'expected_revision', p_expected_revision, 'item', p_item)::text);
  v_id uuid;
  v_name text := trim(coalesce(p_item->>'name', ''));
  v_slug text := lower(regexp_replace(regexp_replace(trim(coalesce(p_item->>'slug', '')), '[^a-zA-Z0-9]+', '-', 'g'), '(^-|-$)', '', 'g'));
  v_status text := coalesce(p_item->>'status', 'active');
  v_order integer;
begin
  if not exists (select 1 from public.profiles p where p.id = p_actor_id and p.role = 'admin') then
    raise exception 'Administrator access is required.' using errcode = '42501';
  end if;
  if p_request_id is null or p_item is null or jsonb_typeof(p_item) <> 'object' then
    raise exception 'Invalid catalog save request.' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('catalog-request:' || p_actor_id::text || ':' || p_request_id::text, 0));
  select * into v_receipt from public.cms_save_receipts r where r.actor_id = p_actor_id and r.request_id = p_request_id;
  if found then
    if v_receipt.operation <> 'catalog-master-save-' || p_kind or v_receipt.payload_hash <> v_hash then
      raise exception 'This request ID was already used for a different save.' using errcode = '22023';
    end if;
    return v_receipt.result;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('catalog-master:' || p_kind || ':' || coalesce(p_id::text, 'new'), 0));
  if p_id is null then
    if p_expected_revision is not null then raise exception 'New records cannot have an existing revision.' using errcode = '22023'; end if;
  else
    v_before := public.catalog_master_row_v1(p_kind, p_id);
    if v_before->'item' = 'null'::jsonb then raise exception 'Catalog record not found.' using errcode = 'P0002'; end if;
    if p_expected_revision is null or v_before->>'revision' <> p_expected_revision then
      raise exception 'This record changed since you opened it. Reload before saving.' using errcode = '40001';
    end if;
  end if;

  if v_name = '' or length(v_name) > 200 then raise exception 'Name is required and must be 200 characters or fewer.' using errcode = '22023'; end if;
  if v_status not in ('active', 'hidden') then raise exception 'Status must be active or hidden.' using errcode = '22023'; end if;
  begin v_order := coalesce((p_item->>'display_order')::integer, 0); exception when others then raise exception 'Display order must be a whole number.' using errcode = '22023'; end;
  if v_order < 0 or v_order > 1000000 then raise exception 'Display order is outside the allowed range.' using errcode = '22023'; end if;

  case p_kind
    when 'gst_slab' then
      if exists(select 1 from jsonb_object_keys(p_item) k where k <> all(array['name','code','percentage','description','status','display_order'])) then raise exception 'GST payload contains unsupported fields.' using errcode='22023'; end if;
      if trim(coalesce(p_item->>'code','')) = '' or length(trim(p_item->>'code')) > 50 then raise exception 'GST code is required.' using errcode='22023'; end if;
      if exists(select 1 from public.catalog_gst_slabs x where (lower(x.name)=lower(v_name) or upper(x.code)=upper(trim(p_item->>'code'))) and (p_id is null or x.id<>p_id)) then raise exception 'A GST slab with this name or code already exists.' using errcode='23505'; end if;
      if (p_item->>'percentage')::numeric < 0 or (p_item->>'percentage')::numeric > 100 then raise exception 'GST percentage must be between 0 and 100.' using errcode='22023'; end if;
      if p_id is null then
        insert into public.catalog_gst_slabs(name,code,percentage,description,status,display_order) values(v_name,upper(trim(p_item->>'code')),(p_item->>'percentage')::numeric,nullif(trim(p_item->>'description'),''),v_status,v_order) returning id into v_id;
      else
        update public.catalog_gst_slabs x set name=v_name,code=upper(trim(p_item->>'code')),percentage=(p_item->>'percentage')::numeric,description=nullif(trim(p_item->>'description'),''),status=v_status,display_order=v_order,updated_at=now()
        where x.id=p_id and (x.name,x.code,x.percentage,x.description,x.status,x.display_order) is distinct from (v_name,upper(trim(p_item->>'code')),(p_item->>'percentage')::numeric,nullif(trim(p_item->>'description'),''),v_status,v_order); v_id:=p_id;
      end if;
    when 'certificate' then
      if exists(select 1 from jsonb_object_keys(p_item) k where k <> all(array['name','code','status','display_order'])) then raise exception 'Certificate payload contains unsupported fields.' using errcode='22023'; end if;
      if exists(select 1 from public.catalog_certificates x where (lower(x.name)=lower(v_name) or (nullif(trim(p_item->>'code'),'') is not null and upper(x.code)=upper(trim(p_item->>'code')))) and (p_id is null or x.id<>p_id)) then raise exception 'A certificate with this name or code already exists.' using errcode='23505'; end if;
      if p_id is null then
        v_slug:=lower(regexp_replace(regexp_replace(v_name,'[^a-zA-Z0-9]+','-','g'),'(^-|-$)','','g'));
        if v_slug='' then raise exception 'Name must contain letters or numbers.' using errcode='22023'; end if;
        insert into public.catalog_certificates(name,code,slug,status,display_order) values(v_name,nullif(upper(trim(p_item->>'code')),''),v_slug,v_status::public.catalog_status,v_order) returning id into v_id;
      else
        update public.catalog_certificates x set name=v_name,code=nullif(upper(trim(p_item->>'code')),''),status=v_status::public.catalog_status,display_order=v_order,updated_at=now()
        where x.id=p_id and (x.name,x.code,x.status,x.display_order) is distinct from (v_name,nullif(upper(trim(p_item->>'code')),''),v_status::public.catalog_status,v_order); v_id:=p_id;
      end if;
    when 'material_value' then
      if exists(select 1 from jsonb_object_keys(p_item) k where k <> all(array['name','slug','cta_mode','cta_label','status','display_order'])) then raise exception 'Material value payload contains unsupported fields.' using errcode='22023'; end if;
      if v_slug='' then raise exception 'Slug is required.' using errcode='22023'; end if;
      if exists(select 1 from public.catalog_material_values x where (lower(x.name)=lower(v_name) or x.slug=v_slug) and (p_id is null or x.id<>p_id)) then raise exception 'A material value with this name or slug already exists.' using errcode='23505'; end if;
      if coalesce(p_item->>'cta_mode','both') not in ('both','enquire_only','checkout_only') then raise exception 'Invalid CTA mode.' using errcode='22023'; end if;
      if p_id is null then insert into public.catalog_material_values(name,slug,cta_mode,cta_label,status,display_order) values(v_name,v_slug,coalesce(p_item->>'cta_mode','both'),nullif(trim(p_item->>'cta_label'),''),v_status,v_order) returning id into v_id;
      else update public.catalog_material_values x set name=v_name,slug=v_slug,cta_mode=coalesce(p_item->>'cta_mode','both'),cta_label=nullif(trim(p_item->>'cta_label'),''),status=v_status,display_order=v_order,updated_at=now() where x.id=p_id and (x.name,x.slug,x.cta_mode,x.cta_label,x.status,x.display_order) is distinct from (v_name,v_slug,coalesce(p_item->>'cta_mode','both'),nullif(trim(p_item->>'cta_label'),''),v_status,v_order); v_id:=p_id; end if;
    when 'ring_size' then
      if exists(select 1 from jsonb_object_keys(p_item) k where k <> all(array['name','slug','status','display_order'])) then raise exception 'Ring size payload contains unsupported fields.' using errcode='22023'; end if;
      if v_slug='' then raise exception 'Slug is required.' using errcode='22023'; end if;
      if exists(select 1 from public.catalog_ring_sizes x where (lower(x.name)=lower(v_name) or x.slug=v_slug) and (p_id is null or x.id<>p_id)) then raise exception 'A ring size with this name or slug already exists.' using errcode='23505'; end if;
      if p_id is null then insert into public.catalog_ring_sizes(name,slug,status,display_order) values(v_name,v_slug,v_status::public.catalog_status,v_order) returning id into v_id;
      else update public.catalog_ring_sizes x set name=v_name,slug=v_slug,status=v_status::public.catalog_status,display_order=v_order,updated_at=now() where x.id=p_id and (x.name,x.slug,x.status,x.display_order) is distinct from (v_name,v_slug,v_status::public.catalog_status,v_order); v_id:=p_id; end if;
    when 'stone_shape' then
      if exists(select 1 from jsonb_object_keys(p_item) k where k <> all(array['name','slug','svg_asset_url','status','display_order'])) then raise exception 'Stone shape payload contains unsupported fields.' using errcode='22023'; end if;
      if v_slug='' then raise exception 'Slug is required.' using errcode='22023'; end if;
      if exists(select 1 from public.catalog_stone_shapes x where (lower(x.name)=lower(v_name) or x.slug=v_slug) and (p_id is null or x.id<>p_id)) then raise exception 'A stone shape with this name or slug already exists.' using errcode='23505'; end if;
      if p_id is null then insert into public.catalog_stone_shapes(name,slug,svg_asset_url,status,display_order) values(v_name,v_slug,nullif(trim(p_item->>'svg_asset_url'),''),v_status::public.catalog_status,v_order) returning id into v_id;
      else update public.catalog_stone_shapes x set name=v_name,slug=v_slug,svg_asset_url=nullif(trim(p_item->>'svg_asset_url'),''),status=v_status::public.catalog_status,display_order=v_order,updated_at=now() where x.id=p_id and (x.name,x.slug,x.svg_asset_url,x.status,x.display_order) is distinct from (v_name,v_slug,nullif(trim(p_item->>'svg_asset_url'),''),v_status::public.catalog_status,v_order); v_id:=p_id; end if;
    when 'style' then
      if exists(select 1 from jsonb_object_keys(p_item) k where k <> all(array['name','icon_svg_path','status','display_order'])) then raise exception 'Style payload contains unsupported fields.' using errcode='22023'; end if;
      if exists(select 1 from public.catalog_styles x where lower(x.name)=lower(v_name) and (p_id is null or x.id<>p_id)) then raise exception 'A style with this name already exists.' using errcode='23505'; end if;
      if p_id is null then
        v_slug:=lower(regexp_replace(regexp_replace(v_name,'[^a-zA-Z0-9]+','-','g'),'(^-|-$)','','g'));
        if v_slug='' then raise exception 'Name must contain letters or numbers.' using errcode='22023'; end if;
        insert into public.catalog_styles(name,slug,icon_svg_path,status,display_order) values(v_name,v_slug,nullif(trim(p_item->>'icon_svg_path'),''),v_status::public.catalog_status,v_order) returning id into v_id;
      else update public.catalog_styles x set name=v_name,icon_svg_path=nullif(trim(p_item->>'icon_svg_path'),''),status=v_status::public.catalog_status,display_order=v_order,updated_at=now() where x.id=p_id and (x.name,x.icon_svg_path,x.status,x.display_order) is distinct from (v_name,nullif(trim(p_item->>'icon_svg_path'),''),v_status::public.catalog_status,v_order); v_id:=p_id; end if;
    when 'content_rule' then
      if exists(select 1 from jsonb_object_keys(p_item) k where k <> all(array['kind','name','slug','title','body','status','display_order'])) then raise exception 'Content rule payload contains unsupported fields.' using errcode='22023'; end if;
      if coalesce(p_item->>'kind','') not in ('shipping','care_warranty') then raise exception 'Invalid content rule type.' using errcode='22023'; end if;
      if v_slug='' or trim(coalesce(p_item->>'title',''))='' or trim(coalesce(p_item->>'body',''))='' then raise exception 'Slug, title, and body are required.' using errcode='22023'; end if;
      if exists(select 1 from public.product_content_rules x where (lower(x.name)=lower(v_name) or x.slug=v_slug) and (p_id is null or x.id<>p_id)) then raise exception 'A content rule with this name or slug already exists.' using errcode='23505'; end if;
      if p_id is null then insert into public.product_content_rules(kind,name,slug,title,body,status,display_order) values((p_item->>'kind')::public.product_content_kind,v_name,v_slug,trim(p_item->>'title'),trim(p_item->>'body'),v_status::public.product_content_status,v_order) returning id into v_id;
      else update public.product_content_rules x set kind=(p_item->>'kind')::public.product_content_kind,name=v_name,slug=v_slug,title=trim(p_item->>'title'),body=trim(p_item->>'body'),status=v_status::public.product_content_status,display_order=v_order,updated_at=now() where x.id=p_id and (x.kind,x.name,x.slug,x.title,x.body,x.status,x.display_order) is distinct from ((p_item->>'kind')::public.product_content_kind,v_name,v_slug,trim(p_item->>'title'),trim(p_item->>'body'),v_status::public.product_content_status,v_order); v_id:=p_id; end if;
    else raise exception 'Unsupported catalog master type.' using errcode='22023';
  end case;

  v_result:=public.catalog_master_row_v1(p_kind,v_id);
  insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'catalog-master-save-'||p_kind,v_hash,v_result);
  return v_result;
exception
  when unique_violation then raise exception 'A record with the same name, code, or slug already exists.' using errcode='23505';
end;
$function$

CREATE OR REPLACE FUNCTION public.cms_article_snapshot_v1(p_kind text, p_post_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_post jsonb;
  v_tags jsonb;
  v_products jsonb;
  v_blocks jsonb;
  v_content jsonb;
begin
  if p_post_id is null or p_post_id < 1 or p_kind not in ('blog', 'education') then
    raise exception 'Invalid article reference.' using errcode = '22023';
  end if;

  if p_kind = 'blog' then
    select to_jsonb(p) - 'created_at' - 'updated_at' into v_post
    from public.blog_posts p where p.id = p_post_id;
    select coalesce(jsonb_agg(to_jsonb(t) - 'post_id' - 'created_at' - 'updated_at' order by t.sort_order, t.id), '[]'::jsonb)
      into v_tags from public.blog_post_tags t where t.post_id = p_post_id;
    select coalesce(jsonb_agg(to_jsonb(r) - 'post_id' - 'created_at' order by r.sort_order, r.id), '[]'::jsonb)
      into v_products from public.blog_post_products r where r.post_id = p_post_id;
    select coalesce(jsonb_agg(to_jsonb(b) - 'post_id' - 'created_at' - 'updated_at' order by b.sort_order, b.id), '[]'::jsonb)
      into v_blocks from public.blog_post_content_blocks b where b.post_id = p_post_id;
  else
    select to_jsonb(p) - 'created_at' - 'updated_at' into v_post
    from public.education_posts p where p.id = p_post_id;
    select coalesce(jsonb_agg(to_jsonb(t) - 'post_id' - 'created_at' - 'updated_at' order by t.sort_order, t.id), '[]'::jsonb)
      into v_tags from public.education_post_tags t where t.post_id = p_post_id;
    select coalesce(jsonb_agg(to_jsonb(r) - 'post_id' - 'created_at' order by r.sort_order, r.id), '[]'::jsonb)
      into v_products from public.education_post_products r where r.post_id = p_post_id;
    select coalesce(jsonb_agg(to_jsonb(b) - 'post_id' - 'created_at' - 'updated_at' order by b.sort_order, b.id), '[]'::jsonb)
      into v_blocks from public.education_post_content_blocks b where b.post_id = p_post_id;
  end if;

  if v_post is null then
    raise exception 'Article not found.' using errcode = 'P0002';
  end if;

  v_content := jsonb_build_object('post', v_post, 'tags', v_tags, 'products', v_products, 'content_blocks', v_blocks);
  return v_content || jsonb_build_object('revision', md5(v_content::text));
end;
$function$

CREATE OR REPLACE FUNCTION public.cms_content_list_snapshot_v1(p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_items jsonb;
begin
  case p_kind
    when 'about_values' then
      select coalesce(jsonb_agg(jsonb_build_object(
        'id',i.id,'sort_order',i.sort_order,'icon_path',i.icon_path,
        'image_path',coalesce(i.image_path,''),'image_alt',coalesce(i.image_alt,''),
        'title',i.title,'description',i.description
      ) order by i.sort_order, i.id), '[]'::jsonb)
        into v_items from public.about_values i;
    when 'about_timeline' then
      select coalesce(jsonb_agg(to_jsonb(i) - 'created_at' - 'updated_at' order by i.sort_order, i.id), '[]'::jsonb)
        into v_items from public.about_timeline i;
    when 'about_founders' then
      select coalesce(jsonb_agg(to_jsonb(i) - 'created_at' - 'updated_at' order by i.sort_order, i.id), '[]'::jsonb)
        into v_items from public.about_founders i;
    when 'contact_info' then
      select coalesce(jsonb_agg(to_jsonb(i) - 'created_at' - 'updated_at' order by i.sort_order, i.id), '[]'::jsonb)
        into v_items from public.contact_info i;
    when 'bespoke_process' then
      select coalesce(jsonb_agg(to_jsonb(i) - 'created_at' - 'updated_at' order by i.sort_order, i.id), '[]'::jsonb)
        into v_items from public.bespoke_process_cards i;
    when 'bespoke_manufacturing' then
      select coalesce(jsonb_agg(jsonb_build_object(
        'id',i.id,'sort_order',i.sort_order,'step',i.step,'eyebrow',i.eyebrow,
        'title',i.title,'description',i.description,'image_path',i.image_path,
        'media_type',i.media_type,'media_path',coalesce(i.media_path,'')
      ) order by i.sort_order, i.id), '[]'::jsonb)
        into v_items from public.bespoke_process_steps i;
    else
      raise exception 'Unsupported CMS list.' using errcode = '22023';
  end case;

  return jsonb_build_object(
    'items', v_items,
    'revision', md5(v_items::text)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.cms_delete_article_v1(p_actor_id uuid, p_request_id uuid, p_kind text, p_post_id bigint, p_expected_revision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_before jsonb; v_result jsonb; v_receipt public.cms_save_receipts%rowtype; v_hash text;
begin
  if p_actor_id is null or p_request_id is null or not exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin') then raise exception 'Administrator access is required.' using errcode='42501'; end if;
  if p_kind not in ('blog','education') or p_post_id is null or p_post_id<1 or coalesce(p_expected_revision,'') !~ '^[0-9a-f]{32}$' then raise exception 'Invalid delete request.' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('cms-article:'||p_kind||':'||p_post_id::text,0));
  perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text||p_request_id::text,0));
  v_hash:=md5(jsonb_build_object('kind',p_kind,'post_id',p_post_id,'revision',p_expected_revision)::text);
  select r.* into v_receipt from public.cms_save_receipts r where r.actor_id=p_actor_id and r.request_id=p_request_id;
  if found then if v_receipt.operation<>'article-delete-'||p_kind or v_receipt.payload_hash<>v_hash then raise exception 'This delete request was already used for different changes.' using errcode='40001'; end if; return v_receipt.result; end if;
  v_before:=public.cms_article_snapshot_v1(p_kind,p_post_id);
  if v_before->>'revision'<>p_expected_revision then raise exception 'This article changed since you opened it. Reload before deleting.' using errcode='40001'; end if;
  if p_kind='blog' then
    delete from public.blog_post_content_blocks where post_id=p_post_id; delete from public.blog_post_tags where post_id=p_post_id; delete from public.blog_post_products where post_id=p_post_id; delete from public.blog_posts where id=p_post_id;
  else
    delete from public.education_post_content_blocks where post_id=p_post_id; delete from public.education_post_tags where post_id=p_post_id; delete from public.education_post_products where post_id=p_post_id; delete from public.education_posts where id=p_post_id;
  end if;
  v_result:=jsonb_build_object('ok',true,'deleted_id',p_post_id);
  insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'article-delete-'||p_kind,v_hash,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.cms_delete_support_faq_category_v1(p_actor_id uuid, p_request_id uuid, p_expected_revision text, p_id bigint)
