$function$

CREATE OR REPLACE FUNCTION public.cms_docs_snapshot_v1(p_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_page jsonb; v_blocks jsonb; v_content jsonb;
begin
  select to_jsonb(p)-'created_at'-'updated_at' into v_page from public.docs_pages p where p.slug=p_slug;
  if v_page is null then raise exception 'Docs page not found.' using errcode='P0002'; end if;
  select coalesce(jsonb_agg(to_jsonb(b)-'page_id'-'created_at'-'updated_at' order by b.sort_order,b.id),'[]'::jsonb) into v_blocks from public.docs_blocks b where b.page_id=(v_page->>'id')::bigint;
  v_content:=jsonb_build_object('page',v_page,'blocks',v_blocks);
  return v_content||jsonb_build_object('revision',md5(v_content::text));
end; $function$

CREATE OR REPLACE FUNCTION public.cms_home_group1_snapshot_v1(p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_section jsonb; v_items jsonb;
begin
  case p_kind
    when 'hero' then
      select to_jsonb(s) - 'created_at' - 'updated_at' into v_section
        from public.homepage_hero s where s.section_key = 'home_hero';
      select coalesce(jsonb_agg(to_jsonb(i) - 'created_at' - 'updated_at' order by i.sort_order, i.id), '[]') into v_items
        from public.homepage_hero_slider_items i
        where i.hero_id = (select id from public.homepage_hero where section_key = 'home_hero');
    when 'collection' then
      v_section := 'null';
      select coalesce(jsonb_agg(to_jsonb(i) order by i.sort_order, i.id), '[]') into v_items from public.collection_items i;
    when 'certifications' then
      select to_jsonb(s) into v_section from public.certifications_section s where s.section_key = 'home_certifications';
      select coalesce(jsonb_agg(to_jsonb(i) order by i.sort_order, i.id), '[]') into v_items from public.certifications_items i;
    when 'discover_shapes' then
      v_section := 'null';
      select coalesce(jsonb_agg(to_jsonb(i) - 'created_at' - 'updated_at' order by i.sort_order, i.id), '[]') into v_items from public.discover_shapes_items i;
    when 'bestsellers' then
      select to_jsonb(s) - 'created_at' - 'updated_at' into v_section from public.cms_home_bestsellers s where s.status = 'active' limit 1;
      select coalesce(jsonb_agg(to_jsonb(i) - 'created_at' order by i.display_order, i.id), '[]') into v_items
        from public.cms_home_bestseller_products i where i.section_id = (v_section->>'id')::uuid;
    when 'shop_by_category' then
      select to_jsonb(s) - 'created_at' - 'updated_at' into v_section from public.homepage_shop_by_category s where s.section_key = 'home_shop_by_category';
      select coalesce(jsonb_agg(to_jsonb(i) - 'created_at' - 'updated_at' order by i.display_order, i.id), '[]') into v_items
        from public.homepage_shop_by_category_items i where i.section_id = (v_section->>'id')::bigint;
    else raise exception 'Unsupported CMS section.' using errcode = '22023';
  end case;
  return jsonb_build_object('section', v_section, 'items', v_items,
    'revision', md5(jsonb_build_object('section', v_section, 'items', v_items)::text));
end;
$function$

CREATE OR REPLACE FUNCTION public.cms_relational_snapshot_v1(p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_parent jsonb; v_items jsonb:='[]'::jsonb; v_parent_id text; v_content jsonb;
begin
  case p_kind
    when 'checkout_result' then
      select to_jsonb(x)-'id'-'created_at'-'updated_at' into v_parent from public.checkout_result_page x where id=1;
      select coalesce(jsonb_agg(to_jsonb(x)-'created_at'-'updated_at' order by case state when 'success' then 1 when 'pending' then 2 when 'failed' then 3 else 4 end),'[]') into v_items from public.checkout_result_states x;
    when 'promotion' then
      select id::text,to_jsonb(x)-'id'-'section_key'-'created_at'-'updated_at' into v_parent_id,v_parent from public.promotion_popup x where section_key='global_promotion_popup';
      if v_parent_id is not null then select coalesce(jsonb_agg(to_jsonb(x)-'promotion_id'-'created_at'-'updated_at' order by sort_order,id),'[]') into v_items from public.promotion_popup_questions x where promotion_id=v_parent_id::bigint; end if;
    when 'service_banner' then
      select to_jsonb(x)-'id'-'created_at'-'updated_at' into v_parent from public.service_banner_section x where id=1;
      select coalesce(jsonb_agg(to_jsonb(x)-'created_at'-'updated_at' order by sort_order,id),'[]') into v_items from public.service_banner_blocks x;
    when 'summary' then
      select id::text,to_jsonb(x)-'id'-'section_key'-'created_at'-'updated_at' into v_parent_id,v_parent from public.cms_summary_sections x where section_key='additional_summary_details';
      if v_parent_id is not null then select coalesce(jsonb_agg(to_jsonb(x)-'section_id'-'created_at'-'updated_at' order by sort_order,id),'[]') into v_items from public.cms_summary_pointers x where section_id=v_parent_id::uuid; end if;
    when 'announcement' then
      select id::text,to_jsonb(x)-'id'-'section_key'-'created_at'-'updated_at' into v_parent_id,v_parent from public.support_announcement_bar x where section_key='global_support_announcement_bar';
      if v_parent_id is not null then select coalesce(jsonb_agg(to_jsonb(x)-'bar_id'-'created_at'-'updated_at' order by sort_order,id),'[]') into v_items from public.support_announcement_bar_items x where bar_id=v_parent_id::bigint; end if;
    when 'faq' then
      select id::text,to_jsonb(x)-'id'-'section_key'-'created_at'-'updated_at' into v_parent_id,v_parent from public.support_faq_section x where section_key='global_support_faq';
      if v_parent_id is not null then select coalesce(jsonb_agg(to_jsonb(x)-'section_id'-'created_at'-'updated_at' order by sort_order,id),'[]') into v_items from public.support_faq_items x where section_id=v_parent_id::bigint; end if;
    else raise exception 'Unsupported CMS relational section.' using errcode='22023';
  end case;
  v_content:=jsonb_build_object('parent',v_parent,'items',v_items);
  return v_content||jsonb_build_object('revision',md5(v_content::text));
end; $function$

CREATE OR REPLACE FUNCTION public.cms_save_article_v1(p_actor_id uuid, p_request_id uuid, p_kind text, p_post_id bigint, p_expected_revision text, p_post jsonb, p_tags jsonb, p_products jsonb, p_blocks jsonb, p_deleted_tag_ids text[], p_deleted_product_ids text[], p_deleted_block_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_before jsonb;
  v_result jsonb;
  v_receipt public.cms_save_receipts%rowtype;
  v_hash text;
  v_item jsonb;
  v_id_text text;
  v_post_id bigint := p_post_id;
  v_slug text;
  v_base_slug text;
  v_suffix integer := 2;
  v_position integer;
begin
  if p_actor_id is null or p_request_id is null or not exists (
    select 1 from public.profiles p where p.id = p_actor_id and p.role = 'admin'
  ) then
    raise exception 'Administrator access is required.' using errcode = '42501';
  end if;

  if p_kind not in ('blog', 'education')
    or jsonb_typeof(p_post) is distinct from 'object'
    or jsonb_typeof(p_tags) is distinct from 'array'
    or jsonb_typeof(p_products) is distinct from 'array'
    or jsonb_typeof(p_blocks) is distinct from 'array'
    or p_deleted_tag_ids is null or p_deleted_product_ids is null or p_deleted_block_ids is null
    or array_position(p_deleted_tag_ids, null) is not null
    or array_position(p_deleted_product_ids, null) is not null
    or array_position(p_deleted_block_ids, null) is not null
  then
    raise exception 'Invalid article payload. Reload this editor.' using errcode = '22023';
  end if;

  if jsonb_array_length(p_tags) > 100 or jsonb_array_length(p_products) > 100
    or jsonb_array_length(p_blocks) > 100 or cardinality(p_deleted_tag_ids) > 100
    or cardinality(p_deleted_product_ids) > 100 or cardinality(p_deleted_block_ids) > 100
  then
    raise exception 'Too many article relations.' using errcode = '22023';
  end if;

  if nullif(trim(p_post->>'title'), '') is null
    or nullif(trim(p_post->>'subtitle'), '') is null
    or nullif(trim(p_post->>'body_html'), '') is null
    or jsonb_typeof(p_post->'is_published') is distinct from 'boolean'
    or coalesce(p_post->>'sort_order', '') !~ '^-?[0-9]+$'
  then
    raise exception 'Title, subtitle, body, publication status, and order are required.' using errcode = '22023';
  end if;

  v_base_slug := trim(p_post->>'slug_base');
  if v_base_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or length(v_base_slug) > 180 then
    raise exception 'A valid article URL is required.' using errcode = '22023';
  end if;

  if exists (select 1 from jsonb_array_elements(p_tags) x where
      jsonb_typeof(x->'tag') is distinct from 'string' or nullif(trim(x->>'tag'), '') is null)
    or exists (select lower(trim(x->>'tag')) from jsonb_array_elements(p_tags) x group by 1 having count(*) > 1)
  then
    raise exception 'Tags must be non-empty and unique.' using errcode = '22023';
  end if;

  if exists (select 1 from jsonb_array_elements(p_products) x where
      jsonb_typeof(x->'product_id') is distinct from 'string'
      or (x->>'product_id') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$')
    or exists (select x->>'product_id' from jsonb_array_elements(p_products) x group by 1 having count(*) > 1)
    or exists (select 1 from jsonb_array_elements(p_products) x
      where not exists (select 1 from public.products p where p.id = (x->>'product_id')::uuid))
  then
    raise exception 'Every linked product must exist and may only be selected once.' using errcode = '22023';
  end if;

  if exists (select 1 from jsonb_array_elements(p_blocks) x where
      coalesce(x->>'block_type', '') not in ('text','image','heading','quote')
      or jsonb_typeof(x->'is_enabled') is distinct from 'boolean'
      or (x->>'block_type' = 'image' and nullif(trim(x->>'image_path'), '') is null)
      or (x->>'block_type' = 'heading' and nullif(trim(x->>'heading'), '') is null)
      or (x->>'block_type' in ('text','quote') and nullif(trim(x->>'body_html'), '') is null))
  then
    raise exception 'Every content block must contain the required content.' using errcode = '22023';
  end if;

  if p_kind = 'blog' and nullif(p_post->>'catalog_category_id', '') is not null and (
    (p_post->>'catalog_category_id') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
    or not exists (select 1 from public.catalog_categories c where c.id = (p_post->>'catalog_category_id')::uuid)
  ) then
    raise exception 'The selected catalog category does not exist.' using errcode = '23503';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('cms-article:' || p_kind || ':' || coalesce(p_post_id::text, 'new'), 0));
  perform pg_advisory_xact_lock(hashtextextended('cms-article-slug:' || p_kind || ':' || v_base_slug, 0));
  perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text || p_request_id::text, 0));

  v_hash := md5(jsonb_build_object('kind',p_kind,'post_id',p_post_id,'revision',p_expected_revision,
    'post',p_post,'tags',p_tags,'products',p_products,'blocks',p_blocks,
    'deleted_tags',p_deleted_tag_ids,'deleted_products',p_deleted_product_ids,'deleted_blocks',p_deleted_block_ids)::text);
  select r.* into v_receipt from public.cms_save_receipts r
  where r.actor_id = p_actor_id and r.request_id = p_request_id;
  if found then
    if v_receipt.operation <> 'article-save-' || p_kind or v_receipt.payload_hash <> v_hash then
      raise exception 'This save request was already used for different changes.' using errcode = '40001';
    end if;
    return v_receipt.result;
  end if;

  if p_post_id is null then
    if p_expected_revision is not null or cardinality(p_deleted_tag_ids) > 0
      or cardinality(p_deleted_product_ids) > 0 or cardinality(p_deleted_block_ids) > 0
      or exists (select 1 from jsonb_array_elements(p_tags) x where x ? 'id')
      or exists (select 1 from jsonb_array_elements(p_products) x where x ? 'id')
      or exists (select 1 from jsonb_array_elements(p_blocks) x where x ? 'id')
    then
      raise exception 'New articles cannot contain saved row IDs or deletions.' using errcode = '22023';
    end if;
  else
    if p_expected_revision is null or p_expected_revision !~ '^[0-9a-f]{32}$' then
      raise exception 'This editor is out of date. Reload it before saving.' using errcode = '40001';
    end if;
    v_before := public.cms_article_snapshot_v1(p_kind, p_post_id);
    if v_before->>'revision' <> p_expected_revision then
      raise exception 'This article changed since you opened it. Reload before saving.' using errcode = '40001';
    end if;
  end if;

  if (select count(distinct x) from unnest(p_deleted_tag_ids) x) <> cardinality(p_deleted_tag_ids)
    or (select count(distinct x) from unnest(p_deleted_product_ids) x) <> cardinality(p_deleted_product_ids)
    or (select count(distinct x) from unnest(p_deleted_block_ids) x) <> cardinality(p_deleted_block_ids)
  then raise exception 'A deleted row ID was duplicated.' using errcode = '22023'; end if;

  if exists (select 1 from jsonb_array_elements(p_tags) x where x ? 'id' and (coalesce(x->>'id','') !~ '^[1-9][0-9]*$' or x->>'id'=any(p_deleted_tag_ids)))
    or exists (select x->>'id' from jsonb_array_elements(p_tags) x where x ? 'id' group by 1 having count(*)>1)
    or exists (select 1 from jsonb_array_elements(p_products) x where x ? 'id' and (coalesce(x->>'id','') !~ '^[1-9][0-9]*$' or x->>'id'=any(p_deleted_product_ids)))
    or exists (select x->>'id' from jsonb_array_elements(p_products) x where x ? 'id' group by 1 having count(*)>1)
    or exists (select 1 from jsonb_array_elements(p_blocks) x where x ? 'id' and (coalesce(x->>'id','') !~ '^[1-9][0-9]*$' or x->>'id'=any(p_deleted_block_ids)))
    or exists (select x->>'id' from jsonb_array_elements(p_blocks) x where x ? 'id' group by 1 having count(*)>1)
  then raise exception 'A relation ID is invalid, duplicated, or both retained and deleted.' using errcode = '22023'; end if;

  v_slug := v_base_slug;
  if p_post_id is not null then
    if p_kind='blog' then select p.slug into v_slug from public.blog_posts p where p.id=p_post_id;
    else select p.slug into v_slug from public.education_posts p where p.id=p_post_id; end if;
    if v_slug is null then raise exception 'Article not found.' using errcode='P0002'; end if;
    if v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then v_slug := v_base_slug; end if;
  end if;
  if p_post_id is null or v_slug = v_base_slug then
    loop
      exit when (p_kind='blog' and not exists(select 1 from public.blog_posts p where p.slug=v_slug and p.id is distinct from p_post_id))
        or (p_kind='education' and not exists(select 1 from public.education_posts p where p.slug=v_slug and p.id is distinct from p_post_id));
      v_slug := v_base_slug || '-' || v_suffix; v_suffix := v_suffix + 1;
    end loop;
  end if;

  if p_kind = 'blog' then
    if p_post_id is null then
      insert into public.blog_posts(slug,title,title_html,card_title,subtitle,category,catalog_category_id,author,date_label,read_time,bg_key,bg_color,hero_image_path,card_image_path,hero_image_alt,body_html,is_published,sort_order)
      values(v_slug,trim(p_post->>'title'),coalesce(nullif(trim(p_post->>'title_html'),''),trim(p_post->>'title')),nullif(trim(p_post->>'card_title'),''),trim(p_post->>'subtitle'),trim(p_post->>'category'),nullif(p_post->>'catalog_category_id','')::uuid,trim(p_post->>'author'),trim(p_post->>'date_label'),trim(p_post->>'read_time'),trim(p_post->>'bg_key'),trim(p_post->>'bg_color'),trim(p_post->>'hero_image_path'),nullif(trim(p_post->>'card_image_path'),''),nullif(trim(p_post->>'hero_image_alt'),''),trim(p_post->>'body_html'),(p_post->>'is_published')::boolean,(p_post->>'sort_order')::integer)
      returning id into v_post_id;
    else
      update public.blog_posts p set slug=v_slug,title=trim(p_post->>'title'),title_html=coalesce(nullif(trim(p_post->>'title_html'),''),trim(p_post->>'title')),card_title=nullif(trim(p_post->>'card_title'),''),subtitle=trim(p_post->>'subtitle'),category=trim(p_post->>'category'),catalog_category_id=nullif(p_post->>'catalog_category_id','')::uuid,author=trim(p_post->>'author'),date_label=trim(p_post->>'date_label'),read_time=trim(p_post->>'read_time'),bg_key=trim(p_post->>'bg_key'),bg_color=trim(p_post->>'bg_color'),hero_image_path=trim(p_post->>'hero_image_path'),card_image_path=nullif(trim(p_post->>'card_image_path'),''),hero_image_alt=nullif(trim(p_post->>'hero_image_alt'),''),body_html=trim(p_post->>'body_html'),is_published=(p_post->>'is_published')::boolean,sort_order=(p_post->>'sort_order')::integer,updated_at=now()
      where p.id=v_post_id;
    end if;
  else
    if p_post_id is null then
      insert into public.education_posts(slug,title,title_html,card_title,subtitle,category,author,date_label,read_time,bg_key,bg_color,hero_image_path,card_image_path,hero_image_alt,body_html,is_published,sort_order)
      values(v_slug,trim(p_post->>'title'),coalesce(nullif(trim(p_post->>'title_html'),''),trim(p_post->>'title')),nullif(trim(p_post->>'card_title'),''),trim(p_post->>'subtitle'),trim(p_post->>'category'),trim(p_post->>'author'),trim(p_post->>'date_label'),trim(p_post->>'read_time'),trim(p_post->>'bg_key'),trim(p_post->>'bg_color'),trim(p_post->>'hero_image_path'),nullif(trim(p_post->>'card_image_path'),''),nullif(trim(p_post->>'hero_image_alt'),''),trim(p_post->>'body_html'),(p_post->>'is_published')::boolean,(p_post->>'sort_order')::integer)
      returning id into v_post_id;
    else
      update public.education_posts p set slug=v_slug,title=trim(p_post->>'title'),title_html=coalesce(nullif(trim(p_post->>'title_html'),''),trim(p_post->>'title')),card_title=nullif(trim(p_post->>'card_title'),''),subtitle=trim(p_post->>'subtitle'),category=trim(p_post->>'category'),author=trim(p_post->>'author'),date_label=trim(p_post->>'date_label'),read_time=trim(p_post->>'read_time'),bg_key=trim(p_post->>'bg_key'),bg_color=trim(p_post->>'bg_color'),hero_image_path=trim(p_post->>'hero_image_path'),card_image_path=nullif(trim(p_post->>'card_image_path'),''),hero_image_alt=nullif(trim(p_post->>'hero_image_alt'),''),body_html=trim(p_post->>'body_html'),is_published=(p_post->>'is_published')::boolean,sort_order=(p_post->>'sort_order')::integer,updated_at=now()
      where p.id=v_post_id;
    end if;
  end if;

  -- Existing children must be either retained by ID or explicitly deleted.
  if p_post_id is not null then
    if p_kind='blog' then
      if exists(select 1 from public.blog_post_tags r where r.post_id=v_post_id and r.id::text<>all(p_deleted_tag_ids) and not exists(select 1 from jsonb_array_elements(p_tags)x where x->>'id'=r.id::text))
        or exists(select 1 from jsonb_array_elements(p_tags)x where x?'id' and not exists(select 1 from public.blog_post_tags r where r.post_id=v_post_id and r.id::text=x->>'id'))
        or exists(select 1 from unnest(p_deleted_tag_ids)d where not exists(select 1 from public.blog_post_tags r where r.post_id=v_post_id and r.id::text=d))
        or exists(select 1 from public.blog_post_products r where r.post_id=v_post_id and r.id::text<>all(p_deleted_product_ids) and not exists(select 1 from jsonb_array_elements(p_products)x where x->>'id'=r.id::text))
        or exists(select 1 from jsonb_array_elements(p_products)x where x?'id' and not exists(select 1 from public.blog_post_products r where r.post_id=v_post_id and r.id::text=x->>'id'))
        or exists(select 1 from unnest(p_deleted_product_ids)d where not exists(select 1 from public.blog_post_products r where r.post_id=v_post_id and r.id::text=d))
        or exists(select 1 from public.blog_post_content_blocks r where r.post_id=v_post_id and r.id::text<>all(p_deleted_block_ids) and not exists(select 1 from jsonb_array_elements(p_blocks)x where x->>'id'=r.id::text))
        or exists(select 1 from jsonb_array_elements(p_blocks)x where x?'id' and not exists(select 1 from public.blog_post_content_blocks r where r.post_id=v_post_id and r.id::text=x->>'id'))
        or exists(select 1 from unnest(p_deleted_block_ids)d where not exists(select 1 from public.blog_post_content_blocks r where r.post_id=v_post_id and r.id::text=d))
      then raise exception 'Every existing article relation must be retained or explicitly removed.' using errcode='22023'; end if;
    else
      if exists(select 1 from public.education_post_tags r where r.post_id=v_post_id and r.id::text<>all(p_deleted_tag_ids) and not exists(select 1 from jsonb_array_elements(p_tags)x where x->>'id'=r.id::text))
        or exists(select 1 from jsonb_array_elements(p_tags)x where x?'id' and not exists(select 1 from public.education_post_tags r where r.post_id=v_post_id and r.id::text=x->>'id'))
        or exists(select 1 from unnest(p_deleted_tag_ids)d where not exists(select 1 from public.education_post_tags r where r.post_id=v_post_id and r.id::text=d))
        or exists(select 1 from public.education_post_products r where r.post_id=v_post_id and r.id::text<>all(p_deleted_product_ids) and not exists(select 1 from jsonb_array_elements(p_products)x where x->>'id'=r.id::text))
        or exists(select 1 from jsonb_array_elements(p_products)x where x?'id' and not exists(select 1 from public.education_post_products r where r.post_id=v_post_id and r.id::text=x->>'id'))
        or exists(select 1 from unnest(p_deleted_product_ids)d where not exists(select 1 from public.education_post_products r where r.post_id=v_post_id and r.id::text=d))
        or exists(select 1 from public.education_post_content_blocks r where r.post_id=v_post_id and r.id::text<>all(p_deleted_block_ids) and not exists(select 1 from jsonb_array_elements(p_blocks)x where x->>'id'=r.id::text))
        or exists(select 1 from jsonb_array_elements(p_blocks)x where x?'id' and not exists(select 1 from public.education_post_content_blocks r where r.post_id=v_post_id and r.id::text=x->>'id'))
        or exists(select 1 from unnest(p_deleted_block_ids)d where not exists(select 1 from public.education_post_content_blocks r where r.post_id=v_post_id and r.id::text=d))
      then raise exception 'Every existing article relation must be retained or explicitly removed.' using errcode='22023'; end if;
    end if;
  end if;

  if p_kind='blog' then
    delete from public.blog_post_tags r where r.post_id=v_post_id and r.id::text=any(p_deleted_tag_ids);
    delete from public.blog_post_products r where r.post_id=v_post_id and r.id::text=any(p_deleted_product_ids);
    delete from public.blog_post_content_blocks r where r.post_id=v_post_id and r.id::text=any(p_deleted_block_ids);
  else
    delete from public.education_post_tags r where r.post_id=v_post_id and r.id::text=any(p_deleted_tag_ids);
    delete from public.education_post_products r where r.post_id=v_post_id and r.id::text=any(p_deleted_product_ids);
    delete from public.education_post_content_blocks r where r.post_id=v_post_id and r.id::text=any(p_deleted_block_ids);
  end if;

  v_position:=0;
  for v_item in select value from jsonb_array_elements(p_tags) loop
    v_position:=v_position+1; v_id_text:=v_item->>'id';
    if p_kind='blog' then
      if v_id_text is null then insert into public.blog_post_tags(post_id,tag,sort_order) values(v_post_id,trim(v_item->>'tag'),v_position);
      else update public.blog_post_tags r set tag=trim(v_item->>'tag'),sort_order=v_position,updated_at=now() where r.id=v_id_text::bigint and r.post_id=v_post_id and (r.tag,r.sort_order) is distinct from (trim(v_item->>'tag'),v_position); end if;
    else
      if v_id_text is null then insert into public.education_post_tags(post_id,tag,sort_order) values(v_post_id,trim(v_item->>'tag'),v_position);
      else update public.education_post_tags r set tag=trim(v_item->>'tag'),sort_order=v_position,updated_at=now() where r.id=v_id_text::bigint and r.post_id=v_post_id and (r.tag,r.sort_order) is distinct from (trim(v_item->>'tag'),v_position); end if;
    end if;
  end loop;

  v_position:=0;
  for v_item in select value from jsonb_array_elements(p_products) loop
    v_position:=v_position+1; v_id_text:=v_item->>'id';
    if p_kind='blog' then
      if v_id_text is null then insert into public.blog_post_products(post_id,product_id,sort_order) values(v_post_id,(v_item->>'product_id')::uuid,v_position);
      else update public.blog_post_products r set product_id=(v_item->>'product_id')::uuid,sort_order=v_position where r.id=v_id_text::bigint and r.post_id=v_post_id and (r.product_id,r.sort_order) is distinct from ((v_item->>'product_id')::uuid,v_position); end if;
    else
      if v_id_text is null then insert into public.education_post_products(post_id,product_id,sort_order) values(v_post_id,(v_item->>'product_id')::uuid,v_position);
      else update public.education_post_products r set product_id=(v_item->>'product_id')::uuid,sort_order=v_position where r.id=v_id_text::bigint and r.post_id=v_post_id and (r.product_id,r.sort_order) is distinct from ((v_item->>'product_id')::uuid,v_position); end if;
    end if;
  end loop;

  v_position:=0;
  for v_item in select value from jsonb_array_elements(p_blocks) loop
    v_position:=v_position+1; v_id_text:=v_item->>'id';
    if p_kind='blog' then
      if v_id_text is null then insert into public.blog_post_content_blocks(post_id,block_type,sort_order,heading,body_html,image_path,image_alt,image_caption,is_enabled) values(v_post_id,v_item->>'block_type',v_position,nullif(trim(v_item->>'heading'),''),nullif(trim(v_item->>'body_html'),''),nullif(trim(v_item->>'image_path'),''),nullif(trim(v_item->>'image_alt'),''),nullif(trim(v_item->>'image_caption'),''),(v_item->>'is_enabled')::boolean);
      else update public.blog_post_content_blocks r set block_type=v_item->>'block_type',sort_order=v_position,heading=nullif(trim(v_item->>'heading'),''),body_html=nullif(trim(v_item->>'body_html'),''),image_path=nullif(trim(v_item->>'image_path'),''),image_alt=nullif(trim(v_item->>'image_alt'),''),image_caption=nullif(trim(v_item->>'image_caption'),''),is_enabled=(v_item->>'is_enabled')::boolean,updated_at=now() where r.id=v_id_text::bigint and r.post_id=v_post_id; end if;
    else
      if v_id_text is null then insert into public.education_post_content_blocks(post_id,block_type,sort_order,heading,body_html,image_path,image_alt,image_caption,is_enabled) values(v_post_id,v_item->>'block_type',v_position,nullif(trim(v_item->>'heading'),''),nullif(trim(v_item->>'body_html'),''),nullif(trim(v_item->>'image_path'),''),nullif(trim(v_item->>'image_alt'),''),nullif(trim(v_item->>'image_caption'),''),(v_item->>'is_enabled')::boolean);
      else update public.education_post_content_blocks r set block_type=v_item->>'block_type',sort_order=v_position,heading=nullif(trim(v_item->>'heading'),''),body_html=nullif(trim(v_item->>'body_html'),''),image_path=nullif(trim(v_item->>'image_path'),''),image_alt=nullif(trim(v_item->>'image_alt'),''),image_caption=nullif(trim(v_item->>'image_caption'),''),is_enabled=(v_item->>'is_enabled')::boolean,updated_at=now() where r.id=v_id_text::bigint and r.post_id=v_post_id; end if;
    end if;
  end loop;

  v_result:=public.cms_article_snapshot_v1(p_kind,v_post_id);
  insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result)
  values(p_actor_id,p_request_id,'article-save-'||p_kind,v_hash,v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.cms_save_content_list_v1(p_actor_id uuid, p_request_id uuid, p_expected_revision text, p_kind text, p_items jsonb, p_deleted_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_before jsonb;
  v_result jsonb;
  v_receipt public.cms_save_receipts%rowtype;
  v_hash text;
  v_item jsonb;
  v_id_text text;
  v_position integer := 0;
begin
  if p_actor_id is null or p_request_id is null or not exists (
    select 1 from public.profiles p where p.id = p_actor_id and p.role = 'admin'
  ) then
    raise exception 'Administrator access is required.' using errcode = '42501';
  end if;

  if p_expected_revision is null
    or p_expected_revision !~ '^[0-9a-f]{32}$'
    or p_kind not in ('about_values', 'about_timeline', 'about_founders', 'contact_info', 'bespoke_process', 'bespoke_manufacturing')
    or jsonb_typeof(p_items) is distinct from 'array'
    or p_deleted_ids is null
    or array_position(p_deleted_ids, null) is not null
  then
    raise exception 'Invalid save payload. Reload this editor.' using errcode = '22023';
  end if;

  if jsonb_array_length(p_items) > 100 or cardinality(p_deleted_ids) > 100 then
    raise exception 'Too many CMS rows.' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('cms-content-list:' || p_kind, 0));
  perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text || p_request_id::text, 0));

  v_hash := md5(jsonb_build_object(
    'revision', p_expected_revision,
    'kind', p_kind,
    'items', p_items,
    'deleted', p_deleted_ids
  )::text);

  select receipt.* into v_receipt
  from public.cms_save_receipts receipt
  where receipt.actor_id = p_actor_id and receipt.request_id = p_request_id;

  if found then
    if v_receipt.operation <> 'content-list-' || p_kind or v_receipt.payload_hash <> v_hash then
      raise exception 'This save request was already used for different changes.' using errcode = '40001';
    end if;
    return v_receipt.result;
  end if;

  case p_kind
    when 'about_values' then lock table public.about_values in share row exclusive mode;
    when 'about_timeline' then lock table public.about_timeline in share row exclusive mode;
    when 'about_founders' then lock table public.about_founders in share row exclusive mode;
    when 'contact_info' then lock table public.contact_info in share row exclusive mode;
    when 'bespoke_process' then lock table public.bespoke_process_cards in share row exclusive mode;
    when 'bespoke_manufacturing' then lock table public.bespoke_process_steps in share row exclusive mode;
  end case;

  v_before := public.cms_content_list_snapshot_v1(p_kind);
  if v_before->>'revision' <> p_expected_revision then
    raise exception 'This section changed since you opened it. Reload before saving.' using errcode = '40001';
  end if;

  if (select count(distinct deleted_id) from unnest(p_deleted_ids) deleted_id) <> cardinality(p_deleted_ids) then
    raise exception 'A deleted row ID was duplicated.' using errcode = '22023';
  end if;

  if exists (
    select 1 from jsonb_array_elements(p_items) item
    where item ? 'id' and (
      jsonb_typeof(item->'id') not in ('string', 'number')
      or nullif(item->>'id', '') is null
      or item->>'id' !~ '^[1-9][0-9]*$'
      or item->>'id' = any(p_deleted_ids)
    )
  ) or exists (
    select item_id
    from (select value->>'id' item_id from jsonb_array_elements(p_items) where value ? 'id') submitted
    group by item_id having count(*) > 1
  ) then
    raise exception 'A row ID is invalid, duplicated, or both retained and deleted.' using errcode = '22023';
  end if;

  if p_kind = 'about_values' then
    if exists (select 1 from jsonb_array_elements(p_items) item where
      jsonb_typeof(item->'icon_path') is distinct from 'string'
      or jsonb_typeof(item->'image_path') is distinct from 'string'
      or jsonb_typeof(item->'image_alt') is distinct from 'string'
      or jsonb_typeof(item->'title') is distinct from 'string'
      or jsonb_typeof(item->'description') is distinct from 'string')
    then raise exception 'Every value card must be valid.' using errcode = '22023'; end if;
    if exists (select 1 from public.about_values row where row.id::text <> all(p_deleted_ids)
      and not exists (select 1 from jsonb_array_elements(p_items) item where item->>'id' = row.id::text))
      or exists (select 1 from jsonb_array_elements(p_items) item where item ? 'id'
        and not exists (select 1 from public.about_values row where row.id::text = item->>'id'))
      or exists (select 1 from unnest(p_deleted_ids) deleted_id
        where not exists (select 1 from public.about_values row where row.id::text = deleted_id))
    then raise exception 'Every existing value card must be retained or explicitly removed.' using errcode = '22023'; end if;
    delete from public.about_values row where row.id::text = any(p_deleted_ids);
    for v_item in select value from jsonb_array_elements(p_items) loop
      v_position := v_position + 1; v_id_text := v_item->>'id';
      if v_id_text is null then
        insert into public.about_values(sort_order, icon_path, image_path, image_alt, title, description)
        values(v_position, trim(v_item->>'icon_path'), nullif(trim(v_item->>'image_path'), ''), nullif(trim(v_item->>'image_alt'), ''), trim(v_item->>'title'), trim(v_item->>'description'));
      else
        update public.about_values row set sort_order=v_position, icon_path=trim(v_item->>'icon_path'), image_path=nullif(trim(v_item->>'image_path'), ''), image_alt=nullif(trim(v_item->>'image_alt'), ''), title=trim(v_item->>'title'), description=trim(v_item->>'description')
        where row.id=v_id_text::bigint and (row.sort_order,row.icon_path,row.image_path,row.image_alt,row.title,row.description) is distinct from
          (v_position,trim(v_item->>'icon_path'),nullif(trim(v_item->>'image_path'), ''),nullif(trim(v_item->>'image_alt'), ''),trim(v_item->>'title'),trim(v_item->>'description'));
      end if;
    end loop;

  elsif p_kind = 'about_timeline' then
    if exists (select 1 from jsonb_array_elements(p_items) item where jsonb_typeof(item->'year') is distinct from 'string' or jsonb_typeof(item->'label') is distinct from 'string')
    then raise exception 'Every timeline entry must be valid.' using errcode = '22023'; end if;
    if exists (select 1 from public.about_timeline row where row.id::text <> all(p_deleted_ids) and not exists (select 1 from jsonb_array_elements(p_items) item where item->>'id'=row.id::text))
      or exists (select 1 from jsonb_array_elements(p_items) item where item ? 'id' and not exists (select 1 from public.about_timeline row where row.id::text=item->>'id'))
      or exists (select 1 from unnest(p_deleted_ids) deleted_id where not exists (select 1 from public.about_timeline row where row.id::text=deleted_id))
    then raise exception 'Every existing timeline entry must be retained or explicitly removed.' using errcode = '22023'; end if;
    delete from public.about_timeline row where row.id::text = any(p_deleted_ids);
    for v_item in select value from jsonb_array_elements(p_items) loop
      v_position:=v_position+1; v_id_text:=v_item->>'id';
      if v_id_text is null then insert into public.about_timeline(sort_order,year,label) values(v_position,trim(v_item->>'year'),trim(v_item->>'label'));
      else update public.about_timeline row set sort_order=v_position,year=trim(v_item->>'year'),label=trim(v_item->>'label')
        where row.id=v_id_text::bigint and (row.sort_order,row.year,row.label) is distinct from (v_position,trim(v_item->>'year'),trim(v_item->>'label')); end if;
    end loop;

  elsif p_kind = 'about_founders' then
    if exists (select 1 from jsonb_array_elements(p_items) item where jsonb_typeof(item->'name') is distinct from 'string' or jsonb_typeof(item->'designation') is distinct from 'string' or jsonb_typeof(item->'bio') is distinct from 'string' or jsonb_typeof(item->'image_path') is distinct from 'string')
    then raise exception 'Every founder must be valid.' using errcode = '22023'; end if;
    if exists (select 1 from public.about_founders row where row.id::text <> all(p_deleted_ids) and not exists (select 1 from jsonb_array_elements(p_items) item where item->>'id'=row.id::text))
      or exists (select 1 from jsonb_array_elements(p_items) item where item ? 'id' and not exists (select 1 from public.about_founders row where row.id::text=item->>'id'))
      or exists (select 1 from unnest(p_deleted_ids) deleted_id where not exists (select 1 from public.about_founders row where row.id::text=deleted_id))
    then raise exception 'Every existing founder must be retained or explicitly removed.' using errcode = '22023'; end if;
    delete from public.about_founders row where row.id::text = any(p_deleted_ids);
    for v_item in select value from jsonb_array_elements(p_items) loop
      v_position:=v_position+1; v_id_text:=v_item->>'id';
      if v_id_text is null then insert into public.about_founders(sort_order,name,designation,bio,image_path) values(v_position,trim(v_item->>'name'),trim(v_item->>'designation'),trim(v_item->>'bio'),trim(v_item->>'image_path'));
      else update public.about_founders row set sort_order=v_position,name=trim(v_item->>'name'),designation=trim(v_item->>'designation'),bio=trim(v_item->>'bio'),image_path=trim(v_item->>'image_path')
        where row.id=v_id_text::bigint and (row.sort_order,row.name,row.designation,row.bio,row.image_path) is distinct from (v_position,trim(v_item->>'name'),trim(v_item->>'designation'),trim(v_item->>'bio'),trim(v_item->>'image_path')); end if;
    end loop;

  elsif p_kind = 'contact_info' then
    if exists (select 1 from jsonb_array_elements(p_items) item where jsonb_typeof(item->'label') is distinct from 'string' or jsonb_typeof(item->'value') is distinct from 'string' or jsonb_typeof(item->'note') is distinct from 'string' or jsonb_typeof(item->'href') is distinct from 'string' or jsonb_typeof(item->'icon_path') is distinct from 'string')
    then raise exception 'Every contact card must be valid.' using errcode = '22023'; end if;
    if exists (select 1 from public.contact_info row where row.id::text <> all(p_deleted_ids) and not exists (select 1 from jsonb_array_elements(p_items) item where item->>'id'=row.id::text))
      or exists (select 1 from jsonb_array_elements(p_items) item where item ? 'id' and not exists (select 1 from public.contact_info row where row.id::text=item->>'id'))
      or exists (select 1 from unnest(p_deleted_ids) deleted_id where not exists (select 1 from public.contact_info row where row.id::text=deleted_id))
    then raise exception 'Every existing contact card must be retained or explicitly removed.' using errcode = '22023'; end if;
    delete from public.contact_info row where row.id::text = any(p_deleted_ids);
    for v_item in select value from jsonb_array_elements(p_items) loop
      v_position:=v_position+1; v_id_text:=v_item->>'id';
      if v_id_text is null then insert into public.contact_info(sort_order,label,value,note,href,icon_path) values(v_position,trim(v_item->>'label'),trim(v_item->>'value'),trim(v_item->>'note'),trim(v_item->>'href'),trim(v_item->>'icon_path'));
      else update public.contact_info row set sort_order=v_position,label=trim(v_item->>'label'),value=trim(v_item->>'value'),note=trim(v_item->>'note'),href=trim(v_item->>'href'),icon_path=trim(v_item->>'icon_path')
        where row.id=v_id_text::bigint and (row.sort_order,row.label,row.value,row.note,row.href,row.icon_path) is distinct from (v_position,trim(v_item->>'label'),trim(v_item->>'value'),trim(v_item->>'note'),trim(v_item->>'href'),trim(v_item->>'icon_path')); end if;
    end loop;

  elsif p_kind = 'bespoke_process' then
    if exists (select 1 from jsonb_array_elements(p_items) item where jsonb_typeof(item->'eyebrow') is distinct from 'string' or jsonb_typeof(item->'title') is distinct from 'string' or jsonb_typeof(item->'description') is distinct from 'string')
    then raise exception 'Every process card must be valid.' using errcode = '22023'; end if;
    if exists (select 1 from public.bespoke_process_cards row where row.id::text <> all(p_deleted_ids) and not exists (select 1 from jsonb_array_elements(p_items) item where item->>'id'=row.id::text))
      or exists (select 1 from jsonb_array_elements(p_items) item where item ? 'id' and not exists (select 1 from public.bespoke_process_cards row where row.id::text=item->>'id'))
      or exists (select 1 from unnest(p_deleted_ids) deleted_id where not exists (select 1 from public.bespoke_process_cards row where row.id::text=deleted_id))
    then raise exception 'Every existing process card must be retained or explicitly removed.' using errcode = '22023'; end if;
    delete from public.bespoke_process_cards row where row.id::text = any(p_deleted_ids);
    for v_item in select value from jsonb_array_elements(p_items) loop
      v_position:=v_position+1; v_id_text:=v_item->>'id';
      if v_id_text is null then insert into public.bespoke_process_cards(sort_order,eyebrow,title,description) values(v_position,trim(v_item->>'eyebrow'),trim(v_item->>'title'),trim(v_item->>'description'));
      else update public.bespoke_process_cards row set sort_order=v_position,eyebrow=trim(v_item->>'eyebrow'),title=trim(v_item->>'title'),description=trim(v_item->>'description')
        where row.id=v_id_text::bigint and (row.sort_order,row.eyebrow,row.title,row.description) is distinct from (v_position,trim(v_item->>'eyebrow'),trim(v_item->>'title'),trim(v_item->>'description')); end if;
    end loop;

  elsif p_kind = 'bespoke_manufacturing' then
    if exists (select 1 from jsonb_array_elements(p_items) item where jsonb_typeof(item->'step') is distinct from 'string' or jsonb_typeof(item->'eyebrow') is distinct from 'string' or jsonb_typeof(item->'title') is distinct from 'string' or jsonb_typeof(item->'description') is distinct from 'string' or coalesce(item->>'media_type','') not in ('image','video') or jsonb_typeof(item->'media_path') is distinct from 'string' or jsonb_typeof(item->'image_path') is distinct from 'string')
    then raise exception 'Every manufacturing step must be valid.' using errcode = '22023'; end if;
    if exists (select 1 from public.bespoke_process_steps row where row.id::text <> all(p_deleted_ids) and not exists (select 1 from jsonb_array_elements(p_items) item where item->>'id'=row.id::text))
      or exists (select 1 from jsonb_array_elements(p_items) item where item ? 'id' and not exists (select 1 from public.bespoke_process_steps row where row.id::text=item->>'id'))
      or exists (select 1 from unnest(p_deleted_ids) deleted_id where not exists (select 1 from public.bespoke_process_steps row where row.id::text=deleted_id))
    then raise exception 'Every existing manufacturing step must be retained or explicitly removed.' using errcode = '22023'; end if;
    delete from public.bespoke_process_steps row where row.id::text = any(p_deleted_ids);
    for v_item in select value from jsonb_array_elements(p_items) loop
      v_position:=v_position+1; v_id_text:=v_item->>'id';
      if v_id_text is null then insert into public.bespoke_process_steps(sort_order,step,eyebrow,title,description,image_path,media_type,media_path)
        values(v_position,trim(v_item->>'step'),trim(v_item->>'eyebrow'),trim(v_item->>'title'),trim(v_item->>'description'),trim(v_item->>'image_path'),v_item->>'media_type',trim(v_item->>'media_path'));
      else update public.bespoke_process_steps row set sort_order=v_position,step=trim(v_item->>'step'),eyebrow=trim(v_item->>'eyebrow'),title=trim(v_item->>'title'),description=trim(v_item->>'description'),image_path=trim(v_item->>'image_path'),media_type=v_item->>'media_type',media_path=trim(v_item->>'media_path')
        where row.id=v_id_text::bigint and (row.sort_order,row.step,row.eyebrow,row.title,row.description,row.image_path,row.media_type,row.media_path) is distinct from
          (v_position,trim(v_item->>'step'),trim(v_item->>'eyebrow'),trim(v_item->>'title'),trim(v_item->>'description'),trim(v_item->>'image_path'),v_item->>'media_type',trim(v_item->>'media_path')); end if;
    end loop;
  end if;

  v_result := public.cms_content_list_snapshot_v1(p_kind);
  insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result)
  values(p_actor_id,p_request_id,'content-list-' || p_kind,v_hash,v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.cms_save_docs_page_v1(p_actor_id uuid, p_request_id uuid, p_slug text, p_expected_revision text, p_page jsonb, p_blocks jsonb, p_deleted_block_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_before jsonb; v_result jsonb; v_receipt public.cms_save_receipts%rowtype; v_hash text; v_page_id bigint; v_item jsonb; v_id text; v_pos integer:=0;
begin
  if p_actor_id is null or p_request_id is null or not exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin') then raise exception 'Administrator access is required.' using errcode='42501'; end if;
  if p_slug not in ('terms','privacy-policy','shipping','returns') or coalesce(p_expected_revision,'') !~ '^[0-9a-f]{32}$' or jsonb_typeof(p_page) is distinct from 'object' or jsonb_typeof(p_blocks) is distinct from 'array' or p_deleted_block_ids is null or array_position(p_deleted_block_ids,null) is not null then raise exception 'Invalid docs payload. Reload this editor.' using errcode='22023'; end if;
  if jsonb_array_length(p_blocks)>100 or cardinality(p_deleted_block_ids)>100 then raise exception 'Too many docs blocks.' using errcode='22023'; end if;
  if nullif(trim(p_page->>'title'),'') is null or nullif(trim(p_page->>'eyebrow'),'') is null or nullif(trim(p_page->>'subtitle'),'') is null then raise exception 'All page fields are required.' using errcode='22023'; end if;
  if exists(select 1 from jsonb_array_elements(p_blocks)x where jsonb_typeof(x->'heading') is distinct from 'string' or jsonb_typeof(x->'description') is distinct from 'string' or jsonb_typeof(x->'body') is distinct from 'string' or (nullif(trim(x->>'heading'),'') is null and nullif(trim(x->>'description'),'') is null and nullif(trim(x->>'body'),'') is null)) then raise exception 'Every docs block must contain content.' using errcode='22023'; end if;
  if p_slug='returns' and nullif(p_page->>'faq_category_id','') is not null and ((p_page->>'faq_category_id') !~ '^[1-9][0-9]*$' or not exists(select 1 from public.support_faq_categories c where c.id=(p_page->>'faq_category_id')::bigint)) then raise exception 'The selected FAQ category does not exist.' using errcode='23503'; end if;
  perform pg_advisory_xact_lock(hashtextextended('cms-docs:'||p_slug,0)); perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text||p_request_id::text,0));
  v_hash:=md5(jsonb_build_object('slug',p_slug,'revision',p_expected_revision,'page',p_page,'blocks',p_blocks,'deleted',p_deleted_block_ids)::text);
  select r.* into v_receipt from public.cms_save_receipts r where r.actor_id=p_actor_id and r.request_id=p_request_id;
  if found then if v_receipt.operation<>'docs-save-'||p_slug or v_receipt.payload_hash<>v_hash then raise exception 'This save request was already used for different changes.' using errcode='40001'; end if; return v_receipt.result; end if;
  v_before:=public.cms_docs_snapshot_v1(p_slug); if v_before->>'revision'<>p_expected_revision then raise exception 'This page changed since you opened it. Reload before saving.' using errcode='40001'; end if;
  v_page_id:=(v_before->'page'->>'id')::bigint;
  if (select count(distinct x) from unnest(p_deleted_block_ids)x)<>cardinality(p_deleted_block_ids)
    or exists(select 1 from jsonb_array_elements(p_blocks)x where x?'id' and (coalesce(x->>'id','') !~ '^[1-9][0-9]*$' or x->>'id'=any(p_deleted_block_ids)))
    or exists(select x->>'id' from jsonb_array_elements(p_blocks)x where x?'id' group by 1 having count(*)>1)
    or exists(select 1 from public.docs_blocks r where r.page_id=v_page_id and r.id::text<>all(p_deleted_block_ids) and not exists(select 1 from jsonb_array_elements(p_blocks)x where x->>'id'=r.id::text))
    or exists(select 1 from jsonb_array_elements(p_blocks)x where x?'id' and not exists(select 1 from public.docs_blocks r where r.page_id=v_page_id and r.id::text=x->>'id'))
    or exists(select 1 from unnest(p_deleted_block_ids)d where not exists(select 1 from public.docs_blocks r where r.page_id=v_page_id and r.id::text=d))
  then raise exception 'Every existing docs block must be retained or explicitly removed.' using errcode='22023'; end if;
  update public.docs_pages p set title=trim(p_page->>'title'),eyebrow=trim(p_page->>'eyebrow'),subtitle=trim(p_page->>'subtitle'),faq_category_id=case when p_slug='returns' then nullif(p_page->>'faq_category_id','')::bigint else p.faq_category_id end,updated_at=now() where p.id=v_page_id;
  delete from public.docs_blocks b where b.page_id=v_page_id and b.id::text=any(p_deleted_block_ids);
  for v_item in select value from jsonb_array_elements(p_blocks) loop v_pos:=v_pos+1; v_id:=v_item->>'id';
    if v_id is null then insert into public.docs_blocks(page_id,sort_order,heading,description,body) values(v_page_id,v_pos,trim(v_item->>'heading'),trim(v_item->>'description'),trim(v_item->>'body'));
    else update public.docs_blocks b set sort_order=v_pos,heading=trim(v_item->>'heading'),description=trim(v_item->>'description'),body=trim(v_item->>'body'),updated_at=now() where b.id=v_id::bigint and b.page_id=v_page_id and (b.sort_order,b.heading,b.description,b.body) is distinct from (v_pos,trim(v_item->>'heading'),trim(v_item->>'description'),trim(v_item->>'body')); end if;
  end loop;
  v_result:=public.cms_docs_snapshot_v1(p_slug); insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'docs-save-'||p_slug,v_hash,v_result); return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.cms_save_home_group1_v1(p_actor_id uuid, p_request_id uuid, p_expected_revision text, p_kind text, p_section jsonb, p_items jsonb, p_deleted_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_before jsonb; v_result jsonb; v_receipt public.cms_save_receipts%rowtype;
  v_hash text; v_item jsonb; v_id_text text; v_position integer := 0;
  v_hero_id bigint; v_section_bigint bigint; v_section_uuid uuid;
begin
  if p_actor_id is null or p_request_id is null or not exists (
    select 1 from public.profiles p where p.id = p_actor_id and p.role = 'admin'
  ) then raise exception 'Administrator access is required.' using errcode = '42501'; end if;
  if p_expected_revision is null or length(p_expected_revision) <> 32
    or p_kind not in ('hero','collection','certifications','discover_shapes','bestsellers','shop_by_category')
    or jsonb_typeof(p_items) is distinct from 'array' or p_deleted_ids is null
    or array_position(p_deleted_ids, null) is not null
  then raise exception 'Invalid save payload. Reload this editor.' using errcode = '22023'; end if;
  if jsonb_array_length(p_items) > 100 or cardinality(p_deleted_ids) > 100
  then raise exception 'Too many CMS rows.' using errcode = '22023'; end if;

  perform pg_advisory_xact_lock(hashtextextended('cms-home-group1:' || p_kind, 0));
  perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text || p_request_id::text, 0));
  v_hash := md5(jsonb_build_object('revision', p_expected_revision, 'kind', p_kind,
    'section', p_section, 'items', p_items, 'deleted', p_deleted_ids)::text);
  select receipt.* into v_receipt from public.cms_save_receipts receipt
    where receipt.actor_id = p_actor_id and receipt.request_id = p_request_id;
  if found then
    if v_receipt.operation <> 'home-group1-' || p_kind or v_receipt.payload_hash <> v_hash
    then raise exception 'This save request was already used for different changes.' using errcode = '40001'; end if;
    return v_receipt.result;
  end if;

  case p_kind
    when 'hero' then lock table public.homepage_hero, public.homepage_hero_slider_items in share row exclusive mode;
    when 'collection' then lock table public.collection_items in share row exclusive mode;
    when 'certifications' then lock table public.certifications_section, public.certifications_items in share row exclusive mode;
    when 'discover_shapes' then lock table public.discover_shapes_items in share row exclusive mode;
    when 'bestsellers' then lock table public.cms_home_bestsellers, public.cms_home_bestseller_products in share row exclusive mode;
    when 'shop_by_category' then lock table public.homepage_shop_by_category, public.homepage_shop_by_category_items in share row exclusive mode;
  end case;
  v_before := public.cms_home_group1_snapshot_v1(p_kind);
  if v_before->>'revision' <> p_expected_revision
  then raise exception 'This section changed since you opened it. Reload before saving.' using errcode = '40001'; end if;
  if (select count(distinct x) from unnest(p_deleted_ids) x) <> cardinality(p_deleted_ids)
  then raise exception 'A deleted row ID was duplicated.' using errcode = '22023'; end if;

  -- Every existing ID must be retained or explicitly deleted. New rows omit id.
  if exists (select 1 from jsonb_array_elements(p_items) x where x ? 'id' and (
      jsonb_typeof(x->'id') not in ('string','number') or nullif(x->>'id','') is null or x->>'id' = any(p_deleted_ids)))
    or exists (select id from (select value->>'id' id from jsonb_array_elements(p_items) where value ? 'id') q group by id having count(*) > 1)
  then raise exception 'A row ID is empty, duplicated, or both retained and deleted.' using errcode = '22023'; end if;

  if p_kind = 'hero' then
    v_hero_id := (v_before->'section'->>'id')::bigint;
    if v_hero_id is null or jsonb_typeof(p_section) <> 'object'
      or jsonb_typeof(p_section->'slider_enabled') <> 'boolean'
      or jsonb_typeof(p_section->'seo_title') <> 'string'
      or jsonb_typeof(p_section->'seo_description') <> 'string'
    then raise exception 'Invalid hero settings.' using errcode = '22023'; end if;
    if exists (select 1 from jsonb_array_elements(p_items) x where
      jsonb_typeof(x->'image_path') <> 'string' or jsonb_typeof(x->'mobile_image_path') <> 'string'
      or jsonb_typeof(x->'headline') <> 'string' or jsonb_typeof(x->'subtitle') <> 'string'
      or jsonb_typeof(x->'button_text') <> 'string' or jsonb_typeof(x->'button_link') <> 'string')
    then raise exception 'Invalid hero slide.' using errcode = '22023'; end if;
    if exists (select 1 from public.homepage_hero_slider_items i where i.hero_id=v_hero_id
      and i.id::text <> all(p_deleted_ids) and not exists (select 1 from jsonb_array_elements(p_items) x where x->>'id'=i.id::text))
      or exists (select 1 from jsonb_array_elements(p_items) x where x ? 'id' and not exists
        (select 1 from public.homepage_hero_slider_items i where i.hero_id=v_hero_id and i.id::text=x->>'id'))
    then raise exception 'Every existing slide must be retained or explicitly removed.' using errcode = '22023'; end if;
    update public.homepage_hero h set slider_enabled=(p_section->>'slider_enabled')::boolean,
      seo_title=nullif(trim(p_section->>'seo_title'),''), seo_description=nullif(trim(p_section->>'seo_description'),''), is_active=true
      where h.id=v_hero_id and (h.slider_enabled,h.seo_title,h.seo_description,h.is_active) is distinct from
      ((p_section->>'slider_enabled')::boolean,nullif(trim(p_section->>'seo_title'),''),nullif(trim(p_section->>'seo_description'),''),true);
    delete from public.homepage_hero_slider_items i where i.hero_id=v_hero_id and i.id::text=any(p_deleted_ids);
    for v_item in select value from jsonb_array_elements(p_items) loop
      v_position:=v_position+1; v_id_text:=v_item->>'id';
      if v_id_text is null then insert into public.homepage_hero_slider_items
        (hero_id,sort_order,image_path,mobile_image_path,headline,subtitle,button_text,button_link)
        values(v_hero_id,v_position,v_item->>'image_path',v_item->>'mobile_image_path',v_item->>'headline',v_item->>'subtitle',v_item->>'button_text',v_item->>'button_link');
      else update public.homepage_hero_slider_items i set sort_order=v_position,image_path=v_item->>'image_path',mobile_image_path=v_item->>'mobile_image_path',
        headline=v_item->>'headline',subtitle=v_item->>'subtitle',button_text=v_item->>'button_text',button_link=v_item->>'button_link'
        where i.id=v_id_text::bigint and (i.sort_order,i.image_path,i.mobile_image_path,i.headline,i.subtitle,i.button_text,i.button_link) is distinct from
        (v_position,v_item->>'image_path',v_item->>'mobile_image_path',v_item->>'headline',v_item->>'subtitle',v_item->>'button_text',v_item->>'button_link'); end if;
    end loop;

  elsif p_kind = 'collection' then
    if jsonb_typeof(p_section) <> 'null' or exists (select 1 from jsonb_array_elements(p_items) x where
      jsonb_typeof(x->'label') <> 'string' or jsonb_typeof(x->'title') <> 'string' or jsonb_typeof(x->'description') <> 'string'
      or jsonb_typeof(x->'image_path') <> 'string' or jsonb_typeof(x->'link') <> 'string')
    then raise exception 'Invalid collection content.' using errcode = '22023'; end if;
    if exists (select 1 from public.collection_items i where i.id::text <> all(p_deleted_ids)
      and not exists (select 1 from jsonb_array_elements(p_items) x where x->>'id'=i.id::text))
      or exists (select 1 from jsonb_array_elements(p_items) x where x ? 'id' and not exists
        (select 1 from public.collection_items i where i.id::text=x->>'id'))
    then raise exception 'Every existing collection item must be retained or explicitly removed.' using errcode = '22023'; end if;
    delete from public.collection_items i where i.id::text=any(p_deleted_ids);
    for v_item in select value from jsonb_array_elements(p_items) loop
      v_position:=v_position+1; v_id_text:=v_item->>'id';
      if v_id_text is null then insert into public.collection_items(sort_order,label,title,description,image_path,link)
        values(v_position,trim(v_item->>'label'),trim(v_item->>'title'),trim(v_item->>'description'),trim(v_item->>'image_path'),trim(v_item->>'link'));
      else update public.collection_items i set sort_order=v_position,label=trim(v_item->>'label'),title=trim(v_item->>'title'),description=trim(v_item->>'description'),image_path=trim(v_item->>'image_path'),link=trim(v_item->>'link')
        where i.id=v_id_text::bigint and (i.sort_order,i.label,i.title,i.description,i.image_path,i.link) is distinct from
        (v_position,trim(v_item->>'label'),trim(v_item->>'title'),trim(v_item->>'description'),trim(v_item->>'image_path'),trim(v_item->>'link')); end if;
    end loop;

  elsif p_kind = 'certifications' then
    if jsonb_typeof(p_section) <> 'object' or jsonb_typeof(p_section->'eyebrow') <> 'string' or jsonb_typeof(p_section->'heading') <> 'string'
      or exists (select 1 from jsonb_array_elements(p_items) x where jsonb_typeof(x->'title') <> 'string' or jsonb_typeof(x->'description') <> 'string'
        or jsonb_typeof(x->'badge') <> 'string' or jsonb_typeof(x->'icon_path') <> 'string')
    then raise exception 'Invalid certifications content.' using errcode = '22023'; end if;
    if exists (select 1 from public.certifications_items i where i.id::text <> all(p_deleted_ids)
      and not exists (select 1 from jsonb_array_elements(p_items) x where x->>'id'=i.id::text))
      or exists (select 1 from jsonb_array_elements(p_items) x where x ? 'id' and not exists
        (select 1 from public.certifications_items i where i.id::text=x->>'id'))
    then raise exception 'Every existing certification must be retained or explicitly removed.' using errcode = '22023'; end if;
    insert into public.certifications_section as target(section_key,eyebrow,heading) values('home_certifications',trim(p_section->>'eyebrow'),trim(p_section->>'heading'))
      on conflict(section_key) do update set eyebrow=excluded.eyebrow,heading=excluded.heading
      where (target.eyebrow,target.heading) is distinct from (excluded.eyebrow,excluded.heading);
    delete from public.certifications_items i where i.id::text=any(p_deleted_ids);
    for v_item in select value from jsonb_array_elements(p_items) loop
      v_position:=v_position+1; v_id_text:=v_item->>'id';
      if v_id_text is null then insert into public.certifications_items(sort_order,title,description,badge,icon_path)
        values(v_position,trim(v_item->>'title'),trim(v_item->>'description'),trim(v_item->>'badge'),trim(v_item->>'icon_path'));
      else update public.certifications_items i set sort_order=v_position,title=trim(v_item->>'title'),description=trim(v_item->>'description'),badge=trim(v_item->>'badge'),icon_path=trim(v_item->>'icon_path')
        where i.id=v_id_text::bigint and (i.sort_order,i.title,i.description,i.badge,i.icon_path) is distinct from
        (v_position,trim(v_item->>'title'),trim(v_item->>'description'),trim(v_item->>'badge'),trim(v_item->>'icon_path')); end if;
    end loop;

  elsif p_kind = 'discover_shapes' then
    if jsonb_typeof(p_section) <> 'null' or exists (select 1 from jsonb_array_elements(p_items) x where
      jsonb_typeof(x->'title') <> 'string' or jsonb_typeof(x->'description') <> 'string' or jsonb_typeof(x->'image_path') <> 'string'
      or jsonb_typeof(x->'image_alt') <> 'string' or (x->'shape_id' <> 'null' and jsonb_typeof(x->'shape_id') <> 'string'))
    then raise exception 'Invalid shape content.' using errcode = '22023'; end if;
    if exists (select 1 from public.discover_shapes_items i where i.id::text <> all(p_deleted_ids)
      and not exists (select 1 from jsonb_array_elements(p_items) x where x->>'id'=i.id::text))
      or exists (select 1 from jsonb_array_elements(p_items) x where x ? 'id' and not exists
        (select 1 from public.discover_shapes_items i where i.id::text=x->>'id'))
    then raise exception 'Every existing shape card must be retained or explicitly removed.' using errcode = '22023'; end if;
    delete from public.discover_shapes_items i where i.id::text=any(p_deleted_ids);
    for v_item in select value from jsonb_array_elements(p_items) loop
      v_position:=v_position+1; v_id_text:=v_item->>'id';
      if v_id_text is null then insert into public.discover_shapes_items(title,description,image_path,image_alt,shape_id,sort_order,status)
        values(trim(v_item->>'title'),trim(v_item->>'description'),trim(v_item->>'image_path'),trim(v_item->>'image_alt'),nullif(v_item->>'shape_id','')::uuid,v_position,'active');
      else update public.discover_shapes_items i set title=trim(v_item->>'title'),description=trim(v_item->>'description'),image_path=trim(v_item->>'image_path'),image_alt=trim(v_item->>'image_alt'),shape_id=nullif(v_item->>'shape_id','')::uuid,sort_order=v_position,status='active'
        where i.id=v_id_text::uuid and (i.title,i.description,i.image_path,i.image_alt,i.shape_id,i.sort_order,i.status) is distinct from
        (trim(v_item->>'title'),trim(v_item->>'description'),trim(v_item->>'image_path'),trim(v_item->>'image_alt'),nullif(v_item->>'shape_id','')::uuid,v_position,'active'); end if;
    end loop;

  elsif p_kind = 'bestsellers' then
    if jsonb_typeof(p_section) <> 'object' or jsonb_typeof(p_section->'eyebrow') <> 'string' or jsonb_typeof(p_section->'heading') <> 'string'
      or jsonb_typeof(p_section->'cta_label') <> 'string' or jsonb_typeof(p_section->'cta_href') <> 'string'
      or exists (select 1 from jsonb_array_elements(p_items) x where jsonb_typeof(x->'product_id') <> 'string'
        or jsonb_typeof(x->'display_title') not in ('string','null') or jsonb_typeof(x->'display_image_path') not in ('string','null'))
    then raise exception 'Invalid bestseller content.' using errcode = '22023'; end if;
    v_section_uuid := nullif(v_before->'section'->>'id','')::uuid;
    if v_section_uuid is null then insert into public.cms_home_bestsellers(eyebrow,heading,cta_label,cta_href,status)
      values(trim(p_section->>'eyebrow'),trim(p_section->>'heading'),trim(p_section->>'cta_label'),trim(p_section->>'cta_href'),'active') returning id into v_section_uuid;
    else update public.cms_home_bestsellers s set eyebrow=trim(p_section->>'eyebrow'),heading=trim(p_section->>'heading'),cta_label=trim(p_section->>'cta_label'),cta_href=trim(p_section->>'cta_href'),status='active'
      where s.id=v_section_uuid and (s.eyebrow,s.heading,s.cta_label,s.cta_href,s.status) is distinct from
      (trim(p_section->>'eyebrow'),trim(p_section->>'heading'),trim(p_section->>'cta_label'),trim(p_section->>'cta_href'),'active'::public.cms_status); end if;
    if exists (select 1 from public.cms_home_bestseller_products i where i.section_id=v_section_uuid and i.id::text <> all(p_deleted_ids)
      and not exists (select 1 from jsonb_array_elements(p_items) x where x->>'id'=i.id::text))
      or exists (select 1 from jsonb_array_elements(p_items) x where x ? 'id' and not exists
        (select 1 from public.cms_home_bestseller_products i where i.section_id=v_section_uuid and i.id::text=x->>'id'))
      or exists (select 1 from jsonb_array_elements(p_items) x where not exists
        (select 1 from public.products p where p.id=(x->>'product_id')::uuid and p.status='active'))
    then raise exception 'Bestseller rows or products are stale.' using errcode = '22023'; end if;
    perform 1 from public.products p join jsonb_array_elements(p_items) x on p.id=(x->>'product_id')::uuid
      where p.status='active' for key share of p;
    delete from public.cms_home_bestseller_products i where i.section_id=v_section_uuid and i.id::text=any(p_deleted_ids);
    for v_item in select value from jsonb_array_elements(p_items) loop
      v_id_text:=v_item->>'id';
      if v_id_text is null then insert into public.cms_home_bestseller_products(section_id,product_id,display_order,display_title,display_image_path)
        values(v_section_uuid,(v_item->>'product_id')::uuid,v_position,nullif(trim(v_item->>'display_title'),''),nullif(trim(v_item->>'display_image_path'),''));
      else update public.cms_home_bestseller_products i set product_id=(v_item->>'product_id')::uuid,display_order=v_position,display_title=nullif(trim(v_item->>'display_title'),''),display_image_path=nullif(trim(v_item->>'display_image_path'),'')
        where i.id=v_id_text::uuid and (i.product_id,i.display_order,i.display_title,i.display_image_path) is distinct from
        ((v_item->>'product_id')::uuid,v_position,nullif(trim(v_item->>'display_title'),''),nullif(trim(v_item->>'display_image_path'),'')); end if;
      v_position:=v_position+1;
    end loop;

  elsif p_kind = 'shop_by_category' then
    if jsonb_typeof(p_section) <> 'object' or jsonb_typeof(p_section->'heading') <> 'string'
      or jsonb_typeof(p_section->'is_enabled') <> 'boolean' then raise exception 'Invalid shop settings.' using errcode = '22023'; end if;
    v_section_bigint := nullif(v_before->'section'->>'id','')::bigint;
    if v_section_bigint is null then insert into public.homepage_shop_by_category(section_key,heading,shop_all_label,shop_all_link,is_enabled,desktop_columns,tablet_columns,mobile_columns)
      values('home_shop_by_category',trim(p_section->>'heading'),nullif(trim(p_section->>'shop_all_label'),''),nullif(trim(p_section->>'shop_all_link'),''),(p_section->>'is_enabled')::boolean,(p_section->>'desktop_columns')::smallint,(p_section->>'tablet_columns')::smallint,(p_section->>'mobile_columns')::smallint) returning id into v_section_bigint;
    else update public.homepage_shop_by_category s set heading=trim(p_section->>'heading'),shop_all_label=nullif(trim(p_section->>'shop_all_label'),''),shop_all_link=nullif(trim(p_section->>'shop_all_link'),''),is_enabled=(p_section->>'is_enabled')::boolean,desktop_columns=(p_section->>'desktop_columns')::smallint,tablet_columns=(p_section->>'tablet_columns')::smallint,mobile_columns=(p_section->>'mobile_columns')::smallint
      where s.id=v_section_bigint and (s.heading,s.shop_all_label,s.shop_all_link,s.is_enabled,s.desktop_columns,s.tablet_columns,s.mobile_columns) is distinct from
      (trim(p_section->>'heading'),nullif(trim(p_section->>'shop_all_label'),''),nullif(trim(p_section->>'shop_all_link'),''),(p_section->>'is_enabled')::boolean,(p_section->>'desktop_columns')::smallint,(p_section->>'tablet_columns')::smallint,(p_section->>'mobile_columns')::smallint); end if;
    if exists (select 1 from public.homepage_shop_by_category_items i where i.section_id=v_section_bigint and i.id::text <> all(p_deleted_ids)
      and not exists (select 1 from jsonb_array_elements(p_items) x where x->>'id'=i.id::text))
      or exists (select 1 from jsonb_array_elements(p_items) x where x ? 'id' and not exists
        (select 1 from public.homepage_shop_by_category_items i where i.section_id=v_section_bigint and i.id::text=x->>'id'))
    then raise exception 'Shop rows are stale.' using errcode = '22023'; end if;
    if exists (select 1 from jsonb_array_elements(p_items) x where
      ((x->>'item_type'='category')::integer + (x->>'item_type'='subcategory')::integer + (x->>'item_type'='option')::integer) <> 1
      or (x->>'item_type'='category' and (x->>'category_id' is null or x->>'subcategory_id' is not null or x->>'option_id' is not null))
      or (x->>'item_type'='subcategory' and (x->>'subcategory_id' is null or x->>'category_id' is not null or x->>'option_id' is not null))
      or (x->>'item_type'='option' and (x->>'option_id' is null or x->>'category_id' is not null or x->>'subcategory_id' is not null))
      or (x->>'item_type'='category' and not exists(select 1 from public.catalog_categories c where c.id=(x->>'category_id')::uuid and c.status='active'))
      or (x->>'item_type'='subcategory' and not exists(select 1 from public.catalog_subcategories c where c.id=(x->>'subcategory_id')::uuid and c.status='active'))
      or (x->>'item_type'='option' and not exists(select 1 from public.catalog_options c where c.id=(x->>'option_id')::uuid and c.status='active')))
      or exists (select 1 from jsonb_array_elements(p_items) x group by x->>'item_type',coalesce(x->>'category_id',x->>'subcategory_id',x->>'option_id') having count(*)>1)
    then raise exception 'Shop items must be unique active catalog records.' using errcode='22023'; end if;
    perform 1 from public.catalog_categories c join jsonb_array_elements(p_items) x on x->>'item_type'='category' and c.id=(x->>'category_id')::uuid for key share of c;
    perform 1 from public.catalog_subcategories c join jsonb_array_elements(p_items) x on x->>'item_type'='subcategory' and c.id=(x->>'subcategory_id')::uuid for key share of c;
    perform 1 from public.catalog_options c join jsonb_array_elements(p_items) x on x->>'item_type'='option' and c.id=(x->>'option_id')::uuid for key share of c;
    delete from public.homepage_shop_by_category_items i where i.section_id=v_section_bigint and i.id::text=any(p_deleted_ids);
    for v_item in select value from jsonb_array_elements(p_items) loop
      if v_item->>'item_type' not in ('category','subcategory','option') then raise exception 'Invalid shop item type.' using errcode='22023'; end if;
      v_id_text:=v_item->>'id';
      if v_id_text is null then insert into public.homepage_shop_by_category_items(section_id,item_type,category_id,subcategory_id,option_id,display_order,is_active)
        values(v_section_bigint,v_item->>'item_type',nullif(v_item->>'category_id','')::uuid,nullif(v_item->>'subcategory_id','')::uuid,nullif(v_item->>'option_id','')::uuid,v_position,(v_item->>'is_active')::boolean);
      else update public.homepage_shop_by_category_items i set item_type=v_item->>'item_type',category_id=nullif(v_item->>'category_id','')::uuid,subcategory_id=nullif(v_item->>'subcategory_id','')::uuid,option_id=nullif(v_item->>'option_id','')::uuid,display_order=v_position,is_active=(v_item->>'is_active')::boolean
        where i.id=v_id_text::bigint and (i.item_type,i.category_id,i.subcategory_id,i.option_id,i.display_order,i.is_active) is distinct from
        (v_item->>'item_type',nullif(v_item->>'category_id','')::uuid,nullif(v_item->>'subcategory_id','')::uuid,nullif(v_item->>'option_id','')::uuid,v_position,(v_item->>'is_active')::boolean); end if;
      v_position:=v_position+1;
    end loop;
  end if;

  v_result := public.cms_home_group1_snapshot_v1(p_kind);
  insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result)
    values(p_actor_id,p_request_id,'home-group1-'||p_kind,v_hash,v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.cms_save_reels_v1(p_actor_id uuid, p_request_id uuid, p_expected_revision text, p_section jsonb, p_items jsonb, p_deleted_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_snapshot jsonb;
  v_result jsonb;
  v_receipt public.cms_save_receipts%rowtype;
  v_item jsonb;
  v_current public.home_instagram_reels%rowtype;
  v_id uuid;
  v_ids uuid[] := array[]::uuid[];
  v_urls text[] := array[]::text[];
  v_hash text;
  v_position integer := 0;
begin
  if p_actor_id is null or p_request_id is null or not exists (
    select 1 from public.profiles p where p.id = p_actor_id and p.role = 'admin'
  ) then
    raise exception 'Administrator access is required.' using errcode = '42501';
  end if;
  if p_expected_revision is null or length(p_expected_revision) <> 32
    or jsonb_typeof(p_section) is distinct from 'object'
    or jsonb_typeof(p_items) is distinct from 'array'
    or p_deleted_ids is null or array_position(p_deleted_ids, null) is not null then
    raise exception 'Invalid save payload. Reload this editor.' using errcode = '22023';
  end if;
  if jsonb_array_length(p_items) > 30 or cardinality(p_deleted_ids) > 30 then
    raise exception 'A maximum of 30 reels is allowed.' using errcode = '22023';
  end if;
  if jsonb_typeof(p_section->'heading') is distinct from 'string'
    or length(trim(p_section->>'heading')) not between 1 and 120
    or jsonb_typeof(p_section->'subtitle') is distinct from 'string'
    or length(p_section->>'subtitle') > 240
    or jsonb_typeof(p_section->'is_enabled') is distinct from 'boolean'
    or jsonb_typeof(p_section->'pause_on_hover') is distinct from 'boolean'
    or jsonb_typeof(p_section->'marquee_duration_seconds') is distinct from 'number'
    or (p_section->>'marquee_duration_seconds')::numeric not between 10 and 180
    or trunc((p_section->>'marquee_duration_seconds')::numeric) <> (p_section->>'marquee_duration_seconds')::numeric then
    raise exception 'Invalid section settings.' using errcode = '22023';
  end if;

  -- Serialize retries for a given actor/request, including a reused request ID.
  perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text || p_request_id::text, 0));
  v_hash := md5(jsonb_build_object('revision', p_expected_revision, 'section', p_section,
    'items', p_items, 'deleted', p_deleted_ids)::text);
  select receipt.* into v_receipt from public.cms_save_receipts receipt
    where receipt.actor_id = p_actor_id and receipt.request_id = p_request_id;
  if found then
    if v_receipt.operation <> 'reels-v1' or v_receipt.payload_hash <> v_hash then
      raise exception 'This save request was already used for different changes.' using errcode = '40001';
    end if;
    return v_receipt.result;
  end if;

  -- These small CMS tables are locked only for this short transaction. This also
  -- serializes writes from legacy tools, which do not take advisory locks.
  lock table public.home_instagram_reels_section, public.home_instagram_reels in share row exclusive mode;
  v_snapshot := public.cms_reels_snapshot_v1();
  if v_snapshot->>'revision' <> p_expected_revision then
    raise exception 'Reels changed since you opened this page. Reload before saving.' using errcode = '40001';
  end if;

  -- Validate every row and its ownership before performing any content writes.
  for v_item in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(v_item) is distinct from 'object'
      or jsonb_typeof(v_item->'instagram_url') is distinct from 'string'
      or (v_item->>'instagram_url') !~ '^https://www[.]instagram[.]com/(reel|reels|p|tv)/[A-Za-z0-9_-]+/$'
      or length(v_item->>'instagram_url') > 500
      or jsonb_typeof(v_item->'title') is distinct from 'string'
      or length(v_item->>'title') > 100
      or jsonb_typeof(v_item->'is_enabled') is distinct from 'boolean' then
      raise exception 'Invalid reel at row %.', v_position + 1 using errcode = '22023';
    end if;
    if v_item->>'instagram_url' = any(v_urls) then
      raise exception 'Each reel URL must be unique.' using errcode = '22023';
    end if;
    v_urls := array_append(v_urls, v_item->>'instagram_url');
    if v_item ? 'id' then
      if jsonb_typeof(v_item->'id') is distinct from 'string' then
        raise exception 'Existing reel IDs cannot be empty.' using errcode = '22023';
      end if;
      v_id := (v_item->>'id')::uuid;
      if v_id = any(v_ids) or v_id = any(p_deleted_ids) or not exists (
        select 1 from public.home_instagram_reels r
        where r.id = v_id and r.section_key = 'home_instagram_reels'
      ) then
        raise exception 'A reel ID is duplicated, removed, or does not belong to this section.' using errcode = '22023';
      end if;
      v_ids := array_append(v_ids, v_id);
    end if;
    if v_item ? 'cover_image_url' and v_item->'cover_image_url' <> 'null'::jsonb and (
      jsonb_typeof(v_item->'cover_image_url') <> 'string'
      or length(v_item->>'cover_image_url') > 1000
      or (v_item->>'cover_image_url') !~ '^https?://[^[:space:]]+$'
    ) then
      raise exception 'Invalid cover image URL.' using errcode = '22023';
    end if;
    v_position := v_position + 1;
  end loop;
  if (select count(distinct removed_id) from unnest(p_deleted_ids) removed_id) <> cardinality(p_deleted_ids)
    or exists (select 1 from unnest(p_deleted_ids) removed_id where not exists (
      select 1 from public.home_instagram_reels r where r.id = removed_id and r.section_key = 'home_instagram_reels'))
    or exists (select 1 from public.home_instagram_reels r where r.section_key = 'home_instagram_reels'
      and not (r.id = any(v_ids)) and not (r.id = any(p_deleted_ids))) then
    raise exception 'Every existing reel must be retained or explicitly removed.' using errcode = '22023';
  end if;

  insert into public.home_instagram_reels_section as target
    (section_key, heading, subtitle, is_enabled, marquee_duration_seconds, pause_on_hover)
  values ('home_instagram_reels', trim(p_section->>'heading'), trim(p_section->>'subtitle'),
    (p_section->>'is_enabled')::boolean, (p_section->>'marquee_duration_seconds')::integer,
    (p_section->>'pause_on_hover')::boolean)
  on conflict (section_key) do update set
    heading = excluded.heading, subtitle = excluded.subtitle, is_enabled = excluded.is_enabled,
    marquee_duration_seconds = excluded.marquee_duration_seconds, pause_on_hover = excluded.pause_on_hover
  where (target.heading, target.subtitle, target.is_enabled, target.marquee_duration_seconds, target.pause_on_hover)
    is distinct from (excluded.heading, excluded.subtitle, excluded.is_enabled, excluded.marquee_duration_seconds, excluded.pause_on_hover);

  delete from public.home_instagram_reels r
    where r.section_key = 'home_instagram_reels' and r.id = any(p_deleted_ids);
  v_position := 0;
  for v_item in select value from jsonb_array_elements(p_items) loop
    if v_item ? 'id' then
      select r.* into strict v_current from public.home_instagram_reels r where r.id = (v_item->>'id')::uuid;
      update public.home_instagram_reels r set
        instagram_url = v_item->>'instagram_url', title = v_item->>'title',
        display_order = v_position, is_enabled = (v_item->>'is_enabled')::boolean,
        cover_image_url = case when v_item ? 'cover_image_url' then v_item->>'cover_image_url' else v_current.cover_image_url end
      where r.id = v_current.id and r.section_key = 'home_instagram_reels'
        and (r.instagram_url, r.title, r.display_order, r.is_enabled, r.cover_image_url)
        is distinct from (v_item->>'instagram_url', v_item->>'title', v_position, (v_item->>'is_enabled')::boolean,
          case when v_item ? 'cover_image_url' then v_item->>'cover_image_url' else v_current.cover_image_url end);
    else
      insert into public.home_instagram_reels
        (section_key, instagram_url, title, display_order, is_enabled, created_by, cover_image_url)
      values ('home_instagram_reels', v_item->>'instagram_url', v_item->>'title', v_position,
        (v_item->>'is_enabled')::boolean, p_actor_id, v_item->>'cover_image_url');
    end if;
    v_position := v_position + 1;
  end loop;

  v_result := public.cms_reels_snapshot_v1();
  insert into public.cms_save_receipts (actor_id, request_id, operation, payload_hash, result)
    values (p_actor_id, p_request_id, 'reels-v1', v_hash, v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.cms_save_relational_v1(p_actor_id uuid, p_request_id uuid, p_expected_revision text, p_kind text, p_parent jsonb, p_items jsonb, p_deleted_ids text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_before jsonb; v_result jsonb; v_receipt public.cms_save_receipts%rowtype; v_hash text; v_parent_id text; v_item jsonb; v_id text;
begin
  if p_actor_id is null or p_request_id is null or not exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin') then raise exception 'Administrator access is required.' using errcode='42501'; end if;
  if p_kind not in ('checkout_result','promotion','service_banner','summary','announcement','faq') or coalesce(p_expected_revision,'') !~ '^[0-9a-f]{32}$' or jsonb_typeof(p_parent) is distinct from 'object' or jsonb_typeof(p_items) is distinct from 'array' then raise exception 'Invalid relational save payload. Reload this editor.' using errcode='22023'; end if;
  if cardinality(p_deleted_ids)<>cardinality(array(select distinct x from unnest(p_deleted_ids) x)) then raise exception 'Deleted IDs must be unique.' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('cms-relational:'||p_kind,0));
  perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text||p_request_id::text,0));
  v_hash:=md5(jsonb_build_object('kind',p_kind,'revision',p_expected_revision,'parent',p_parent,'items',p_items,'deleted',p_deleted_ids)::text);
  select r.* into v_receipt from public.cms_save_receipts r where r.actor_id=p_actor_id and r.request_id=p_request_id;
  if found then if v_receipt.operation<>'relational-save-'||p_kind or v_receipt.payload_hash<>v_hash then raise exception 'This save request was already used for different changes.' using errcode='40001'; end if; return v_receipt.result; end if;
  v_before:=public.cms_relational_snapshot_v1(p_kind);
  if v_before->>'revision'<>p_expected_revision then raise exception 'This section changed since you opened it. Reload before saving.' using errcode='40001'; end if;

  case p_kind
    when 'checkout_result' then
      if jsonb_array_length(p_items)<>4 or exists(select 1 from jsonb_array_elements(p_items) x where x->>'state' not in ('success','pending','failed','error')) or (select count(distinct x->>'state') from jsonb_array_elements(p_items)x)<>4 then raise exception 'All four checkout states are required.' using errcode='22023'; end if;
      insert into public.checkout_result_page(id,main_banner_image_path,main_banner_image_alt,secondary_banner_image_path,secondary_banner_image_alt,secondary_eyebrow,secondary_heading,secondary_paragraph,is_enabled)
      values(1,nullif(trim(p_parent->>'main_banner_image_path'),''),nullif(trim(p_parent->>'main_banner_image_alt'),''),nullif(trim(p_parent->>'secondary_banner_image_path'),''),nullif(trim(p_parent->>'secondary_banner_image_alt'),''),nullif(trim(p_parent->>'secondary_eyebrow'),''),nullif(trim(p_parent->>'secondary_heading'),''),nullif(trim(p_parent->>'secondary_paragraph'),''),(p_parent->>'is_enabled')::boolean)
      on conflict(id) do update set main_banner_image_path=excluded.main_banner_image_path,main_banner_image_alt=excluded.main_banner_image_alt,secondary_banner_image_path=excluded.secondary_banner_image_path,secondary_banner_image_alt=excluded.secondary_banner_image_alt,secondary_eyebrow=excluded.secondary_eyebrow,secondary_heading=excluded.secondary_heading,secondary_paragraph=excluded.secondary_paragraph,is_enabled=excluded.is_enabled,updated_at=now();
      for v_item in select * from jsonb_array_elements(p_items) loop
        insert into public.checkout_result_states(state,eyebrow,heading,paragraph,order_button_label,is_enabled) values(v_item->>'state',nullif(trim(v_item->>'eyebrow'),''),nullif(trim(v_item->>'heading'),''),nullif(trim(v_item->>'paragraph'),''),nullif(trim(v_item->>'order_button_label'),''),(v_item->>'is_enabled')::boolean)
        on conflict(state) do update set eyebrow=excluded.eyebrow,heading=excluded.heading,paragraph=excluded.paragraph,order_button_label=excluded.order_button_label,is_enabled=excluded.is_enabled,updated_at=now();
      end loop;
    when 'promotion' then
      insert into public.promotion_popup(section_key,label,title,description,cta_text,cta_link,cta_action,selected_coupon_id,image_path,mobile_image_path,image_alt,image_only_mode,is_active,show_once_per_session)
      values('global_promotion_popup',p_parent->>'label',p_parent->>'title',p_parent->>'description',p_parent->>'cta_text',p_parent->>'cta_link',p_parent->>'cta_action',nullif(p_parent->>'selected_coupon_id','')::bigint,p_parent->>'image_path',nullif(p_parent->>'mobile_image_path',''),nullif(p_parent->>'image_alt',''),(p_parent->>'image_only_mode')::boolean,(p_parent->>'is_active')::boolean,(p_parent->>'show_once_per_session')::boolean)
      on conflict(section_key) do update set label=excluded.label,title=excluded.title,description=excluded.description,cta_text=excluded.cta_text,cta_link=excluded.cta_link,cta_action=excluded.cta_action,selected_coupon_id=excluded.selected_coupon_id,image_path=excluded.image_path,mobile_image_path=excluded.mobile_image_path,image_alt=excluded.image_alt,image_only_mode=excluded.image_only_mode,is_active=excluded.is_active,show_once_per_session=excluded.show_once_per_session,updated_at=now() returning id::text into v_parent_id;
      if exists(select 1 from public.promotion_popup_questions x where x.promotion_id=v_parent_id::bigint and not(x.id::text=any(p_deleted_ids)) and not exists(select 1 from jsonb_array_elements(p_items)i where i->>'id'=x.id::text)) then raise exception 'Questions may only be removed explicitly.' using errcode='22023'; end if;
