 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_item jsonb;
  v_content jsonb;
begin
  case p_kind
    when 'about_hero' then
      select to_jsonb(r)-'id'-'created_at'-'updated_at' into v_item from public.about_hero r where r.section_key='about_hero';
    when 'about_wide_banner' then
      select to_jsonb(r)-'id'-'created_at'-'updated_at' into v_item from public.about_wide_banner r where r.section_key='about_wide_banner';
    when 'blog_hero' then
      select to_jsonb(r)-'id'-'created_at'-'updated_at' into v_item from public.blog_page_hero r where r.id=1;
    when 'education_hero' then
      select to_jsonb(r)-'id'-'updated_at' into v_item from public.education_page_hero r where r.id=1;
    when 'contact_hero' then
      select to_jsonb(r)-'id'-'created_at'-'updated_at' into v_item from public.contact_hero r where r.section_key='contact_hero';
    when 'bespoke_showcase' then
      select to_jsonb(r)-'id'-'created_at'-'updated_at' into v_item from public.home_bespoke_showcase_section r where r.section_key='home_bespoke_showcase';
    when 'collection_page' then
      select to_jsonb(r)-'id'-'created_at'-'updated_at' into v_item from public.collection_page_config r where r.section_key='main_collection_page';
    when 'hiphop_showcase' then
      select to_jsonb(r)-'id'-'created_at'-'updated_at' into v_item from public.hiphop_showcase_section r where r.section_key='home_hiphop_showcase';
    else
      raise exception 'Unsupported CMS singleton.' using errcode='22023';
  end case;
  v_content:=jsonb_build_object('item',v_item);
  return v_content||jsonb_build_object('revision',md5(v_content::text));
end;
$function$

CREATE OR REPLACE FUNCTION public.duplicate_product(p_source_product_id uuid, p_request_id uuid, p_admin_id uuid)
 RETURNS TABLE(product_id uuid, slug text, lane text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_source public.products%rowtype;
  v_new_product public.products%rowtype;
  v_existing_product_id uuid;
  v_new_product_id uuid := gen_random_uuid();
  v_suffix text := replace(gen_random_uuid()::text, '-', '');
  v_new_slug text;
  v_new_sku text;
  v_payload jsonb;
  v_old_purity record;
  v_new_purity_id uuid;
  v_old_variant record;
  v_new_variant_id uuid;
begin
  if p_source_product_id is null or p_request_id is null or p_admin_id is null then
    raise exception 'Source product, request, and administrator IDs are required.';
  end if;

  if not exists (
    select 1 from public.profiles
    where id = p_admin_id and role = 'admin'
  ) then
    raise exception 'Only an administrator can duplicate products.';
  end if;

  -- Serialize identical request IDs so concurrent clicks cannot create two copies.
  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text, 0));

  select r.new_product_id into v_existing_product_id
  from public.product_duplicate_requests r
  where r.request_id = p_request_id;

  if v_existing_product_id is not null then
    return query
    select p.id, p.slug, coalesce(p.product_lane, 'standard')
    from public.products p
    where p.id = v_existing_product_id;
    return;
  end if;

  select p.* into v_source
  from public.products p
  where p.id = p_source_product_id
  for share;

  if not found then
    raise exception 'Source product was not found.';
  end if;

  insert into public.product_duplicate_requests (request_id, source_product_id, requested_by)
  values (p_request_id, p_source_product_id, p_admin_id)
  on conflict (request_id) do nothing;

  v_new_slug :=
    coalesce(
      nullif(btrim(regexp_replace(lower(coalesce(v_source.slug, v_source.name)), '[^a-z0-9]+', '-', 'g'), '-'), ''),
      'product'
    ) || '-copy-' || left(v_suffix, 12);
  v_new_sku := left(coalesce(nullif(trim(v_source.sku), ''), 'PRODUCT'), 80)
    || '-COPY-' || upper(left(v_suffix, 8));

  v_payload :=
    to_jsonb(v_source)
    || jsonb_build_object(
      'id', v_new_product_id,
      'name', v_source.name || ' — Copy',
      'slug', v_new_slug,
      'sku', v_new_sku,
      'status', 'draft',
      'stock_quantity', 0,
      'allow_checkout', false,
      'featured', false,
      'ready_to_ship', false,
      'default_purity_price_id', null,
      'duplicated_from_product_id', v_source.id,
      'duplicated_by', p_admin_id,
      'duplicated_at', now(),
      'created_at', now(),
      'updated_at', now()
    );

  insert into public.products
  select (jsonb_populate_record(null::public.products, v_payload)).*
  returning * into v_new_product;

  insert into public.product_metal_selections (product_id, metal_id, sort_order)
  select v_new_product.id, s.metal_id, s.sort_order
  from public.product_metal_selections s where s.product_id = v_source.id;

  insert into public.product_material_value_selections (product_id, material_value_id, sort_order)
  select v_new_product.id, s.material_value_id, s.sort_order
  from public.product_material_value_selections s where s.product_id = v_source.id;

  insert into public.product_stone_shapes (product_id, shape_id)
  select v_new_product.id, s.shape_id
  from public.product_stone_shapes s where s.product_id = v_source.id;

  insert into public.product_subcategory_links (product_id, subcategory_id, is_primary, sort_order)
  select v_new_product.id, s.subcategory_id, s.is_primary, s.sort_order
  from public.product_subcategory_links s where s.product_id = v_source.id;

  insert into public.product_option_links (product_id, option_id, is_primary, sort_order)
  select v_new_product.id, o.option_id, o.is_primary, o.sort_order
  from public.product_option_links o where o.product_id = v_source.id;

  insert into public.product_metal_media (
    product_id, metal_id, image_1_path, image_2_path, image_3_path,
    image_4_path, video_path, is_default_fallback
  )
  select
    v_new_product.id, m.metal_id, m.image_1_path, m.image_2_path, m.image_3_path,
    m.image_4_path, m.video_path, m.is_default_fallback
  from public.product_metal_media m where m.product_id = v_source.id;

  for v_old_purity in
    select p.* from public.product_purity_prices p
    where p.product_id = v_source.id order by p.sort_order, p.id
  loop
    insert into public.product_purity_prices (
      product_id, purity_label, price, compare_at_price, sort_order
    ) values (
      v_new_product.id, v_old_purity.purity_label, v_old_purity.price,
      v_old_purity.compare_at_price, v_old_purity.sort_order
    ) returning id into v_new_purity_id;

    if v_old_purity.id = v_source.default_purity_price_id then
      update public.products
      set default_purity_price_id = v_new_purity_id
      where id = v_new_product.id;
    end if;
  end loop;

  insert into public.product_variant_media_items (
    product_id, variant_id, media_type, media_path, sort_order, is_default_fallback, alt_text
  )
  select
    v_new_product.id, null, m.media_type, m.media_path,
    m.sort_order, m.is_default_fallback, m.alt_text
  from public.product_variant_media_items m
  where m.product_id = v_source.id and m.variant_id is null;

  for v_old_variant in
    select v.* from public.product_metal_variants v
    where v.product_id = v_source.id order by v.sort_order, v.id
  loop
    insert into public.product_metal_variants (
      product_id, metal_id, price, is_default, sort_order
    ) values (
      v_new_product.id, v_old_variant.metal_id, v_old_variant.price,
      v_old_variant.is_default, v_old_variant.sort_order
    ) returning id into v_new_variant_id;

    insert into public.product_variant_media_items (
      product_id, variant_id, media_type, media_path, sort_order, is_default_fallback, alt_text
    )
    select
      v_new_product.id, v_new_variant_id, m.media_type, m.media_path,
      m.sort_order, m.is_default_fallback, m.alt_text
    from public.product_variant_media_items m
    where m.product_id = v_source.id and m.variant_id = v_old_variant.id;
  end loop;

  insert into public.product_faq_items (
    product_id, question, answer, sort_order, is_active, source
  )
  select v_new_product.id, f.question, f.answer, f.sort_order, f.is_active, f.source
  from public.product_faq_items f where f.product_id = v_source.id;

  update public.product_duplicate_requests
  set new_product_id = v_new_product.id, completed_at = now()
  where request_id = p_request_id;

  return query
  select v_new_product.id, v_new_product.slug, coalesce(v_new_product.product_lane, 'standard');
end;
$function$

CREATE OR REPLACE FUNCTION public.navbar_item_save_v1(p_actor_id uuid, p_request_id uuid, p_expected_revision text, p_item_id uuid, p_item jsonb, p_sections jsonb, p_links jsonb, p_source_items jsonb, p_featured_card jsonb, p_deleted_section_ids uuid[], p_deleted_link_ids uuid[], p_deleted_source_item_ids bigint[], p_deleted_featured_card_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_snapshot jsonb; v_row jsonb; v_section_ids jsonb := '{}'::jsonb; v_section_id uuid; v_id uuid; v_source_id bigint; v_hash text;
begin
  -- This function is executable only by service_role. The route has already
  -- authenticated the browser user, and this check keeps the audit actor an
  -- existing admin without incorrectly comparing it to service_role's JWT.
  if not exists (select 1 from public.profiles profile where profile.id=p_actor_id and profile.role='admin') then
    raise exception 'Forbidden.' using errcode='42501';
  end if;
  if jsonb_typeof(p_item)<>'object' or jsonb_typeof(p_sections)<>'array' or jsonb_typeof(p_links)<>'array' or jsonb_typeof(p_source_items)<>'array' or jsonb_typeof(p_featured_card)<>'object' then raise exception 'Invalid navbar item payload.' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('navbar-item:'||p_item_id::text, 0));
  v_hash := md5(jsonb_build_object('item',p_item,'sections',p_sections,'links',p_links,'source_items',p_source_items,'featured_card',p_featured_card,'deleted_sections',p_deleted_section_ids,'deleted_links',p_deleted_link_ids,'deleted_sources',p_deleted_source_item_ids,'deleted_cards',p_deleted_featured_card_ids)::text);
  select result into v_snapshot from public.cms_save_receipts where actor_id=p_actor_id and request_id=p_request_id and operation='navbar-item-save';
  if found then
    if (select payload_hash from public.cms_save_receipts where actor_id=p_actor_id and request_id=p_request_id and operation='navbar-item-save') <> v_hash then raise exception 'Request ID was reused.' using errcode='22023'; end if;
    return v_snapshot;
  end if;
  v_snapshot := public.navbar_item_snapshot_v1(p_item_id);
  if v_snapshot->>'revision' <> p_expected_revision then raise exception 'This navbar item changed after it was opened.' using errcode = 'PT409'; end if;
  if p_item->>'id' <> p_item_id::text or not exists(select 1 from public.navbar_items where id=p_item_id) then raise exception 'Invalid navbar item.' using errcode='22023'; end if;
  if exists(select 1 from unnest(p_deleted_section_ids) as deleted(row_id) where not exists(select 1 from public.navbar_sections s where s.id=deleted.row_id and s.navbar_item_id=p_item_id))
    or exists(select 1 from unnest(p_deleted_link_ids) as deleted(row_id) where not exists(select 1 from public.navbar_section_links l join public.navbar_sections s on s.id=l.section_id where l.id=deleted.row_id and s.navbar_item_id=p_item_id))
    or exists(select 1 from unnest(p_deleted_source_item_ids) as deleted(row_id) where not exists(select 1 from public.navbar_section_source_items x join public.navbar_sections s on s.id=x.section_id where x.id=deleted.row_id and s.navbar_item_id=p_item_id))
    or exists(select 1 from unnest(p_deleted_featured_card_ids) as deleted(row_id) where not exists(select 1 from public.navbar_featured_cards f where f.id=deleted.row_id and f.navbar_item_id=p_item_id)) then raise exception 'A deleted row belongs to another navbar item.' using errcode='22023'; end if;
  update public.navbar_items set label=trim(p_item->>'label'), slug=trim(p_item->>'slug'), item_type=(jsonb_populate_record(null::public.navbar_items,p_item)).item_type, linked_category_id=nullif(p_item->>'linked_category_id','')::uuid, direct_link_url=nullif(trim(p_item->>'direct_link_url'),''), status=(jsonb_populate_record(null::public.navbar_items,p_item)).status, updated_at=now() where id=p_item_id;
  delete from public.navbar_section_source_items where id=any(p_deleted_source_item_ids) or section_id=any(p_deleted_section_ids);
  delete from public.navbar_section_links where id=any(p_deleted_link_ids) or section_id=any(p_deleted_section_ids);
  delete from public.navbar_sections where id=any(p_deleted_section_ids) and navbar_item_id=p_item_id;
  delete from public.navbar_featured_cards where id=any(p_deleted_featured_card_ids) and navbar_item_id=p_item_id;
  for v_row in select value from jsonb_array_elements(p_sections) loop
    v_id:=nullif(v_row->>'id','')::uuid;
    if v_id is not null and not exists(select 1 from public.navbar_sections where id=v_id and navbar_item_id=p_item_id) then raise exception 'A section belongs to another navbar item.' using errcode='22023'; end if;
    if v_id is null then insert into public.navbar_sections(navbar_item_id,title,icon_svg_path,section_type,source_subcategory_id,source_category_slug,enable_category_link,linked_category_id,column_number,show_as_filter,display_order,status) values(p_item_id,trim(v_row->>'title'),nullif(v_row->>'icon_svg_path',''),(jsonb_populate_record(null::public.navbar_sections,v_row)).section_type,nullif(v_row->>'source_subcategory_id','')::uuid,nullif(v_row->>'source_category_slug',''),coalesce((v_row->>'enable_category_link')::boolean,false),nullif(v_row->>'linked_category_id','')::uuid,(v_row->>'column_number')::integer,coalesce((v_row->>'show_as_filter')::boolean,false),(v_row->>'display_order')::integer,(jsonb_populate_record(null::public.navbar_sections,v_row)).status) returning id into v_section_id;
    else v_section_id:=v_id; update public.navbar_sections set title=trim(v_row->>'title'),icon_svg_path=nullif(v_row->>'icon_svg_path',''),section_type=(jsonb_populate_record(null::public.navbar_sections,v_row)).section_type,source_subcategory_id=nullif(v_row->>'source_subcategory_id','')::uuid,source_category_slug=nullif(v_row->>'source_category_slug',''),enable_category_link=coalesce((v_row->>'enable_category_link')::boolean,false),linked_category_id=nullif(v_row->>'linked_category_id','')::uuid,column_number=(v_row->>'column_number')::integer,show_as_filter=coalesce((v_row->>'show_as_filter')::boolean,false),display_order=(v_row->>'display_order')::integer,status=(jsonb_populate_record(null::public.navbar_sections,v_row)).status,updated_at=now() where id=v_id; end if;
    v_section_ids:=v_section_ids||jsonb_build_object(v_row->>'key',v_section_id::text);
  end loop;
  for v_row in select value from jsonb_array_elements(p_links) loop
    v_section_id:=nullif(v_section_ids->>(v_row->>'section_key'),'')::uuid; v_id:=nullif(v_row->>'id','')::uuid;
    if v_section_id is null then raise exception 'Invalid navbar link section.' using errcode='22023'; end if;
    if v_id is null then insert into public.navbar_section_links(section_id,label,url,display_order,status) values(v_section_id,trim(v_row->>'label'),trim(v_row->>'url'),(v_row->>'display_order')::integer,(jsonb_populate_record(null::public.navbar_section_links,v_row)).status); else update public.navbar_section_links set section_id=v_section_id,label=trim(v_row->>'label'),url=trim(v_row->>'url'),display_order=(v_row->>'display_order')::integer,status=(jsonb_populate_record(null::public.navbar_section_links,v_row)).status,updated_at=now() where id=v_id and exists(select 1 from public.navbar_sections s where s.id=navbar_section_links.section_id and s.navbar_item_id=p_item_id); end if;
  end loop;
  for v_row in select value from jsonb_array_elements(p_source_items) loop
    v_section_id:=nullif(v_section_ids->>(v_row->>'section_key'),'')::uuid; v_source_id:=nullif(v_row->>'id','')::bigint;
    if v_section_id is null then raise exception 'Invalid navbar source section.' using errcode='22023'; end if;
    if v_source_id is null then insert into public.navbar_section_source_items(section_id,source_kind,source_item_id,sort_order,is_active) values(v_section_id,v_row->>'source_kind',v_row->>'source_item_id',(v_row->>'sort_order')::integer,(v_row->>'is_active')::boolean); else update public.navbar_section_source_items set section_id=v_section_id,source_kind=v_row->>'source_kind',source_item_id=v_row->>'source_item_id',sort_order=(v_row->>'sort_order')::integer,is_active=(v_row->>'is_active')::boolean where id=v_source_id and exists(select 1 from public.navbar_sections s where s.id=navbar_section_source_items.section_id and s.navbar_item_id=p_item_id); end if;
  end loop;
  if p_item->>'item_type' = 'mega_menu' then
    v_id:=nullif(p_featured_card->>'id','')::uuid;
    if v_id is null then insert into public.navbar_featured_cards(navbar_item_id,image_path,image_alt,button_label,button_url,enabled) values(p_item_id,nullif(p_featured_card->>'image_path',''),nullif(p_featured_card->>'image_alt',''),nullif(p_featured_card->>'button_label',''),nullif(p_featured_card->>'button_url',''),coalesce((p_featured_card->>'enabled')::boolean,false)); else update public.navbar_featured_cards set image_path=nullif(p_featured_card->>'image_path',''),image_alt=nullif(p_featured_card->>'image_alt',''),button_label=nullif(p_featured_card->>'button_label',''),button_url=nullif(p_featured_card->>'button_url',''),enabled=coalesce((p_featured_card->>'enabled')::boolean,false),updated_at=now() where id=v_id and navbar_item_id=p_item_id; end if;
  end if;
  v_snapshot:=public.navbar_item_snapshot_v1(p_item_id);
  insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'navbar-item-save',v_hash,v_snapshot);
  return v_snapshot;
end; $function$

CREATE OR REPLACE FUNCTION public.navbar_save_v1(p_actor_id uuid, p_request_id uuid, p_expected_revision text, p_items jsonb, p_sections jsonb, p_links jsonb, p_source_items jsonb, p_featured_cards jsonb, p_deleted_section_ids uuid[] DEFAULT '{}'::uuid[], p_deleted_link_ids uuid[] DEFAULT '{}'::uuid[], p_deleted_source_item_ids bigint[] DEFAULT '{}'::bigint[], p_deleted_featured_card_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_before jsonb;
  v_result jsonb;
  v_receipt public.cms_save_receipts%rowtype;
  v_hash text;
  v_row jsonb;
  v_id uuid;
  v_bigint_id bigint;
  v_parent_id uuid;
  v_key text;
  v_item_ids jsonb := '{}'::jsonb;
  v_section_ids jsonb := '{}'::jsonb;
begin
  if p_actor_id is null or p_request_id is null or not exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin') then
    raise exception 'Administrator access is required.' using errcode='42501';
  end if;
  if coalesce(p_expected_revision,'') !~ '^[0-9a-f]{32}$'
     or jsonb_typeof(p_items) is distinct from 'array'
     or jsonb_typeof(p_sections) is distinct from 'array'
     or jsonb_typeof(p_links) is distinct from 'array'
     or jsonb_typeof(p_source_items) is distinct from 'array'
     or jsonb_typeof(p_featured_cards) is distinct from 'array' then
    raise exception 'Invalid navbar save payload. Reload the editor.' using errcode='22023';
  end if;
  if cardinality(p_deleted_section_ids)<>cardinality(array(select distinct x from unnest(p_deleted_section_ids)x))
     or cardinality(p_deleted_link_ids)<>cardinality(array(select distinct x from unnest(p_deleted_link_ids)x))
     or cardinality(p_deleted_source_item_ids)<>cardinality(array(select distinct x from unnest(p_deleted_source_item_ids)x))
     or cardinality(p_deleted_featured_card_ids)<>cardinality(array(select distinct x from unnest(p_deleted_featured_card_ids)x)) then
    raise exception 'Deleted navbar IDs must be unique.' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('navbar-builder',0));
  perform pg_advisory_xact_lock(hashtextextended('navbar-request:'||p_actor_id||':'||p_request_id,0));
  v_hash:=md5(jsonb_build_object('revision',p_expected_revision,'items',p_items,'sections',p_sections,'links',p_links,'source_items',p_source_items,'featured_cards',p_featured_cards,'deleted_sections',p_deleted_section_ids,'deleted_links',p_deleted_link_ids,'deleted_source_items',p_deleted_source_item_ids,'deleted_featured_cards',p_deleted_featured_card_ids)::text);
  select r.* into v_receipt from public.cms_save_receipts r where r.actor_id=p_actor_id and r.request_id=p_request_id;
  if found then
    if v_receipt.operation<>'navbar-save' or v_receipt.payload_hash<>v_hash then
      raise exception 'This save request was already used for different changes.' using errcode = 'PT409';
    end if;
    return v_receipt.result;
  end if;

  v_before:=public.navbar_snapshot_v1();
  if v_before->>'revision'<>p_expected_revision then
    raise exception 'The navbar changed since you opened it. Reload before saving.' using errcode = 'PT409';
  end if;

  if exists(select 1 from jsonb_array_elements(p_items)x group by x->>'key' having count(*)>1)
     or exists(select 1 from jsonb_array_elements(p_sections)x group by x->>'key' having count(*)>1)
     or exists(select 1 from jsonb_array_elements(p_items)x where nullif(trim(x->>'key'),'') is null)
     or exists(select 1 from jsonb_array_elements(p_sections)x where nullif(trim(x->>'key'),'') is null) then
    raise exception 'Navbar client keys must be present and unique.' using errcode='22023';
  end if;

  -- Every persisted row must be present or explicitly deleted. This prevents stale or partial clients from erasing data.
  if exists(select 1 from public.navbar_items x where not exists(select 1 from jsonb_array_elements(p_items)i where nullif(i->>'id','')::uuid=x.id)) then
    raise exception 'Navbar items cannot be removed by this editor.' using errcode='22023';
  end if;
  if exists(select 1 from public.navbar_sections x where not(x.id=any(p_deleted_section_ids)) and not exists(select 1 from jsonb_array_elements(p_sections)i where nullif(i->>'id','')::uuid=x.id)) then
    raise exception 'Navbar sections may only be removed explicitly.' using errcode='22023';
  end if;
  if exists(select 1 from public.navbar_section_links x where not(x.id=any(p_deleted_link_ids)) and not exists(select 1 from jsonb_array_elements(p_links)i where nullif(i->>'id','')::uuid=x.id)) then
    raise exception 'Navbar links may only be removed explicitly.' using errcode='22023';
  end if;
  if exists(select 1 from public.navbar_section_source_items x where not(x.id=any(p_deleted_source_item_ids)) and not exists(select 1 from jsonb_array_elements(p_source_items)i where nullif(i->>'id','')::bigint=x.id)) then
    raise exception 'Navbar source items may only be removed explicitly.' using errcode='22023';
  end if;
  if exists(select 1 from public.navbar_featured_cards x where not(x.id=any(p_deleted_featured_card_ids)) and not exists(select 1 from jsonb_array_elements(p_featured_cards)i where nullif(i->>'id','')::uuid=x.id)) then
    raise exception 'Navbar featured cards may only be removed explicitly.' using errcode='22023';
  end if;

  -- Reject unknown, duplicated, or conflicting persistent IDs before changing anything.
  if exists(select 1 from jsonb_array_elements(p_items)x where nullif(x->>'id','') is not null and not exists(select 1 from public.navbar_items t where t.id=(x->>'id')::uuid))
     or exists(select 1 from jsonb_array_elements(p_sections)x where nullif(x->>'id','') is not null and not exists(select 1 from public.navbar_sections t where t.id=(x->>'id')::uuid))
     or exists(select 1 from jsonb_array_elements(p_links)x where nullif(x->>'id','') is not null and not exists(select 1 from public.navbar_section_links t where t.id=(x->>'id')::uuid))
     or exists(select 1 from jsonb_array_elements(p_source_items)x where nullif(x->>'id','') is not null and not exists(select 1 from public.navbar_section_source_items t where t.id=(x->>'id')::bigint))
     or exists(select 1 from jsonb_array_elements(p_featured_cards)x where nullif(x->>'id','') is not null and not exists(select 1 from public.navbar_featured_cards t where t.id=(x->>'id')::uuid)) then
    raise exception 'The navbar payload contains an unknown row ID.' using errcode='22023';
  end if;
  if exists(select 1 from jsonb_array_elements(p_items)x where nullif(x->>'id','') is not null group by x->>'id' having count(*)>1)
     or exists(select 1 from jsonb_array_elements(p_sections)x where nullif(x->>'id','') is not null group by x->>'id' having count(*)>1)
     or exists(select 1 from jsonb_array_elements(p_links)x where nullif(x->>'id','') is not null group by x->>'id' having count(*)>1)
     or exists(select 1 from jsonb_array_elements(p_source_items)x where nullif(x->>'id','') is not null group by x->>'id' having count(*)>1)
     or exists(select 1 from jsonb_array_elements(p_featured_cards)x where nullif(x->>'id','') is not null group by x->>'id' having count(*)>1) then
    raise exception 'Navbar row IDs must be unique.' using errcode='22023';
  end if;
  if exists(
    select 1 from jsonb_array_elements(p_source_items) source
    join jsonb_array_elements(p_sections) section on section->>'key'=source->>'section_key'
    where case section->>'section_type'
      when 'category_list' then source->>'source_kind'<>'subcategory_option'
      when 'metal_swatches' then source->>'source_kind'<>'metal'
      when 'stone_shapes' then source->>'source_kind'<>'stone_shape'
      when 'ring_sizes' then source->>'source_kind'<>'ring_size'
      when 'certificates' then source->>'source_kind'<>'certificate'
      when 'styles' then source->>'source_kind'<>'style'
      else true
    end
  ) then
    raise exception 'A navbar source item does not match its section type.' using errcode='22023';
  end if;

  delete from public.navbar_section_source_items where id=any(p_deleted_source_item_ids) or section_id=any(p_deleted_section_ids);
  delete from public.navbar_section_links where id=any(p_deleted_link_ids) or section_id=any(p_deleted_section_ids);
  delete from public.navbar_sections where id=any(p_deleted_section_ids);
  delete from public.navbar_featured_cards where id=any(p_deleted_featured_card_ids);

  for v_row in select * from jsonb_array_elements(p_items) loop
    v_key:=v_row->>'key'; v_id:=nullif(v_row->>'id','')::uuid;
    if nullif(trim(v_row->>'label'),'') is null or nullif(trim(v_row->>'slug'),'') is null or v_row->>'item_type' not in ('mega_menu','direct_link') or v_row->>'status' not in ('active','hidden') then
      raise exception 'Invalid navbar item.' using errcode='22023';
    end if;
    if nullif(v_row->>'linked_category_id','') is not null and not exists(select 1 from public.catalog_categories c where c.id=(v_row->>'linked_category_id')::uuid) then
      raise exception 'A navbar item references a missing category.' using errcode='23503';
    end if;
    if v_id is null then
      insert into public.navbar_items(label,slug,item_type,linked_category_id,direct_link_url,display_order,status)
      values(trim(v_row->>'label'),trim(v_row->>'slug'),(jsonb_populate_record(null::public.navbar_items,v_row)).item_type,nullif(v_row->>'linked_category_id','')::uuid,nullif(trim(v_row->>'direct_link_url'),''),(v_row->>'display_order')::integer,(jsonb_populate_record(null::public.navbar_items,v_row)).status)
      returning id into v_id;
    else
      update public.navbar_items set label=trim(v_row->>'label'),slug=trim(v_row->>'slug'),item_type=(jsonb_populate_record(null::public.navbar_items,v_row)).item_type,linked_category_id=nullif(v_row->>'linked_category_id','')::uuid,direct_link_url=nullif(trim(v_row->>'direct_link_url'),''),display_order=(v_row->>'display_order')::integer,status=(jsonb_populate_record(null::public.navbar_items,v_row)).status,updated_at=now()
      where id=v_id and (label,slug,item_type,linked_category_id,direct_link_url,display_order,status) is distinct from (trim(v_row->>'label'),trim(v_row->>'slug'),(jsonb_populate_record(null::public.navbar_items,v_row)).item_type,nullif(v_row->>'linked_category_id','')::uuid,nullif(trim(v_row->>'direct_link_url'),''),(v_row->>'display_order')::integer,(jsonb_populate_record(null::public.navbar_items,v_row)).status);
    end if;
    v_item_ids:=v_item_ids||jsonb_build_object(v_key,v_id::text);
  end loop;

  for v_row in select * from jsonb_array_elements(p_sections) loop
    v_key:=v_row->>'key'; v_id:=nullif(v_row->>'id','')::uuid; v_parent_id:=nullif(v_item_ids->>(v_row->>'item_key'),'')::uuid;
    if v_parent_id is null or nullif(trim(v_row->>'title'),'') is null or v_row->>'section_type' not in ('category_list','manual_links','metal_swatches','stone_shapes','ring_sizes','certificates','category_link','styles') or v_row->>'status' not in ('active','hidden') then
      raise exception 'Invalid navbar section.' using errcode='22023';
    end if;
    if nullif(v_row->>'source_subcategory_id','') is not null and not exists(select 1 from public.catalog_subcategories s where s.id=(v_row->>'source_subcategory_id')::uuid) then raise exception 'A navbar section references a missing subcategory.' using errcode='23503'; end if;
    if nullif(v_row->>'linked_category_id','') is not null and not exists(select 1 from public.catalog_categories c where c.id=(v_row->>'linked_category_id')::uuid) then raise exception 'A navbar section references a missing category.' using errcode='23503'; end if;
    if v_id is null then
      insert into public.navbar_sections(navbar_item_id,title,icon_svg_path,section_type,source_subcategory_id,source_category_slug,enable_category_link,linked_category_id,column_number,show_as_filter,display_order,status)
      values(v_parent_id,trim(v_row->>'title'),nullif(trim(v_row->>'icon_svg_path'),''),(jsonb_populate_record(null::public.navbar_sections,v_row)).section_type,nullif(v_row->>'source_subcategory_id','')::uuid,nullif(trim(v_row->>'source_category_slug'),''),(v_row->>'enable_category_link')::boolean,nullif(v_row->>'linked_category_id','')::uuid,(v_row->>'column_number')::integer,(v_row->>'show_as_filter')::boolean,(v_row->>'display_order')::integer,(jsonb_populate_record(null::public.navbar_sections,v_row)).status) returning id into v_id;
    else
      update public.navbar_sections set navbar_item_id=v_parent_id,title=trim(v_row->>'title'),icon_svg_path=nullif(trim(v_row->>'icon_svg_path'),''),section_type=(jsonb_populate_record(null::public.navbar_sections,v_row)).section_type,source_subcategory_id=nullif(v_row->>'source_subcategory_id','')::uuid,source_category_slug=nullif(trim(v_row->>'source_category_slug'),''),enable_category_link=(v_row->>'enable_category_link')::boolean,linked_category_id=nullif(v_row->>'linked_category_id','')::uuid,column_number=(v_row->>'column_number')::integer,show_as_filter=(v_row->>'show_as_filter')::boolean,display_order=(v_row->>'display_order')::integer,status=(jsonb_populate_record(null::public.navbar_sections,v_row)).status,updated_at=now()
      where id=v_id and (navbar_item_id,title,icon_svg_path,section_type,source_subcategory_id,source_category_slug,enable_category_link,linked_category_id,column_number,show_as_filter,display_order,status) is distinct from (v_parent_id,trim(v_row->>'title'),nullif(trim(v_row->>'icon_svg_path'),''),(jsonb_populate_record(null::public.navbar_sections,v_row)).section_type,nullif(v_row->>'source_subcategory_id','')::uuid,nullif(trim(v_row->>'source_category_slug'),''),(v_row->>'enable_category_link')::boolean,nullif(v_row->>'linked_category_id','')::uuid,(v_row->>'column_number')::integer,(v_row->>'show_as_filter')::boolean,(v_row->>'display_order')::integer,(jsonb_populate_record(null::public.navbar_sections,v_row)).status);
    end if;
    v_section_ids:=v_section_ids||jsonb_build_object(v_key,v_id::text);
  end loop;

  for v_row in select * from jsonb_array_elements(p_links) loop
    v_id:=nullif(v_row->>'id','')::uuid; v_parent_id:=nullif(v_section_ids->>(v_row->>'section_key'),'')::uuid;
    if v_parent_id is null or nullif(trim(v_row->>'label'),'') is null or nullif(trim(v_row->>'url'),'') is null or v_row->>'status' not in ('active','hidden') then raise exception 'Invalid navbar link.' using errcode='22023'; end if;
    if v_id is null then insert into public.navbar_section_links(section_id,label,url,display_order,status) values(v_parent_id,trim(v_row->>'label'),trim(v_row->>'url'),(v_row->>'display_order')::integer,(jsonb_populate_record(null::public.navbar_section_links,v_row)).status);
    else update public.navbar_section_links set section_id=v_parent_id,label=trim(v_row->>'label'),url=trim(v_row->>'url'),display_order=(v_row->>'display_order')::integer,status=(jsonb_populate_record(null::public.navbar_section_links,v_row)).status,updated_at=now() where id=v_id and (section_id,label,url,display_order,status) is distinct from (v_parent_id,trim(v_row->>'label'),trim(v_row->>'url'),(v_row->>'display_order')::integer,(jsonb_populate_record(null::public.navbar_section_links,v_row)).status); end if;
  end loop;

  for v_row in select * from jsonb_array_elements(p_source_items) loop
    v_bigint_id:=nullif(v_row->>'id','')::bigint; v_parent_id:=nullif(v_section_ids->>(v_row->>'section_key'),'')::uuid;
    if v_parent_id is null or v_row->>'source_kind' not in ('subcategory_option','metal','stone_shape','ring_size','certificate','style') or nullif(v_row->>'source_item_id','') is null then raise exception 'Invalid navbar source item.' using errcode='22023'; end if;
    if (v_row->>'source_kind'='subcategory_option' and not exists(select 1 from public.catalog_options x where x.id=(v_row->>'source_item_id')::uuid))
       or (v_row->>'source_kind'='metal' and not exists(select 1 from public.catalog_metals x where x.id=(v_row->>'source_item_id')::uuid))
       or (v_row->>'source_kind'='stone_shape' and not exists(select 1 from public.catalog_stone_shapes x where x.id=(v_row->>'source_item_id')::uuid))
       or (v_row->>'source_kind'='ring_size' and not exists(select 1 from public.catalog_ring_sizes x where x.id=(v_row->>'source_item_id')::uuid))
       or (v_row->>'source_kind'='certificate' and not exists(select 1 from public.catalog_certificates x where x.id=(v_row->>'source_item_id')::uuid))
       or (v_row->>'source_kind'='style' and not exists(select 1 from public.catalog_styles x where x.id=(v_row->>'source_item_id')::uuid)) then raise exception 'A navbar source item references missing catalog data.' using errcode='23503'; end if;
    if v_bigint_id is null then insert into public.navbar_section_source_items(section_id,source_kind,source_item_id,sort_order,is_active) values(v_parent_id,v_row->>'source_kind',v_row->>'source_item_id',(v_row->>'sort_order')::integer,(v_row->>'is_active')::boolean);
    else update public.navbar_section_source_items set section_id=v_parent_id,source_kind=v_row->>'source_kind',source_item_id=v_row->>'source_item_id',sort_order=(v_row->>'sort_order')::integer,is_active=(v_row->>'is_active')::boolean where id=v_bigint_id and (section_id,source_kind,source_item_id,sort_order,is_active) is distinct from (v_parent_id,v_row->>'source_kind',v_row->>'source_item_id',(v_row->>'sort_order')::integer,(v_row->>'is_active')::boolean); end if;
  end loop;

  for v_row in select * from jsonb_array_elements(p_featured_cards) loop
    v_id:=nullif(v_row->>'id','')::uuid; v_parent_id:=nullif(v_item_ids->>(v_row->>'item_key'),'')::uuid;
    if v_parent_id is null then raise exception 'Invalid navbar featured card.' using errcode='22023'; end if;
    if v_id is null then insert into public.navbar_featured_cards(navbar_item_id,image_path,image_alt,button_label,button_url,enabled) values(v_parent_id,nullif(trim(v_row->>'image_path'),''),nullif(trim(v_row->>'image_alt'),''),nullif(trim(v_row->>'button_label'),''),nullif(trim(v_row->>'button_url'),''),(v_row->>'enabled')::boolean);
    else update public.navbar_featured_cards set navbar_item_id=v_parent_id,image_path=nullif(trim(v_row->>'image_path'),''),image_alt=nullif(trim(v_row->>'image_alt'),''),button_label=nullif(trim(v_row->>'button_label'),''),button_url=nullif(trim(v_row->>'button_url'),''),enabled=(v_row->>'enabled')::boolean,updated_at=now() where id=v_id and (navbar_item_id,image_path,image_alt,button_label,button_url,enabled) is distinct from (v_parent_id,nullif(trim(v_row->>'image_path'),''),nullif(trim(v_row->>'image_alt'),''),nullif(trim(v_row->>'button_label'),''),nullif(trim(v_row->>'button_url'),''),(v_row->>'enabled')::boolean); end if;
  end loop;

  v_result:=public.navbar_snapshot_v1();
  insert into public.cms_save_receipts(actor_id,request_id,operation,payload_hash,result) values(p_actor_id,p_request_id,'navbar-save',v_hash,v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.navbar_section_source_item_type_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_section_type public.navbar_section_type;
  v_expected_kind text;
begin
  select section_type into v_section_type from public.navbar_sections where id = new.section_id;
  if not found then raise exception 'Navbar section does not exist.' using errcode = '23503'; end if;

  v_expected_kind := case v_section_type
    when 'category_list' then 'subcategory_option'
    when 'metal_swatches' then 'metal'
    when 'stone_shapes' then 'stone_shape'
    when 'ring_sizes' then 'ring_size'
    when 'certificates' then 'certificate'
    when 'styles' then 'style'
    else null
  end;
  if v_expected_kind is null or new.source_kind <> v_expected_kind then
    raise exception 'Navbar source kind does not match its section type.' using errcode = '23514';
  end if;

  if (new.source_kind = 'subcategory_option' and not exists (select 1 from public.catalog_options item where item.id::text = new.source_item_id))
     or (new.source_kind = 'metal' and not exists (select 1 from public.catalog_metals item where item.id::text = new.source_item_id))
     or (new.source_kind = 'stone_shape' and not exists (select 1 from public.catalog_stone_shapes item where item.id::text = new.source_item_id))
     or (new.source_kind = 'ring_size' and not exists (select 1 from public.catalog_ring_sizes item where item.id::text = new.source_item_id))
     or (new.source_kind = 'certificate' and not exists (select 1 from public.catalog_certificates item where item.id::text = new.source_item_id))
     or (new.source_kind = 'style' and not exists (select 1 from public.catalog_styles item where item.id::text = new.source_item_id)) then
    raise exception 'Navbar source item does not exist.' using errcode = '23503';
  end if;
  return new;
end;
$function$
